import type { TermInput } from "@/lib/schema";

/**
 * Specialist vocabulary found across the site (procedures, pathology, treatment, trial and side-effect jargon).
 * Each name and alias gets an automatic hover tooltip wherever it appears in page text (src/lib/term-hover.tsx),
 * so aliases are the exact spellings and inflections used in the corpus. Fundamentals (cell, gene, stage, grade,
 * hazard ratio, phase 1/2/3) live in terms-basics.ts, not here.
 */

const asOf = "2026-09-09";
const W = (s: string) => `https://en.wikipedia.org/wiki/${s}`;
type T = Omit<TermInput, "kind" | "asOf">;
const t = (x: T): TermInput => ({ kind: "term", asOf, links: x.wikipedia ? [{ label: "Wikipedia", url: x.wikipedia }] : undefined, ...x });

export const termsJargon: TermInput[] = [
  // ---- Procedures ----
  t({ id: "oesophagectomy", name: "Oesophagectomy", category: "Procedures", aka: ["esophagectomy", "oesophagectomies", "Ivor Lewis"], tldr: "Surgery that removes most of the food pipe (oesophagus) and rebuilds it by pulling the stomach up into the chest.", summary: "The standard curative operation for oesophageal and junctional cancer, usually after chemoradiation (CROSS) or perioperative chemotherapy (FLOT). Approaches include Ivor Lewis (abdomen plus right chest), McKeown (three-field) and transhiatal; minimally invasive and robotic versions reduce pulmonary complications. It is one of the highest-risk cancer operations, with 2-5% mortality even in expert centres and lasting effects on eating, reflux and weight, which is why outcomes are better in centralised high-volume units and why active surveillance after complete response (SANO) is being tested as an alternative.", wikipedia: W("Esophagectomy"), cancers: ["esophageal", "gastric"], trials: ["cross", "sano"], related: ["centralisation", "surgical-morbidity", "dysphagia"], sections: ["surgery"] }),
  t({ id: "whipple", name: "Whipple procedure (pancreaticoduodenectomy)", category: "Procedures", aka: ["Whipple", "pancreatoduodenectomy", "pancreatic resection"], tldr: "The big operation for cancers of the head of the pancreas: the surgeon removes the pancreatic head, the duodenum, the gallbladder and part of the bile duct, then reconnects everything.", summary: "Named after Allen Whipple (1935), it is the only curative option for pancreatic head, distal bile duct and ampullary cancers, and is offered only when imaging shows the tumour can be fully removed (resectable or borderline resectable after neoadjuvant therapy). It takes 5-8 hours, carries 2-4% mortality and 30-40% major complication rates (pancreatic fistula, delayed gastric emptying), and most patients need enzyme supplements afterwards. Distal pancreatectomy removes the tail instead. Neoadjuvant chemotherapy (FOLFIRINOX) and RAS inhibitors are increasing the share of patients who reach an R0 resection.", wikipedia: W("Pancreaticoduodenectomy"), cancers: ["pancreatic", "cholangiocarcinoma"], related: ["resection-margins", "resectability", "surgical-morbidity"], sections: ["surgery"] }),
  t({ id: "lobectomy", name: "Lobectomy", category: "Procedures", aka: ["lobectomies", "pulmonary lobectomy"], tldr: "Removing one lobe of the lung (the right lung has three, the left two). The standard operation for early lung cancer.", summary: "Lobectomy with mediastinal lymph node sampling is the reference treatment for stage I-II non-small-cell lung cancer, usually done by video-assisted (VATS) or robotic surgery through small incisions. Five-year survival is 70-90% for stage I. For small peripheral tumours (≤2 cm) segmentectomy proved non-inferior (JCOG0802, CALGB 140503), and SBRT is the alternative for patients too frail to operate. Perioperative chemo-immunotherapy or adjuvant osimertinib (ADAURA) now follows in many patients. Thyroid and liver lobectomies use the same word for a different organ.", wikipedia: W("Lobectomy_(lung)"), cancers: ["nsclc"], trials: ["adaura"], technologies: ["sbrt", "robotic-surgery"], related: ["segmentectomy", "pneumonectomy"], sections: ["surgery"] }),
  t({ id: "segmentectomy", name: "Segmentectomy (sublobar resection)", category: "Procedures", aka: ["sublobar resection", "wedge resection", "segmentectomies"], tldr: "Removing only a segment or wedge of a lung lobe rather than the whole lobe, sparing breathing capacity.", summary: "Once reserved for patients who could not tolerate lobectomy, anatomical segmentectomy became a standard option for peripheral tumours ≤2 cm after JCOG0802 (2022) showed better overall survival and CALGB 140503 showed non-inferior disease-free survival. Wedge resection is a non-anatomical version with less lymph node clearance. The same lung-sparing logic drives lung-sparing surgery in mesothelioma and parenchyma-sparing liver resection.", wikipedia: W("Segmental_resection"), cancers: ["nsclc"], related: ["lobectomy"], sections: ["surgery"] }),
  t({ id: "pneumonectomy", name: "Pneumonectomy", category: "Procedures", aka: ["extrapleural pneumonectomy", "pneumonectomies"], tldr: "Removing an entire lung. Now rare in cancer surgery because the cost in breathing capacity is high.", summary: "Used for central lung tumours that cannot be cleared by lobectomy or sleeve resection. Extrapleural pneumonectomy (lung, pleura, diaphragm and pericardium) was tried for mesothelioma but the MARS 1 trial suggested harm and practice shifted to lung-sparing pleurectomy/decortication, itself questioned by MARS 2. Mortality is 5-10%, and long-term cardiopulmonary limitation is common.", wikipedia: W("Pneumonectomy"), cancers: ["nsclc", "mesothelioma"], trials: ["mars-2"], related: ["lobectomy", "pleura"], sections: ["surgery"] }),
  t({ id: "cystectomy", name: "Radical cystectomy", category: "Procedures", aka: ["cystectomy", "cystectomies"], tldr: "Removing the bladder (and nearby organs) for bladder cancer that has grown into the muscle wall; urine is then diverted through a stoma or a new bladder made of bowel.", summary: "The standard for muscle-invasive bladder cancer (MIBC), preceded by cisplatin-based neoadjuvant chemotherapy or, since NIAGARA, chemo-immunotherapy. Reconstruction uses an ileal conduit (external bag) or an orthotopic neobladder. It is a major operation with 60% complication rates and a permanent change to daily life, so bladder-sparing trimodality therapy (TURBT plus chemoradiation) and, for patients with complete response to enfortumab vedotin plus pembrolizumab, bladder preservation trials are active alternatives.", wikipedia: W("Cystectomy"), cancers: ["urothelial"], trials: ["niagara"], related: ["turbt", "stoma", "nmibc-vs-mibc", "organ-preservation"], sections: ["surgery"] }),
  t({ id: "nephrectomy", name: "Nephrectomy", category: "Procedures", aka: ["partial nephrectomy", "radical nephrectomy", "cytoreductive nephrectomy", "nephrectomies"], tldr: "Removing a kidney (radical) or just the tumour-bearing part of it (partial).", summary: "Partial nephrectomy, usually robotic, is preferred for small renal masses because it preserves kidney function with equal cancer control; radical nephrectomy is for larger or central tumours. Cytoreductive nephrectomy (removing the kidney despite metastases) lost its routine role after CARMENA in the targeted-therapy era but is used selectively after response to immunotherapy. Adjuvant pembrolizumab (KEYNOTE-564) follows resection of high-risk disease.", wikipedia: W("Nephrectomy"), cancers: ["rcc"], technologies: ["robotic-surgery", "thermal-ablation"], related: ["active-surveillance", "debulking"], sections: ["surgery"] }),
  t({ id: "mastectomy", name: "Mastectomy", category: "Procedures", aka: ["mastectomies", "risk-reducing mastectomy", "prophylactic mastectomy", "nipple-sparing mastectomy"], tldr: "Removing the whole breast, either for cancer or preventively in BRCA1/2 carriers, where bilateral risk-reducing mastectomy cuts breast cancer risk by 90% or more. For most early cancers, lumpectomy plus radiotherapy works as well, so mastectomy is chosen for large or multicentric tumours, inflammatory cancer, or patient preference.", summary: "Total mastectomy removes breast tissue; modified radical adds axillary nodes; skin- and nipple-sparing variants allow immediate reconstruction with implants or the patient's own tissue. For most early cancers, lumpectomy plus radiotherapy gives identical survival (NSABP B-06, Milan trials), so mastectomy is chosen for large or multicentric tumours, inflammatory cancer, or patient preference. Bilateral risk-reducing mastectomy cuts breast cancer risk by 90% or more in BRCA1/2 carriers.", wikipedia: W("Mastectomy"), cancers: ["breast-hr-positive", "breast-her2-positive", "tnbc"], targets: ["brca"], related: ["lumpectomy", "sentinel-lymph-node-biopsy", "gbrca-mutation"], sections: ["surgery"] }),
  t({ id: "lumpectomy", name: "Lumpectomy (breast-conserving surgery)", category: "Procedures", aka: ["breast-conserving", "breast-conserving surgery", "breast conservation", "wide excision"], tldr: "Removing only the tumour with a rim of normal breast, keeping the breast; almost always followed by radiotherapy.", summary: "Pioneered by Veronesi and Fisher, breast conservation plus whole-breast radiotherapy matches mastectomy for survival with better body image. Margins are checked by the pathologist ('no ink on tumour' suffices for invasive cancer); re-excision is needed in 10-20%. Hypofractionated (FAST-Forward, 5 fractions) and partial-breast radiotherapy have shortened the course. Neoadjuvant therapy can shrink tumours enough to convert mastectomy candidates to lumpectomy.", wikipedia: W("Lumpectomy"), cancers: ["breast-hr-positive", "breast-her2-positive", "tnbc"], related: ["mastectomy", "resection-margins", "hypofractionation"], sections: ["surgery", "radiation"] }),
  t({ id: "sentinel-lymph-node-biopsy", name: "Sentinel node biopsy", category: "Procedures", aka: ["sentinel lymph node biopsy", "sentinel lymph node", "sentinel node", "sentinel lymph node mapping", "SLNB"], tldr: "Finding and removing the first one or two lymph nodes a tumour drains to, to see whether cancer has spread, instead of removing the whole nodal basin.", summary: "A dye or radioactive tracer (technetium tilmanocept, indocyanine green, blue dye) injected at the tumour travels to the 'sentinel' node, which is removed and examined. If it is clear, the remaining nodes are almost certainly clear and a full dissection with its lymphoedema risk is avoided. Standard in breast cancer, melanoma (from ~0.8 mm Breslow), endometrial and vulval cancers and increasingly oral cavity cancer; even positive sentinel nodes often no longer trigger full axillary dissection (Z0011, SENOMAC).", wikipedia: W("Sentinel_lymph_node"), technologies: ["sentinel-node", "fluorescence-guided-surgery"], related: ["lymphadenectomy", "lymph-node-status", "tilmanocept-tc99m"], sections: ["surgery"] }),
  t({ id: "lymphadenectomy", name: "Lymphadenectomy (lymph node dissection)", category: "Procedures", aka: ["lymph node dissection", "nodal dissection", "axillary dissection", "axillary lymph node dissection", "neck dissection", "D2 lymphadenectomy", "D2 dissection", "pelvic lymph node dissection", "retroperitoneal lymph node dissection", "mediastinal node dissection", "lymph node sampling"], tldr: "Surgically removing the lymph nodes that drain a tumour, both to stage the cancer and to clear any spread.", summary: "The extent is organ-specific: D2 gastrectomy removes perigastric and regional nodes; axillary dissection clears levels I-II for breast cancer; neck dissection is graded by levels for head and neck cancer; retroperitoneal dissection is used in testicular cancer. It improves staging accuracy (and so adjuvant decisions) and sometimes cure, at the cost of lymphoedema, nerve injury and longer surgery. Sentinel node biopsy has replaced it wherever a negative sentinel node is reliable.", wikipedia: W("Lymphadenectomy"), related: ["sentinel-lymph-node-biopsy", "lymph-node-status", "gastrectomy"], sections: ["surgery"] }),
  t({ id: "gastrectomy", name: "Gastrectomy", category: "Procedures", aka: ["total gastrectomy", "subtotal gastrectomy", "gastrectomies"], tldr: "Removing part (subtotal) or all (total) of the stomach for stomach cancer, with the bowel joined to what remains.", summary: "Curative surgery for localised gastric cancer, combined with D2 lymphadenectomy and perioperative FLOT chemotherapy in the West or adjuvant chemotherapy in East Asia, where screening finds earlier disease and endoscopic resection can cure tumours confined to the mucosa. Laparoscopic and robotic approaches are standard in Korea and Japan (KLASS, JCOG trials). Consequences include small-meal eating, dumping, vitamin B12 deficiency and weight loss, hence the drive to avoid palliative gastrectomy in metastatic disease.", wikipedia: W("Gastrectomy"), cancers: ["gastric", "early-gastric-cancer", "esophageal"], related: ["lymphadenectomy", "endoscopic-resection", "flot"], sections: ["surgery"] }),
  t({ id: "colectomy", name: "Colectomy", category: "Procedures", aka: ["hemicolectomy", "right hemicolectomy", "left hemicolectomy", "segmental colectomy", "colectomies"], tldr: "Removing the part of the colon containing the cancer along with its blood supply and lymph nodes, then joining the ends.", summary: "Right or left hemicolectomy removes the affected half of the colon; the bowel is usually reconnected without a permanent stoma. Laparoscopic colectomy is oncologically equivalent to open surgery (COST, CLASICC). At least 12 nodes should be examined for accurate staging; adjuvant FOLFOX or CAPOX follows for stage III and high-risk stage II, increasingly guided by ctDNA (DYNAMIC, CIRCULATE). Rectal cancer uses different operations (total mesorectal excision, abdominoperineal resection).", wikipedia: W("Colectomy"), cancers: ["colorectal"], trials: ["dynamic", "circulate-japan"], related: ["total-mesorectal-excision", "abdominoperineal-resection", "folfox-family"], sections: ["surgery"] }),
  t({ id: "total-mesorectal-excision", name: "Total mesorectal excision (TME)", category: "Procedures", aka: ["mesorectal excision", "low anterior resection", "anterior resection", "TME surgery"], tldr: "The standard rectal cancer operation: the rectum is removed together with its surrounding fatty envelope (the mesorectum) in one intact package, which is where local recurrences used to come from.", summary: "Introduced by Bill Heald in the 1980s, TME cut local recurrence from 20-30% to under 10% and remains the technical benchmark. Low anterior resection preserves the anal sphincter with an anastomosis (often with a temporary ileostomy); abdominoperineal resection is needed when the tumour involves the sphincter. Robotic and transanal TME are alternatives in narrow pelvises. Total neoadjuvant therapy and watch-and-wait for complete responders aim to avoid TME altogether in selected patients.", wikipedia: W("Total_mesorectal_excision"), cancers: ["colorectal", "rectal-cancer"], related: ["abdominoperineal-resection", "organ-preservation", "total-neoadjuvant-therapy"], sections: ["surgery"] }),
  t({ id: "abdominoperineal-resection", name: "Abdominoperineal resection", category: "Procedures", aka: ["abdominoperineal", "abdomino-perineal resection", "salvage APR"], tldr: "Removing the rectum and anus together, leaving a permanent colostomy. Used when a low rectal or anal cancer involves the sphincter.", summary: "The operation through both the abdomen and the perineum removes rectum, anal canal and sphincters, so a permanent end colostomy is unavoidable. For anal squamous cancer it is reserved as salvage after definitive chemoradiation (the Nigro regimen) fails; for low rectal cancers it is being displaced by sphincter-preserving TME, intersphincteric resection and organ-preservation strategies. Perineal wound problems are common and flap reconstruction is often needed.", wikipedia: W("Abdominoperineal_resection"), cancers: ["colorectal"], related: ["total-mesorectal-excision", "stoma", "chemoradiation"], sections: ["surgery"] }),
  t({ id: "hepatectomy", name: "Hepatectomy (liver resection)", category: "Procedures", aka: ["liver resection", "partial hepatectomy", "hemihepatectomy", "hepatic resection", "metastasectomy"], tldr: "Cutting out the part of the liver containing tumour. The liver regrows, so up to 70% can be removed if what remains is healthy.", summary: "Used for hepatocellular carcinoma in patients with preserved liver function (Child-Pugh A, no portal hypertension), for cholangiocarcinoma, and for colorectal liver metastases, where resection gives 5-year survival of 40-50% and is the only curative option. Portal vein embolisation or two-stage hepatectomy grows the future liver remnant before surgery; ablation handles small lesions. Anatomical segments (Couinaud) define the resection; a margin of even 1 mm is acceptable in metastases.", wikipedia: W("Hepatectomy"), cancers: ["hcc", "cholangiocarcinoma", "colorectal"], technologies: ["thermal-ablation"], related: ["child-pugh", "resection-margins", "downstaging"], sections: ["surgery"] }),
  t({ id: "prostatectomy", name: "Radical prostatectomy", category: "Procedures", aka: ["prostatectomy", "robotic prostatectomy", "robot-assisted prostatectomy", "prostatectomies"], tldr: "Removing the entire prostate gland and seminal vesicles for localised prostate cancer, now almost always with a robot.", summary: "One of three options for localised disease alongside radiotherapy and active surveillance; ProtecT showed identical 15-year prostate cancer mortality (~3%) across all three. Robot-assisted laparoscopic prostatectomy dominates in high-income countries with nerve-sparing techniques to reduce erectile dysfunction, but incontinence (5-20%) and impotence (30-70%) remain the main harms. PSA should become undetectable; a rise afterwards (biochemical recurrence) is imaged with PSMA PET and treated with salvage radiotherapy.", wikipedia: W("Prostatectomy"), cancers: ["prostate"], trials: ["protect"], technologies: ["robotic-surgery", "psma-pet"], related: ["active-surveillance", "gleason-grade-group", "adt"], sections: ["surgery"] }),
  t({ id: "orchiectomy", name: "Orchiectomy", category: "Procedures", aka: ["orchidectomy", "radical inguinal orchiectomy", "surgical castration", "bilateral orchiectomy"], tldr: "Surgical removal of a testicle: the diagnostic and first curative step for testicular cancer, or of both, as a cheap permanent form of hormone therapy in prostate cancer.", summary: "Radical inguinal orchiectomy (through the groin, not the scrotum, to avoid seeding) removes the tumour and gives the histology (seminoma vs non-seminoma) that guides surveillance, carboplatin or BEP chemotherapy. Bilateral orchiectomy lowers testosterone to castrate levels within hours and remains the most cost-effective androgen deprivation worldwide, though most men choose GnRH drugs for reversibility. Testosterone falls to castrate levels permanently, so the hot flushes, bone loss and fatigue of androgen deprivation follow.", wikipedia: W("Orchiectomy"), cancers: ["prostate"], related: ["adt", "castration-resistance"], sections: ["surgery", "hormonal"] }),
  t({ id: "hysterectomy", name: "Hysterectomy", category: "Procedures", aka: ["radical hysterectomy", "total hysterectomy", "hysterectomies", "minimally invasive hysterectomy"], tldr: "Removing the uterus (womb), often with the cervix, tubes and ovaries. Simple hysterectomy is the standard curative operation for endometrial cancer, and radical hysterectomy, which also removes tissue beside the cervix and the upper vagina, treats early cervical cancer; the LACC trial showed open surgery beats laparoscopic for cervical cancer.", summary: "Simple hysterectomy with bilateral salpingo-oophorectomy and sentinel node mapping is the standard for endometrial cancer, where minimally invasive surgery is safe (LAP2, LACE). For cervical cancer, radical hysterectomy removes parametrial tissue and upper vagina; the LACC trial (2018) showed open surgery gave better survival than laparoscopic, reversing practice, while SHAPE showed simple hysterectomy suffices for small low-risk tumours. Fertility-sparing trachelectomy is an option for young women with small cervical tumours.", wikipedia: W("Hysterectomy"), cancers: ["endometrial", "cervical"], related: ["salpingo-oophorectomy", "sentinel-lymph-node-biopsy", "minimally-invasive-surgery"], sections: ["surgery"] }),
  t({ id: "salpingo-oophorectomy", name: "Salpingo-oophorectomy", category: "Procedures", aka: ["oophorectomy", "risk-reducing salpingo-oophorectomy", "bilateral salpingo-oophorectomy", "BSO", "RRSO", "opportunistic salpingectomy", "salpingectomy"], tldr: "Removing the ovaries and fallopian tubes. Done for ovarian cancer, to prevent it in BRCA carriers, or to switch off oestrogen in breast cancer.", summary: "Risk-reducing salpingo-oophorectomy at 35-45 cuts ovarian cancer risk by 80-90% in BRCA1/2 carriers and is the main reason genetic testing saves lives; it causes surgical menopause. Because most high-grade serous cancers begin in the fallopian tube, opportunistic salpingectomy (tubes only, at any pelvic surgery) is now recommended for the general population. Oophorectomy or GnRH agonists provide ovarian suppression in premenopausal hormone receptor-positive breast cancer (SOFT/TEXT).", wikipedia: W("Salpingoophorectomy"), cancers: ["ovarian", "breast-hr-positive"], targets: ["brca"], related: ["gbrca-mutation", "hysterectomy", "aromatase-inhibitor"], sections: ["surgery", "prevention"] }),
  t({ id: "debulking", name: "Debulking (cytoreductive surgery)", category: "Procedures", aka: ["cytoreductive surgery", "cytoreduction", "cytoreductive", "primary debulking", "interval debulking", "interval cytoreduction", "secondary cytoreduction", "complete cytoreduction", "optimal debulking"], tldr: "Surgery that removes as much tumour as possible when it cannot all be removed cleanly; leaving nothing visible behind is what matters.", summary: "Central to ovarian cancer, where survival tracks the residual disease after surgery: complete cytoreduction (no visible tumour) is the goal. Primary debulking is done first if feasible; otherwise three cycles of carboplatin-paclitaxel are followed by interval debulking (EORTC 55971, CHORUS). Secondary cytoreduction at platinum-sensitive relapse helps selected patients (DESKTOP III) but not unselected ones (GOG-0213). Cytoreductive surgery plus HIPEC is used for peritoneal disease from appendix, colorectal and ovarian cancers, and cytoreductive nephrectomy in kidney cancer.", wikipedia: W("Debulking"), cancers: ["ovarian", "rcc"], technologies: ["hipec"], related: ["hipec-procedure", "peritoneum", "neoadjuvant-adjuvant"], sections: ["surgery"] }),
  t({ id: "thyroidectomy", name: "Thyroidectomy", category: "Procedures", aka: ["total thyroidectomy", "hemithyroidectomy", "lobectomy of the thyroid", "prophylactic thyroidectomy"], tldr: "Removing all (total) or half (hemi-) of the thyroid gland, after which thyroid hormone tablets replace its function.", summary: "The main treatment for differentiated thyroid cancer, followed by radioiodine when risk warrants it. Hemithyroidectomy is now adequate for low-risk tumours under 4 cm, and active surveillance is accepted for papillary microcarcinomas. Prophylactic thyroidectomy in childhood prevents medullary thyroid cancer in germline RET carriers (MEN2). Risks are voice change (recurrent laryngeal nerve) and low calcium (parathyroid injury).", wikipedia: W("Thyroidectomy"), cancers: ["thyroid"], related: ["radioiodine-therapy", "active-surveillance"], sections: ["surgery"] }),
  t({ id: "adrenalectomy", name: "Adrenalectomy", category: "Procedures", aka: ["adrenalectomies"], tldr: "Removing an adrenal gland. Open, complete (R0) removal is the only cure for adrenocortical carcinoma.", summary: "Laparoscopic adrenalectomy suits benign tumours and small metastases, but adrenocortical carcinoma requires open en-bloc resection because capsule rupture seeds the abdomen. Adjuvant mitotane follows in high-risk cases. Adrenal metastases from lung cancer are sometimes resected or treated with SBRT in oligometastatic disease.", wikipedia: W("Adrenalectomy"), drugs: ["mitotane"], related: ["resection-margins"], sections: ["surgery"] }),
  t({ id: "turbt", name: "Transurethral resection of bladder tumour (TURBT)", category: "Procedures", aka: ["transurethral resection", "TURBT", "re-resection", "re-TURBT"], tldr: "Shaving a bladder tumour away from the inside using a scope passed up the urethra. It is both the diagnosis and, for non-muscle-invasive cancer, the treatment.", summary: "TURBT establishes stage (whether the tumour has reached the muscle) and grade, and removes all visible non-muscle-invasive disease. A second resection within 6 weeks is recommended for high-grade T1 tumours because up to 30% are under-staged. It is followed by a single chemotherapy instillation or by induction and maintenance intravesical BCG for intermediate- and high-risk disease; blue-light cystoscopy and en-bloc resection improve completeness. Muscle-invasive disease needs cystectomy or trimodality therapy instead.", wikipedia: W("Transurethral_resection_of_bladder_tumor"), cancers: ["urothelial"], related: ["intravesical-therapy", "nmibc-vs-mibc", "cystectomy"], sections: ["surgery"] }),
  t({ id: "limb-salvage-term", name: "Limb-salvage surgery", category: "Procedures", aka: ["limb-salvage", "limb salvage", "limb-sparing surgery", "endoprosthetic reconstruction"], tldr: "Removing a bone or soft-tissue sarcoma while keeping the arm or leg, rebuilding the bone with a metal endoprosthesis or a graft.", summary: "Rosenberg's NCI trial and the arrival of effective chemotherapy made limb salvage standard for osteosarcoma and Ewing sarcoma in the 1980s, with survival equal to amputation. Wide margins are still required; radiotherapy adds local control for soft-tissue sarcomas. Growing endoprostheses for children, computer-navigated resection and 3D-printed implants are current refinements; infection and mechanical failure of the prosthesis are the long-term problems.", wikipedia: W("Limb-sparing_techniques"), cancers: ["sarcoma"], related: ["limb-salvage-surgery", "resection-margins", "wide-local-excision"], sections: ["surgery"] }),
  t({ id: "wide-local-excision", name: "Wide local excision", category: "Procedures", aka: ["wide excision", "excision margins", "local excision", "re-excision", "re-excisions"], tldr: "Cutting out a tumour together with a measured rim of normal-looking tissue around it, so that microscopic spread at the edge is removed too.", summary: "The standard treatment for primary melanoma after diagnostic biopsy: margins of 0.5 cm for in situ, 1 cm for tumours ≤1 mm and 2 cm for thicker tumours (MSLT, MelMarT trials). The same principle applies to soft-tissue sarcomas, skin cancers, breast lumpectomy and vulval cancer. Wider is not better beyond the evidence-based margin; what matters is that the pathologist finds the edges clear (R0).", wikipedia: W("Wide_local_excision"), cancers: ["melanoma", "sarcoma"], related: ["resection-margins", "mohs-surgery", "breslow-thickness"], sections: ["surgery"] }),
  t({ id: "mohs-surgery", name: "Mohs surgery", category: "Procedures", aka: ["Mohs", "Mohs micrographic surgery"], tldr: "Skin cancer surgery in which the tumour is removed in thin layers, each checked under the microscope on the spot, until the edges are clear; it spares the most normal skin.", summary: "Developed by Frederic Mohs, it achieves cure rates above 97% for basal cell and cutaneous squamous cell carcinomas, and is preferred for tumours on the face, recurrent tumours, and aggressive histologies where tissue conservation matters. Each stage takes an hour or so of processing, so the procedure can last a day. It is not used for melanoma in most centres because frozen sections read melanocytes poorly.", wikipedia: W("Mohs_surgery"), related: ["wide-local-excision", "resection-margins"], sections: ["surgery"] }),
  t({ id: "endoscopic-resection-term", name: "EMR and ESD (endoscopic mucosal resection, endoscopic submucosal dissection)", category: "Procedures", aka: ["endoscopic mucosal resection", "endoscopic submucosal dissection", "ESD", "endoscopically resected"], tldr: "Removing an early cancer from the inside lining of the gut through an endoscope, with no external incision and the organ left in place.", summary: "Endoscopic mucosal resection lifts and snares lesions up to about 2 cm; endoscopic submucosal dissection, developed in Japan, cuts under larger lesions en bloc so the pathologist can judge depth and margins. Both cure mucosal cancers of the oesophagus, stomach and colon that have negligible node risk (T1a, well-differentiated, no lymphovascular invasion), which is why endoscopic screening in East Asia converts gastric and oesophageal cancer into an outpatient cure. Deeper (T1b) or poorly differentiated lesions still need surgery.", wikipedia: W("Endoscopic_mucosal_resection"), cancers: ["gastric", "esophageal", "colorectal"], related: ["endoscopic-resection", "barretts-esophagus", "lymphovascular-invasion", "colonoscopy"], sections: ["surgery", "early-detection"] }),
  t({ id: "colonoscopy", name: "Colonoscopy", category: "Procedures", aka: ["colonoscopies", "colonoscopic", "polypectomy", "sigmoidoscopy"], tldr: "Examining the whole large bowel with a flexible camera; polyps found on the way are removed (polypectomy), which prevents most bowel cancers.", summary: "The only screening test that both detects and prevents cancer: removing adenomas cuts colorectal cancer incidence and mortality by half or more (National Polyp Study, NordICC). It is the confirmatory test after a positive stool test (FIT) or blood test, and the surveillance tool after polyp removal or resection. Quality is measured by adenoma detection rate and caecal intubation; AI polyp detection raises the former. Bowel preparation and sedation are the main deterrents to uptake.", wikipedia: W("Colonoscopy"), cancers: ["colorectal"], related: ["endoscopic-resection", "endoscopy"], sections: ["early-detection"] }),
  t({ id: "endoscopy", name: "Endoscopy (EGD, EUS, ERCP)", category: "Procedures", aka: ["endoscopic", "upper endoscopy", "gastroscopy", "endoscopic ultrasound", "EUS", "ERCP", "chromoendoscopy", "cystoscopy", "endoscopies", "cystoscopies"], tldr: "Looking inside a hollow organ with a camera on a flexible tube, taking biopsies and sometimes treating on the spot.", summary: "Upper endoscopy diagnoses and surveils oesophageal and gastric cancer and Barrett's; endoscopic ultrasound (EUS) images the wall layers and nearby nodes and guides fine-needle biopsy of pancreatic masses; ERCP cannulates the bile duct to biopsy and place stents in obstructive jaundice; cystoscopy is the equivalent for the bladder. Lugol chromoendoscopy and narrow-band imaging highlight early squamous and Barrett's neoplasia. Population endoscopic screening is standard in Japan and Korea for gastric cancer.", wikipedia: W("Endoscopy"), cancers: ["esophageal", "gastric", "pancreatic", "cholangiocarcinoma", "urothelial"], related: ["colonoscopy", "endoscopic-resection", "biliary-stent"], sections: ["diagnostics"] }),
  t({ id: "bronchoscopy", name: "Bronchoscopy (EBUS, robotic navigation)", category: "Procedures", aka: ["bronchoscopic", "EBUS", "endobronchial ultrasound", "robotic bronchoscopy", "navigational bronchoscopy"], tldr: "Passing a camera down the windpipe into the lungs to biopsy tumours and lymph nodes without surgery.", summary: "Endobronchial ultrasound (EBUS) samples mediastinal nodes through the airway wall and has largely replaced surgical mediastinoscopy for staging lung cancer. Robotic and electromagnetic navigation bronchoscopy reach small peripheral nodules found on screening CT, and are being coupled with ablation to treat them in the same session. Tissue yield matters because a modern lung cancer diagnosis needs enough for PD-L1 and a genomic panel.", wikipedia: W("Bronchoscopy"), cancers: ["nsclc", "sclc"], related: ["mediastinum", "core-needle-biopsy"], sections: ["diagnostics"] }),
  t({ id: "staging-laparoscopy", name: "Laparoscopy (keyhole surgery)", category: "Procedures", aka: ["laparoscopic", "staging laparoscopy", "diagnostic laparoscopy", "keyhole surgery", "laparoscopically", "peritoneal cytology"], tldr: "Operating or looking inside the abdomen through a few small holes with a camera, instead of one large incision.", summary: "Laparoscopic resection is oncologically equivalent to open surgery for colon, gastric, kidney and endometrial cancer, with faster recovery, though not for cervical cancer (LACC). Staging laparoscopy before gastric or pancreatic surgery finds peritoneal metastases missed by CT in 10-20% of patients and washes the abdomen for cytology, sparing them a non-curative operation. Robotic surgery is laparoscopy with wristed instruments and a console.", wikipedia: W("Laparoscopy"), technologies: ["robotic-surgery"], related: ["minimally-invasive-surgery", "peritoneum"], sections: ["surgery"] }),
  t({ id: "minimally-invasive-surgery", name: "Minimally invasive surgery (laparoscopic, robotic, VATS)", category: "Procedures", aka: ["minimally invasive", "minimally-invasive", "VATS", "video-assisted thoracoscopic surgery", "robot-assisted", "robotic surgery"], tldr: "Any operation done through small incisions with cameras and long instruments, including robot-assisted surgery; the cancer operation is the same, the wound is smaller.", summary: "Video-assisted thoracoscopic surgery (VATS) and robotic lobectomy, laparoscopic colectomy and gastrectomy, and robotic prostatectomy and hysterectomy all give equivalent cancer outcomes to open surgery with less pain, shorter stays and fewer wound complications. Exceptions exist (LACC in cervical cancer), so equivalence must be shown per cancer. Robots cost more without proven survival benefit but are now standard in urology and spreading to lung, oesophageal and pancreatic surgery.", wikipedia: W("Minimally_invasive_procedure"), technologies: ["robotic-surgery"], related: ["staging-laparoscopy", "lobectomy", "prostatectomy"], sections: ["surgery"] }),
  t({ id: "radiofrequency-ablation", name: "Radiofrequency ablation (RFA)", category: "Procedures", aka: ["RFA", "radiofrequency", "thermal ablation", "ablated", "ablative"], tldr: "Killing a tumour by heating it with an electrical current through a needle placed under image guidance, without removing it.", summary: "A probe delivers alternating current that heats tissue above 60°C, coagulating tumours up to about 3 cm. Standard for small hepatocellular carcinomas (equivalent to resection under 2-3 cm), colorectal liver metastases, small kidney tumours in comorbid patients, lung nodules, and Barrett's oesophagus after endoscopic resection. Limitations are the heat-sink effect near large vessels and incomplete ablation of larger lesions, which microwave ablation partly overcomes.", wikipedia: W("Radiofrequency_ablation"), technologies: ["thermal-ablation"], cancers: ["hcc", "rcc", "colorectal"], related: ["microwave-ablation", "cryoablation", "barretts-esophagus"], sections: ["surgery"] }),
  t({ id: "microwave-ablation", name: "Microwave ablation (MWA)", category: "Procedures", aka: ["microwave", "MWA"], tldr: "Like radiofrequency ablation but using microwaves, which heat faster and larger volumes and are less affected by nearby blood vessels.", summary: "Microwave antennas create larger, more predictable ablation zones than RFA in a shorter time and are less prone to the heat-sink effect, so they are increasingly preferred for liver tumours up to 4-5 cm and lung metastases. Randomised comparisons with RFA in hepatocellular carcinoma show equal or better local control. Both are percutaneous, done under CT or ultrasound guidance, usually as a day case.", wikipedia: W("Microwave_ablation"), technologies: ["thermal-ablation"], cancers: ["hcc", "colorectal"], related: ["radiofrequency-ablation", "cryoablation"], sections: ["surgery"] }),
  t({ id: "cryoablation", name: "Cryoablation", category: "Procedures", aka: ["cryotherapy", "cryosurgery", "percutaneous cryoablation"], tldr: "Destroying a tumour by freezing it with a needle that reaches minus 40°C or below; the ice ball is visible on CT, so the treated zone can be watched forming.", summary: "Used for small renal masses (where it rivals partial nephrectomy in frail patients), bone and soft-tissue metastases for pain, early prostate cancer, breast fibroadenomas and small breast cancers, and lung tumours. Freezing is less painful than heat and preserves collagen scaffolds, and dying frozen cells release intact antigens, which motivates trials pairing cryoablation with checkpoint inhibitors. Larger tumours need multiple probes.", wikipedia: W("Cryoablation"), technologies: ["thermal-ablation"], cancers: ["rcc", "prostate"], related: ["radiofrequency-ablation", "microwave-ablation"], sections: ["surgery"] }),
  t({ id: "tace-term", name: "TACE (transarterial chemoembolisation)", category: "Procedures", aka: ["TACE", "chemoembolisation", "chemoembolization", "transarterial", "DEB-TACE", "bland embolisation"], tldr: "Threading a catheter into the artery feeding a liver tumour and injecting chemotherapy plus particles that block the blood supply, starving and poisoning it at once.", summary: "The standard treatment for intermediate-stage (BCLC B) hepatocellular carcinoma that cannot be resected, ablated or transplanted, exploiting the fact that tumours draw blood from the hepatic artery while normal liver relies on the portal vein. Drug-eluting beads deliver doxorubicin more slowly than conventional lipiodol emulsions. Combining TACE with immunotherapy and anti-VEGF drugs (EMERALD-1, LEAP-012) improves progression-free survival, and TACE is also used to bridge patients to liver transplantation.", wikipedia: W("Transcatheter_arterial_chemoembolization"), cancers: ["hcc", "neuroendocrine"], related: ["tace", "tare", "bclc-staging", "liver-directed-therapy"], sections: ["surgery"] }),
  t({ id: "tare", name: "TARE / SIRT (radioembolisation with yttrium-90)", category: "Procedures", aka: ["TARE", "SIRT", "radioembolisation", "radioembolization", "Y-90", "Y90", "yttrium-90", "selective internal radiation therapy", "90Y microspheres"], tldr: "Injecting tiny radioactive glass or resin beads into the liver's artery so they lodge in the tumour and irradiate it from inside.", summary: "Yttrium-90 microspheres (20-60 µm) deliver beta radiation over a few millimetres with a 64-hour half-life, treating hepatocellular carcinoma, colorectal liver metastases and neuroendocrine liver metastases. Randomised trials against sorafenib (SARAH, SIRveNIB) showed no survival gain but better tolerability; radiation segmentectomy, which delivers ablative doses to a small segment, achieves outcomes close to ablation. Dosimetry now individualises the activity (DOSISPHERE). Chosen over TACE when portal vein thrombus is present.", wikipedia: W("Selective_internal_radiation_therapy"), cancers: ["hcc", "colorectal", "neuroendocrine"], related: ["tace", "liver-directed-therapy", "portal-vein-tumour-thrombus"], sections: ["radiopharma", "surgery"] }),
  t({ id: "stereotactic-radiosurgery", name: "Stereotactic radiosurgery (SRS)", category: "Procedures", aka: ["SRS", "radiosurgery", "Gamma Knife", "gamma knife", "fractionated stereotactic radiotherapy"], tldr: "A single high dose of radiation delivered to a brain tumour or metastasis by beams converging from all sides, so the target gets a destructive dose while the surrounding brain gets little; no scalpel is involved despite the name. It treats metastases up to about 3-4 cm and has replaced whole-brain radiotherapy for limited disease because it spares cognition.", summary: "Gamma Knife, CyberKnife and linac-based SRS treat brain metastases up to about 3-4 cm (or several at once) with local control above 80% and have replaced whole-brain radiotherapy for limited disease because they spare cognition (N0574, JLGK0901). Larger cavities after surgery get fractionated stereotactic radiotherapy in 3-5 sessions. Modern practice combines SRS with CNS-active drugs (osimertinib, tucatinib, T-DXd), and trials now test whether upfront SRS can be deferred when such drugs are available.", wikipedia: W("Radiosurgery"), technologies: ["sbrt"], related: ["brain-metastases", "wbrt", "sbrt-term"], sections: ["radiation"] }),
  t({ id: "wbrt", name: "Whole-brain radiotherapy (WBRT)", category: "Procedures", aka: ["WBRT", "whole-brain", "whole-brain radiation", "whole brain radiotherapy", "hippocampal-avoidance"], tldr: "Irradiating the entire brain, typically 30 Gy in 10 sessions, when metastases are too numerous or too widespread (leptomeningeal) for focused radiosurgery. It controls disease but dulls memory, so it is now reserved for those cases, with hippocampal-avoidance planning and memantine to limit the decline.", summary: "Once routine for any brain metastasis, WBRT (typically 30 Gy in 10 fractions) is now reserved for numerous or leptomeningeal metastases when SRS is impractical, because randomised trials showed no survival gain over SRS alone and clear neurocognitive harm. Hippocampal-avoidance planning and memantine (NRG CC001) reduce the decline. In small-cell lung cancer, prophylactic cranial irradiation is a related low-dose whole-brain treatment now being replaced by MRI surveillance.", wikipedia: W("Whole_brain_radiotherapy"), related: ["stereotactic-radiosurgery", "brain-metastases", "prophylactic-cranial-irradiation", "leptomeningeal-disease"], sections: ["radiation"] }),
  t({ id: "pci-term", name: "Prophylactic cranial irradiation (PCI)", category: "Procedures", aka: ["PCI", "cranial irradiation"], tldr: "Giving the brain a preventive dose of radiation (25 Gy in 10 sessions) before any metastasis can be seen, mainly in small-cell lung cancer, which spreads to the brain in over half of patients. Its value is disputed now that MRI surveillance is routine, and cognitive side effects push practice towards watching instead.", summary: "Small-cell lung cancer spreads to the brain in over half of patients, and PCI (25 Gy in 10 fractions) halved brain relapse and improved survival in limited-stage disease in the 1990s meta-analysis. Its value in extensive-stage disease and in the era of routine MRI staging is disputed (the Japanese Takahashi trial found no benefit with MRI surveillance), so the SWOG S1827 MAVERICK trial is comparing PCI with MRI surveillance while cognitive side effects push practice toward surveillance. In childhood leukaemia it has been replaced by intrathecal chemotherapy.", wikipedia: W("Prophylactic_cranial_irradiation"), cancers: ["sclc"], related: ["prophylactic-cranial-irradiation", "wbrt", "brain-metastases", "intrathecal-therapy"], sections: ["radiation"] }),
  t({ id: "biliary-stent", name: "Stenting (biliary, oesophageal, airway)", category: "Procedures", aka: ["stent", "stents", "stenting", "biliary stenting", "self-expanding metal stent", "SEMS", "oesophageal stent", "biliary drainage", "percutaneous drainage"], tldr: "Placing a small mesh or plastic tube to hold open a duct or passage that a tumour is squeezing shut, relieving jaundice, swallowing difficulty or breathlessness.", summary: "Biliary stents placed by ERCP (or percutaneously) relieve obstructive jaundice from pancreatic and bile duct cancers so that chemotherapy can be given; metal stents stay open longer than plastic. Self-expanding oesophageal stents restore swallowing in advanced oesophageal cancer within a day, airway stents relieve central obstruction, and ureteric stents or nephrostomy protect kidneys. Stents palliate rather than treat the tumour, and can migrate or block, so they are one option alongside brachytherapy and radiotherapy.", wikipedia: W("Stent"), cancers: ["pancreatic", "cholangiocarcinoma", "esophageal"], related: ["obstructive-jaundice", "dysphagia", "endoscopy"], sections: ["supportive-care"] }),
  t({ id: "pleurodesis", name: "Pleurodesis and indwelling pleural catheter", category: "Procedures", aka: ["pleurodesis", "indwelling pleural catheter", "talc pleurodesis", "thoracentesis", "pleural drainage"], tldr: "Ways to stop fluid repeatedly collecting around the lung: either glue the two pleural layers together with talc, or leave a small tunnelled drain the patient empties at home.", summary: "Malignant pleural effusion causes breathlessness in lung, breast and mesothelioma patients. Draining it (thoracentesis) helps for days; talc pleurodesis via chest tube or VATS seals the space in about 70%; an indwelling pleural catheter allows outpatient management with fewer hospital days (TIME2, AMPLE) and can itself produce pleurodesis. Choice depends on lung re-expansion, prognosis and preference; pleurodesis has no effect on the underlying cancer.", wikipedia: W("Pleurodesis"), cancers: ["mesothelioma", "nsclc"], related: ["pleura", "pleural-effusion"], sections: ["supportive-care"] }),
  t({ id: "apheresis", name: "Apheresis (leukapheresis)", category: "Procedures", aka: ["leukapheresis", "apheresis collection", "stem cell mobilisation", "stem cell collection", "plerixafor mobilisation"], tldr: "Running a patient's blood through a machine that skims off one type of cell (T cells, or stem cells) and returns the rest; the harvested cells become the raw material for CAR-T or a transplant.", summary: "For CAR-T, leukapheresis collects the patient's lymphocytes over 3-4 hours, which are shipped to a manufacturing site; heavy prior chemotherapy or a low lymphocyte count can make the product fail. For autologous transplant, stem cells are mobilised from the marrow into blood with G-CSF (plus plerixafor if needed) and collected the same way, then cryopreserved. Slot availability and vein-to-vein time depend on apheresis capacity, a real bottleneck in cell therapy.", wikipedia: W("Apheresis"), technologies: ["car-t", "apheresis-starting-material"], related: ["autologous-transplant", "vein-to-vein-time", "lymphodepletion"], sections: ["cell-therapy"] }),
  t({ id: "intrathecal-therapy", name: "Intrathecal therapy (lumbar puncture, Ommaya reservoir)", category: "Procedures", aka: ["intrathecal", "intrathecal chemotherapy", "intraventricular", "Ommaya", "Ommaya reservoir", "lumbar puncture", "spinal tap", "CSF sampling"], tldr: "Giving drugs directly into the fluid around the brain and spinal cord, by needle in the lower back or through a small reservoir under the scalp, because most drugs cannot cross from the blood into that space.", summary: "Intrathecal methotrexate and cytarabine prevent and treat central nervous system leukaemia and lymphoma and are given by lumbar puncture, which also samples cerebrospinal fluid for leukaemic cells or ctDNA. An Ommaya reservoir connects to a ventricular catheter for repeated intraventricular dosing and is the route for locoregional CAR-T in glioblastoma and leptomeningeal disease trials. Intrathecal trastuzumab is used for HER2-positive leptomeningeal metastases.", wikipedia: W("Intrathecal_administration"), cancers: ["all-leukemia", "dlbcl", "glioblastoma"], related: ["leptomeningeal-disease", "cns-penetration"], sections: ["chemotherapy"] }),
  t({ id: "central-venous-access", name: "Central venous access (port, PICC line)", category: "Procedures", aka: ["port-a-cath", "implanted port", "PICC", "PICC line", "central line", "central venous catheter", "Hickman line", "tunnelled line", "PICC lines"], tldr: "A long-term line into a large vein near the heart, either a small disc under the skin (port) or a tube from the arm (PICC), so chemotherapy can be given and blood drawn without repeated needle sticks.", summary: "Vesicant drugs (anthracyclines, vinca alkaloids), continuous infusions (5-FU pumps) and cell therapies are safer through central access, which avoids extravasation and vein damage. Ports last years and allow swimming; PICC lines are cheaper but need weekly care and carry higher thrombosis and infection risk. Both are sources of line infection and catheter-related thrombosis, so they are removed when no longer needed.", wikipedia: W("Port_(medical)"), technologies: ["infusion-devices-vascular-access"], related: ["extravasation-infusion-reaction", "vte"], sections: ["supportive-care"] }),
  t({ id: "feeding-tube", name: "Feeding tube (gastrostomy, PEG, jejunostomy)", category: "Procedures", aka: ["gastrostomy", "PEG tube", "jejunostomy", "nasogastric tube", "enteral feeding", "feeding tubes"], tldr: "A tube placed into the stomach (gastrostomy, PEG) or small bowel (jejunostomy) so a patient who cannot swallow enough can still be fed through the gut.", summary: "Head and neck chemoradiation, oesophageal cancer and extensive upper-GI surgery often make eating impossible for weeks. A percutaneous endoscopic gastrostomy (PEG) is placed through the abdominal wall under endoscopy; a feeding jejunostomy is often placed at oesophagectomy. Enteral feeding is preferred over intravenous nutrition whenever the gut works, because it keeps the intestinal barrier healthy and costs less. Prophylactic versus reactive tube placement in head and neck cancer remains debated because tubes can prolong swallowing disuse.", wikipedia: W("Percutaneous_endoscopic_gastrostomy"), cancers: ["head-and-neck", "esophageal"], related: ["dysphagia", "enteral-parenteral-nutrition", "oesophagectomy"], sections: ["supportive-care"] }),
  t({ id: "stoma", name: "Stoma (colostomy, ileostomy, urostomy)", category: "Procedures", aka: ["colostomy", "ileostomy", "urostomy", "ileal conduit", "neobladder", "ostomy", "stoma reversal"], tldr: "An opening made in the abdominal wall so bowel or urine empties into a bag; may be temporary while a join heals, or permanent when the rectum, anus or bladder has been removed.", summary: "A loop ileostomy protects a low rectal anastomosis for a few months and is then reversed. Abdominoperineal resection leaves a permanent colostomy; cystectomy is followed by an ileal conduit (urostomy) or an orthotopic neobladder made from bowel that the patient empties by straining. Stoma avoidance is a major motive behind organ-preservation strategies in rectal, anal and bladder cancer, and stoma care nursing is a large part of survivorship.", wikipedia: W("Stoma_(medicine)"), cancers: ["colorectal", "urothelial"], related: ["abdominoperineal-resection", "cystectomy", "organ-preservation"], sections: ["surgery", "supportive-care"] }),
  t({ id: "core-needle-biopsy", name: "Core needle biopsy and fine-needle aspiration (FNA)", category: "Procedures", aka: ["core biopsy", "core needle biopsy", "fine-needle aspiration", "fine needle aspiration", "FNA", "image-guided biopsy", "CT-guided biopsy", "re-biopsy", "bone marrow biopsy", "bone marrow aspirate", "targeted biopsy"], tldr: "Taking a sliver of tissue (core) or a few cells (fine-needle aspiration) through a needle guided by ultrasound, CT or MRI, to diagnose the cancer and test its markers without surgery.", summary: "Core biopsy preserves tissue architecture and gives enough material for immunohistochemistry (ER, PR, HER2, PD-L1) and genomic panels, so it is the standard for breast, prostate (MRI-targeted), lung and liver lesions. FNA gives cytology only and suits thyroid nodules (Bethesda system) and lymph nodes. Bone marrow aspirate and trephine biopsy diagnose and monitor leukaemias and myeloma. Re-biopsy at progression identifies resistance mechanisms (T790M, small-cell transformation) when liquid biopsy is uninformative.", wikipedia: W("Needle_aspiration_biopsy"), technologies: ["histopathology-ihc", "liquid-biopsy"], related: ["histology", "flow-cytometry", "cfdna"], sections: ["diagnostics"] }),
  t({ id: "hipec-procedure", name: "HIPEC (hyperthermic intraperitoneal chemotherapy)", category: "Procedures", aka: ["hyperthermic intraperitoneal chemotherapy", "heated intraperitoneal chemotherapy", "PIPAC", "pressurised intraperitoneal aerosol chemotherapy"], tldr: "After surgeons remove all visible tumour from the abdominal lining, the abdomen is bathed for 60-90 minutes in heated chemotherapy to kill the microscopic cells left behind.", summary: "Cytoreductive surgery plus HIPEC is standard for pseudomyxoma peritonei and appendiceal cancers and has randomised support in ovarian cancer (van Driel 2018, OVHIPEC-1) and gastric cancer prevention of peritoneal recurrence, but PRODIGE 7 showed no benefit of oxaliplatin HIPEC in colorectal peritoneal metastases, so its role there rests on complete cytoreduction alone. Heat (41-43°C) increases drug penetration to a few millimetres. PIPAC delivers aerosolised chemotherapy laparoscopically for unresectable peritoneal disease and is in trials.", wikipedia: W("Hyperthermic_intraperitoneal_chemotherapy"), technologies: ["hipec"], cancers: ["ovarian", "colorectal", "gastric"], related: ["debulking", "peritoneum", "intraperitoneal-chemotherapy"], sections: ["surgery", "chemotherapy"] }),
  t({ id: "brachytherapy-term", name: "Brachytherapy (internal radiotherapy)", category: "Procedures", aka: ["brachytherapy boost", "HDR brachytherapy", "LDR brachytherapy", "seed implant", "interstitial brachytherapy", "intracavitary"], tldr: "Radiotherapy from the inside: radioactive seeds or a temporary source are placed in or next to the tumour, so the dose falls off steeply and nearby organs are spared.", summary: "Low-dose-rate seeds (iodine-125) permanently implanted in the prostate cure low-risk disease as well as surgery; high-dose-rate brachytherapy boosts external beam in intermediate- and high-risk prostate cancer (ASCENDE-RT) and is essential for cervical cancer, where image-guided brachytherapy to ≥85 Gy EQD2 drives cure (EMBRACE). Also used for oesophageal palliation, skin, breast (partial-breast) and eye (plaque for uveal melanoma). It needs skilled operators and access has declined in some countries as external-beam options improved.", wikipedia: W("Brachytherapy"), technologies: ["brachytherapy"], cancers: ["prostate", "cervical"], related: ["gray-unit", "hypofractionation", "imrt-term"], sections: ["radiation"] }),
  t({ id: "sbrt-term", name: "Stereotactic body radiotherapy (SBRT / SABR)", category: "Procedures", aka: ["SBRT", "SABR", "stereotactic ablative radiotherapy", "stereotactic body radiation therapy", "stereotactic radiotherapy", "stereotactic", "metastasis-directed therapy"], tldr: "A course of one to five large, pinpoint-accurate radiation doses that destroy a tumour outside the brain almost like surgery, for patients who cannot or prefer not to have an operation. It is standard for inoperable early lung cancer and the backbone of oligometastatic treatment; toxicity is mostly to whatever lies within a centimetre of the target.", summary: "Made possible by image guidance and motion management, SBRT gives local control above 90% for early lung cancer (the standard for inoperable stage I), treats liver, pancreatic, kidney, spine and prostate tumours (5-fraction PACE-B), and is the backbone of oligometastatic treatment, where SABR-COMET showed a survival gain. Ultra-high doses per fraction exploit different radiobiology (vascular damage, immune priming), hence the abscopal-effect trials with checkpoint inhibitors. Toxicity is mostly to whatever lies within a centimetre of the target.", wikipedia: W("Stereotactic_body_radiation_therapy"), technologies: ["sbrt"], related: ["stereotactic-radiosurgery", "hypofractionation", "oligometastatic", "gray-unit"], sections: ["radiation"] }),
  t({ id: "imrt-term", name: "IMRT / IGRT / VMAT (modern external beam radiotherapy)", category: "Procedures", aka: ["IMRT", "IGRT", "VMAT", "intensity-modulated radiotherapy", "intensity-modulated", "image-guided radiotherapy", "external beam", "external-beam", "external beam radiotherapy", "EBRT", "conformal", "3D-conformal"], tldr: "Radiation beams shaped and varied in intensity from multiple angles, or while the machine rotates around the patient (VMAT), so the dose hugs the tumour and misses healthy tissue, checked against imaging before each session so it lands where planned. It cut dry mouth in head and neck cancer and rectal toxicity in prostate cancer.", summary: "Intensity-modulated radiotherapy (IMRT) sculpts dose with a multileaf collimator; volumetric modulated arc therapy (VMAT) does it while the machine rotates, in minutes; image-guided radiotherapy (IGRT) uses cone-beam CT or surface tracking before each fraction. Together they cut xerostomia in head and neck cancer (PARSPORT), rectal toxicity in prostate cancer and allowed hypofractionation. Planning quality depends on contouring, now aided by AI auto-segmentation. Proton therapy adds a sharper depth stop for selected tumours.", wikipedia: W("Radiation_therapy#Intensity-modulated_radiation_therapy_(IMRT)"), technologies: ["imrt-igrt", "proton-therapy", "auto-contouring-ai"], related: ["hypofractionation", "gray-unit", "sbrt-term"], sections: ["radiation"] }),

  // ---- Anatomy ----
  t({ id: "mediastinum", name: "Mediastinum", category: "Anatomy", aka: ["mediastinal", "mediastinal nodes", "mediastinal lymph nodes", "hilar nodes", "mediastinoscopy", "mediastinal node"], tldr: "The space in the middle of the chest between the two lungs, containing the heart, great vessels, windpipe, food pipe and the lymph nodes that lung cancer spreads to first.", summary: "Whether mediastinal lymph nodes contain tumour separates stage I-II lung cancer (surgery first) from stage III (chemoradiation or neoadjuvant chemo-immunotherapy), so they are sampled by EBUS or mediastinoscopy before any operation. Thymomas, lymphomas and germ cell tumours arise in the mediastinum; oesophageal cancer and its nodes lie within it. On PET reports 'uptake above mediastinum' is the Deauville reference level.", wikipedia: W("Mediastinum"), cancers: ["nsclc", "esophageal"], related: ["bronchoscopy", "lymph-node-status", "deauville"], sections: ["surgery"] }),
  t({ id: "peritoneum", name: "Peritoneum and peritoneal metastases", category: "Anatomy", aka: ["peritoneal", "peritoneal metastases", "peritoneal carcinomatosis", "carcinomatosis", "peritoneal disease", "peritoneal spread", "peritoneal cavity", "omentum", "omental"], tldr: "The thin membrane lining the abdominal cavity and covering the bowel. Cancers of the ovary, stomach, colon, appendix and pancreas seed it with small, poorly vascularised deposits that CT under-detects and drugs reach badly, which is why surgery with heated intraperitoneal chemotherapy (HIPEC) is used in appendiceal and selected ovarian cancers.", summary: "Peritoneal metastases (carcinomatosis) cause ascites, bowel obstruction and cachexia, are under-detected by CT, and respond poorly to systemic therapy because deposits are small, poorly vascularised and bathed in a protective fluid space. Treatments include cytoreductive surgery with HIPEC (standard in appendiceal and selected ovarian cancers), intraperitoneal chemotherapy and PIPAC, and in gastric cancer the extent of peritoneal disease (P score, cytology) determines resectability. Mesothelioma can also arise from the peritoneum.", wikipedia: W("Peritoneal_carcinomatosis"), cancers: ["ovarian", "gastric", "colorectal", "pancreatic", "mesothelioma"], related: ["hipec-procedure", "debulking", "staging-laparoscopy", "intraperitoneal-chemotherapy"], sections: ["surgery"] }),
  t({ id: "pleura", name: "Pleura", category: "Anatomy", aka: ["pleural", "pleural cavity", "pleural space", "extrapleural", "pleurectomy", "pleurectomy/decortication", "pleural metastases"], tldr: "The two-layered lining around each lung. Mesothelioma grows from it, lung and breast cancers spread to it, and fluid collecting between its layers causes breathlessness.", summary: "The visceral pleura covers the lung and the parietal pleura lines the chest wall; the potential space between them fills with a malignant pleural effusion in advanced lung, breast and ovarian cancers and lymphoma. Malignant pleural mesothelioma, almost always from asbestos, spreads along the pleural surface; its surgery ranges from extrapleural pneumonectomy (abandoned after MARS 1) to pleurectomy/decortication (questioned by MARS 2). Pleural invasion also upstages lung cancer.", wikipedia: W("Pulmonary_pleurae"), cancers: ["mesothelioma", "nsclc"], trials: ["mars-2"], related: ["pleural-effusion", "pleurodesis", "pneumonectomy"], sections: ["surgery"] }),
  t({ id: "pleural-effusion", name: "Malignant pleural effusion and ascites", category: "Anatomy", aka: ["pleural effusion", "effusion", "effusions", "ascites", "malignant ascites", "paracentesis"], tldr: "Fluid that builds up around the lung (pleural effusion) or in the abdomen (ascites) because cancer cells irritate the lining and block lymph drainage; it causes breathlessness or a swollen, tight belly.", summary: "Both are signs of advanced disease (stage IV in lung cancer; a criterion in Child-Pugh and BCLC for liver cancer) and both are diagnosed and relieved by draining the fluid, which can also be sent for cytology and ctDNA. Repeated drainage, indwelling catheters, pleurodesis and, for ascites, diuretics or intraperitoneal therapy are the management options; effective systemic treatment of the cancer is what stops the fluid re-forming. Ovarian cancer classically presents with ascites.", wikipedia: W("Malignant_pleural_effusion"), cancers: ["nsclc", "ovarian", "hcc", "mesothelioma"], related: ["pleura", "pleurodesis", "peritoneum", "child-pugh"], sections: ["supportive-care"] }),
  t({ id: "retroperitoneum", name: "Retroperitoneum", category: "Anatomy", aka: ["retroperitoneal", "retroperitoneal sarcoma", "retroperitoneal nodes", "para-aortic nodes", "para-aortic"], tldr: "The space at the back of the abdomen, behind the gut's lining, holding the kidneys, adrenals, pancreas, aorta and the para-aortic lymph nodes. Tumours here grow large before they are felt.", summary: "Retroperitoneal sarcomas (liposarcoma, leiomyosarcoma) are removed en bloc with adjacent organs and were the subject of the STRASS trials of preoperative radiotherapy; kidney, adrenal and pancreatic cancers are retroperitoneal organs. Para-aortic and retroperitoneal lymph nodes are staging sites for testicular, cervical, endometrial and gastric cancers, and retroperitoneal lymph node dissection remains part of testicular cancer treatment. Retroperitoneal spread often presents as back pain or ureteric obstruction.", wikipedia: W("Retroperitoneal_space"), cancers: ["sarcoma", "rcc", "pancreatic"], related: ["lymphadenectomy", "lymph-node-status"], sections: ["surgery"] }),
  t({ id: "lymph-node-status", name: "Lymph node status (node-positive / node-negative)", category: "Anatomy", aka: ["node-positive", "node-negative", "nodal", "nodal status", "nodal staging", "nodal disease", "lymph node involvement", "lymph node metastases", "lymph node-positive", "N0", "regional nodes", "positive nodes", "involved nodes"], tldr: "Whether the cancer has reached the nearby lymph nodes, the filters along the lymphatic drainage. It is the single strongest predictor of whether cancer has escaped the organ, and it drives most decisions about extra treatment after surgery.", summary: "The N in TNM staging counts involved regional nodes (N0 none, N1-N3 increasing). Node-positive breast cancer earns chemotherapy or CDK4/6 inhibitors (monarchE); node-positive colon cancer (stage III) gets adjuvant FOLFOX; N2 lung cancer changes surgery to chemoradiation. Nodes are assessed by imaging, sentinel node biopsy or dissection, and pathologists count how many of how many examined were positive, which is why a minimum node harvest is a surgical quality marker. Nodal micrometastases and isolated tumour cells are graded separately.", wikipedia: W("Lymph_node_metastasis"), related: ["sentinel-lymph-node-biopsy", "lymphadenectomy", "tnm-staging", "lymphovascular-invasion"], trials: ["monarche"], sections: ["surgery"] }),
  t({ id: "gej", name: "Gastro-oesophageal junction (GEJ)", category: "Anatomy", aka: ["GEJ", "GOJ", "gastroesophageal junction", "gastro-oesophageal junction", "oesophagogastric junction", "junctional", "Siewert", "esophagogastric junction"], tldr: "Where the food pipe meets the stomach. Cancers here are classed by how far above or below the junction they centre (Siewert I-III), which decides whether they are treated like oesophageal or stomach cancer.", summary: "Adenocarcinoma of the GEJ has risen sharply in Western countries with obesity and reflux (via Barrett's oesophagus). Siewert type I (mainly oesophageal) is treated with chemoradiation (CROSS) and oesophagectomy; type III (mainly gastric) with perioperative FLOT and extended gastrectomy; type II either way. Drug trials for HER2, PD-L1 and claudin 18.2 usually enrol gastric and GEJ tumours together, so the label 'gastric or GEJ adenocarcinoma' is common on approvals.", wikipedia: W("Gastroesophageal_junction"), cancers: ["esophageal", "gastric"], trials: ["cross"], related: ["barretts-esophagus", "oesophagectomy", "gastrectomy", "flot"], sections: ["surgery"] }),
  t({ id: "head-neck-subsites", name: "Head and neck subsites (oral cavity, oropharynx, larynx)", category: "Anatomy", aka: ["oral cavity", "oropharynx", "oropharyngeal", "hypopharynx", "nasopharynx", "nasopharyngeal", "larynx", "laryngeal", "larynx preservation", "salivary gland", "salivary glands"], tldr: "Head and neck cancer is really several cancers named by exact location: mouth (oral cavity), back of the throat (oropharynx, where HPV cancers arise), voice box (larynx), lower throat (hypopharynx) and behind the nose (nasopharynx). Each behaves and is treated differently.", summary: "Oral cavity cancers are treated surgically first. Oropharyngeal cancers, now mostly HPV-driven, respond so well to chemoradiation that de-escalation trials are under way; laryngeal cancer is often treated with radiotherapy to preserve the voice, with laryngectomy for salvage; nasopharyngeal carcinoma, EBV-driven and concentrated in southern China, gets IMRT plus platinum and is monitored by plasma EBV DNA. Subsite determines staging (AJCC 8 gives HPV-positive oropharynx its own system), surgical access and functional consequences for speech and swallowing.", wikipedia: W("Head_and_neck_cancer"), cancers: ["head-and-neck"], related: ["hpv-status", "ebv-term", "chemoradiation", "plasma-ebv-dna"], sections: ["surgery", "radiation"] }),
  t({ id: "leptomeningeal-disease", name: "Leptomeningeal disease", category: "Anatomy", aka: ["leptomeningeal", "leptomeningeal metastases", "leptomeningeal carcinomatosis", "carcinomatous meningitis"], tldr: "Cancer cells spreading in the fluid and membranes that bathe the brain and spinal cord, rather than as a solid lump. It causes headaches, nerve palsies and confusion and has been one of the hardest situations to treat.", summary: "Occurs in 5-10% of solid tumours (breast, lung, melanoma) and in leukaemia and lymphoma; diagnosed by MRI and cerebrospinal fluid cytology or ctDNA. Median survival has been weeks to months. Treatments are intrathecal chemotherapy or trastuzumab, craniospinal radiotherapy (proton craniospinal showed benefit at MSK), and increasingly CNS-penetrant drugs such as osimertinib at high dose, tucatinib and T-DXd. CNS prophylaxis in high-risk leukaemia and lymphoma exists to prevent it.", wikipedia: W("Leptomeningeal_cancer"), related: ["brain-metastases", "intrathecal-therapy", "cns-penetration"], sections: ["radiation", "chemotherapy"] }),
  t({ id: "brain-metastases", name: "Brain metastases (intracranial disease)", category: "Anatomy", aka: ["brain metastasis", "intracranial", "intracranial metastases", "CNS metastases", "CNS disease", "CNS activity", "intracranial response", "intracranial ORR", "CNS relapse", "brain mets", "intracranial responses"], tldr: "Tumour deposits that have travelled to the brain from a cancer elsewhere, ten times more common than cancers that start in the brain, mostly from lung, breast, melanoma and kidney cancer. Because the blood-brain barrier excludes most drugs, whether a medicine reaches and shrinks them now decides which drug is chosen, and trials report intracranial progression separately.", summary: "Lung cancer, breast cancer (especially HER2-positive and triple-negative), melanoma and kidney cancer account for most cases; 30-50% of driver-positive lung cancer patients develop them. Local treatment is stereotactic radiosurgery or surgery for limited disease and whole-brain radiotherapy for extensive disease. Because the blood-brain barrier excludes many drugs, CNS penetration and intracranial response rates (osimertinib, lorlatinib, tucatinib, T-DXd in DESTINY-Breast12) increasingly determine which drug is chosen, and trials now report intracranial progression-free survival separately.", wikipedia: W("Brain_metastasis"), cancers: ["nsclc", "breast-her2-positive", "tnbc", "melanoma", "secondary-brain-tumours"], related: ["stereotactic-radiosurgery", "wbrt", "cns-penetration", "leptomeningeal-disease"], sections: ["radiation"] }),
  t({ id: "bone-metastases", name: "Bone metastases and skeletal-related events", category: "Anatomy", aka: ["bone metastasis", "skeletal metastases", "skeletal-related events", "skeletal-related event", "SRE", "bone-only", "bone-predominant", "osseous metastases", "pathological fracture", "spinal cord compression"], tldr: "Cancer spread to the bones, most common in prostate, breast, lung, kidney and thyroid cancer and myeloma. It causes pain, fractures and high calcium, and the complications are counted in trials as 'skeletal-related events'.", summary: "Skeletal-related events (fracture, need for radiotherapy or surgery to bone, spinal cord compression, hypercalcaemia) are reduced 30-40% by bone-modifying agents (zoledronic acid, denosumab). Single-fraction 8 Gy radiotherapy relieves pain as well as longer courses; SBRT gives more durable relief for spine metastases. Bone-seeking radiopharmaceuticals (radium-223, strontium-89) treat bone-predominant prostate cancer, and bone-only disease has a better prognosis than visceral spread in breast cancer. Spinal cord compression is an emergency needing steroids and urgent radiotherapy or surgery.", wikipedia: W("Bone_metastasis"), cancers: ["prostate", "breast-hr-positive", "multiple-myeloma", "rcc"], technologies: ["bone-modifying-agents", "palliative-radiotherapy"], drugs: ["radium-223"], related: ["hypofractionation", "sbrt-term"], sections: ["supportive-care"] }),
  t({ id: "portal-vein-tumour-thrombus", name: "Portal vein tumour thrombus (macrovascular invasion)", category: "Anatomy", aka: ["portal vein", "portal vein invasion", "macrovascular invasion", "tumour thrombus", "vascular invasion", "portal hypertension"], tldr: "Liver cancer growing into the main vein that brings blood from the gut to the liver. It marks advanced disease, rules out most surgery and transplant, and makes some local treatments unsafe.", summary: "Hepatocellular carcinoma has a propensity to invade the portal and hepatic veins; macrovascular invasion defines BCLC stage C, excludes transplantation and usually resection, and makes TACE hazardous because the liver would lose both blood supplies, so radioembolisation, radiotherapy to the thrombus or systemic therapy (atezolizumab-bevacizumab) are used. Portal hypertension from cirrhosis, separately, causes varices and ascites and limits treatment options. Renal cell carcinoma can similarly extend into the renal vein and inferior vena cava, which is removed with the kidney.", wikipedia: W("Portal_vein"), cancers: ["hcc", "rcc"], related: ["bclc-staging", "tace", "tare", "cirrhosis"], sections: ["surgery"] }),

  // ---- Pathology & biomarkers ----
  t({ id: "lymphovascular-invasion", name: "Lymphovascular invasion (LVI)", category: "Pathology & biomarkers", aka: ["LVI", "lymphovascular", "vascular invasion", "lymphatic invasion", "venous invasion", "extramural venous invasion", "EMVI"], tldr: "The pathologist has seen cancer cells inside small lymph or blood vessels in the removed tissue: a sign the tumour has found the exit routes, even if the nodes are clear.", summary: "Reported in most resection specimens, LVI raises the risk of node metastases and recurrence and is a criterion for adjuvant chemotherapy in stage II colon cancer, for surgery rather than endoscopic resection in early gastric and oesophageal cancer, for adjuvant therapy in stage I testicular cancer, and for cystectomy in bladder cancer. Extramural venous invasion (EMVI) on MRI is a high-risk feature in rectal cancer. It is one of several 'high-risk features' alongside grade, perineural invasion and positive margins.", wikipedia: W("Lymphovascular_invasion"), related: ["perineural-invasion", "lymph-node-status", "resection-margins", "endoscopic-resection"], sections: ["diagnostics"] }),
  t({ id: "perineural-invasion", name: "Perineural invasion (PNI)", category: "Pathology & biomarkers", aka: ["PNI", "perineural", "nerve invasion", "neural invasion"], tldr: "Cancer cells growing along the sheath of a nerve. Nerves act as tracks for spread, so this finding predicts recurrence, especially in pancreatic, prostate and head and neck cancers.", summary: "Nearly universal in pancreatic cancer (explaining its pain and local recurrence), common in prostate cancer biopsies and in cutaneous squamous and salivary cancers, PNI is an adverse pathological feature that can trigger adjuvant radiotherapy or wider margins. Biologically, nerves and tumours signal to each other (adrenergic and cholinergic signalling drive proliferation), which underpins the cancer neuroscience field and trials of beta-blockers and denervation. It is recorded in nearly every pathology report as present or absent.", wikipedia: W("Perineural_invasion"), cancers: ["pancreatic", "prostate", "head-and-neck"], technologies: ["nerve-tumour-denervation"], related: ["lymphovascular-invasion", "resection-margins"], sections: ["diagnostics"] }),
  t({ id: "resection-margins", name: "Resection margins (R0 / R1 / R2)", category: "Pathology & biomarkers", aka: ["margins", "margin", "surgical margins", "negative margins", "positive margins", "margin-negative", "margin-positive", "clear margins", "R0", "R0 resection", "R1 resection", "R2 resection", "microscopic residual disease", "margin status", "circumferential resection margin", "CRM", "positive margin", "resection margin"], tldr: "Whether the edge of the removed tissue is free of cancer. R0 means clear under the microscope, R1 means microscopic cancer at the edge, R2 means visible tumour left behind. R0 is what 'complete resection' means.", summary: "Margin status is the strongest surgeon-controlled predictor of local recurrence and, in several cancers, of survival. An R1 margin often means further surgery, radiotherapy or, in pancreatic cancer, simply a worse prognosis; R2 resections are palliative. The required width varies: 'no ink on tumour' suffices for invasive breast cancer, 1 mm for the circumferential margin in rectal cancer, 1-2 cm for melanoma. Neoadjuvant therapy is often justified by its ability to raise the R0 rate, as with daraxonrasib in pancreatic cancer.", wikipedia: W("Resection_margin"), related: ["wide-local-excision", "whipple", "lymphovascular-invasion", "mohs-surgery"], sections: ["surgery", "diagnostics"] }),
  t({ id: "tumour-differentiation", name: "Tumour differentiation (well / moderately / poorly differentiated)", category: "Pathology & biomarkers", aka: ["well-differentiated", "well differentiated", "moderately differentiated", "poorly differentiated", "poorly-differentiated", "undifferentiated", "dedifferentiated", "differentiated thyroid cancer", "differentiated"], tldr: "How much the cancer cells still resemble the normal tissue they came from. Well-differentiated tumours look almost normal and tend to grow slowly; poorly differentiated ones have lost their identity and behave aggressively. It is the basis of grade.", summary: "Pathologists assign differentiation from gland formation, nuclear appearance and mitotic rate; it underlies grading systems such as Gleason (prostate), Nottingham (breast) and WHO grade for neuroendocrine tumours (well-differentiated NETs versus poorly differentiated neuroendocrine carcinomas, which are treated like small-cell cancer). Well-differentiated mucosal gastric cancers qualify for endoscopic resection; poorly differentiated thyroid cancer loses iodine uptake. Dedifferentiation over time (liposarcoma, thyroid, prostate to neuroendocrine) marks transformation to a more aggressive state.", wikipedia: W("Grading_(tumors)"), cancers: ["neuroendocrine", "thyroid", "prostate"], related: ["gleason-grade-group", "adenocarcinoma", "dysplasia"], sections: ["diagnostics"] }),
  t({ id: "dysplasia", name: "Dysplasia (pre-cancerous change)", category: "Pathology & biomarkers", aka: ["dysplastic", "high-grade dysplasia", "low-grade dysplasia", "atypical hyperplasia", "atypia", "intraepithelial neoplasia", "CIN", "premalignant", "pre-malignant", "precancerous", "pre-cancerous", "precursor lesion", "precursor lesions"], tldr: "Abnormal-looking cells in a surface lining that are not yet cancer but are on the way. Finding and removing dysplasia (cervical smears, Barrett's surveillance, colon polyps) is how screening prevents cancer rather than just detecting it early.", summary: "Dysplasia is graded low or high by how disordered the cells and architecture are; high-grade dysplasia is treated because a substantial fraction progresses to invasive cancer. Cervical intraepithelial neoplasia (CIN 2-3) is excised or ablated; Barrett's with dysplasia is ablated by radiofrequency after endoscopic resection; adenomatous polyps are removed at colonoscopy; oral leukoplakia and anal intraepithelial neoplasia are watched or treated. Atypical hyperplasia of the breast raises risk and can justify preventive tamoxifen. Carcinoma in situ is the most severe form, in which the whole epithelium is malignant but has not invaded.", wikipedia: W("Dysplasia"), cancers: ["cervical", "esophageal", "colorectal"], related: ["carcinoma-in-situ", "barretts-esophagus", "colonoscopy", "hpv-status"], sections: ["early-detection", "prevention"] }),
  t({ id: "carcinoma-in-situ", name: "Carcinoma in situ (CIS)", category: "Pathology & biomarkers", aka: ["CIS", "in situ carcinoma", "in situ", "Tis", "lobular carcinoma in situ", "LCIS", "stage 0", "non-invasive cancer", "intraepithelial"], tldr: "Cancer cells that fill the lining layer where they started but have not broken through the basement membrane into the tissue beneath. They cannot spread yet, so removal is usually curative; it is 'stage 0'.", summary: "Staged as Tis, in situ disease is found in breast (ductal and lobular), bladder (flat CIS, which is aggressive and treated with BCG), cervix (CIN 3), skin (Bowen's disease, melanoma in situ), oesophagus and lung (adenocarcinoma in situ). Whether and how fast it would have progressed is often unknowable, which raises overdiagnosis questions in screening. Treatment is local (excision, ablation, intravesical therapy) without systemic chemotherapy, sometimes with radiotherapy or endocrine therapy for breast DCIS.", wikipedia: W("Carcinoma_in_situ"), cancers: ["urothelial", "cervical", "melanoma"], related: ["dcis", "dysplasia", "intravesical-therapy", "tnm-staging"], sections: ["early-detection"] }),
  t({ id: "dcis", name: "Ductal carcinoma in situ (DCIS)", category: "Pathology & biomarkers", aka: ["DCIS", "ductal carcinoma in situ", "ductal in situ"], tldr: "Breast cancer cells confined inside the milk ducts, found mostly by mammography as calcifications. It is not life-threatening in itself, but around a third would progress to invasive cancer if left.", summary: "DCIS makes up 20-25% of screen-detected breast cancers. Standard treatment is lumpectomy with radiotherapy (or mastectomy for extensive disease) plus tamoxifen or an aromatase inhibitor if ER-positive; low-dose tamoxifen (5 mg, TAM-01) halves recurrence with fewer side effects. Because many DCIS lesions are indolent, active surveillance trials (COMET, LORIS, LORD) tested omitting surgery for low-risk disease, and COMET found no excess invasive cancer at 2 years. It is a leading example of the overdiagnosis debate in screening.", wikipedia: W("Ductal_carcinoma_in_situ"), cancers: ["breast-hr-positive"], drugs: ["tamoxifen"], related: ["carcinoma-in-situ", "lumpectomy", "active-surveillance"], sections: ["early-detection"] }),
  t({ id: "pd-l1-testing", name: "PD-L1 expression testing (22C3, SP142, SP263)", category: "Pathology & biomarkers", aka: ["PD-L1 expression", "PD-L1-positive", "PD-L1 positive", "PD-L1-negative", "PD-L1 negative", "PD-L1-high", "PD-L1 high", "PD-L1-low", "PD-L1 status", "PD-L1 IHC", "22C3", "SP142", "SP263", "28-8", "PD-L1 ≥50%", "PD-L1 ≥1%"], tldr: "A stain on the tumour biopsy that measures how much of the PD-L1 'don't attack me' protein is present, scored as a tumour proportion or combined positive score. Higher levels usually mean checkpoint inhibitors work better, and approvals in lung, triple-negative breast, gastric and head and neck cancer set minimum scores; yet PD-L1-negative tumours sometimes respond.", summary: "Several antibody clones (22C3 for pembrolizumab, SP142 for atezolizumab, SP263 for durvalumab, 28-8 for nivolumab) and scoring systems (tumour proportion score, combined positive score, immune cell score) are in use and are only partly interchangeable (Blueprint project), which complicates practice. PD-L1 ≥50% TPS in lung cancer permits pembrolizumab alone; CPS ≥10 gates pembrolizumab in triple-negative breast and CPS ≥1 or ≥5 in gastric and head and neck cancer. It is an imperfect biomarker: PD-L1-negative tumours sometimes respond and expression is heterogeneous and changes with treatment.", wikipedia: W("PD-L1"), targets: ["pdl1"], technologies: ["checkpoint-inhibitor", "histopathology-ihc", "companion-diagnostic"], related: ["cps", "tmb", "immuno-oncology"], sections: ["immunotherapy", "diagnostics"] }),
  t({ id: "hormone-receptor-status", name: "Hormone receptor status (ER / PR)", category: "Pathology & biomarkers", aka: ["ER/PR", "ER-positive", "ER positive", "ER+", "ER-negative", "ER−", "PR-positive", "PR+", "HR-positive", "HR+", "HR-negative", "HR−", "hormone receptor-positive", "hormone receptor positive", "hormone-receptor-positive", "oestrogen receptor-positive", "progesterone receptor", "ER-low", "PgR", "estrogen receptor-positive", "estrogen receptor positive", "estrogen-receptor-positive", "oestrogen-receptor-positive", "oestrogen-driven", "estrogen-driven", "luminal", "luminal A", "luminal B"], tldr: "Whether a breast cancer's cells carry receptors for oestrogen (ER) and progesterone (PR). If they do, the cancer is fed by these hormones and can be treated by blocking them; about 70% of breast cancers are hormone receptor-positive.", summary: "Measured by immunohistochemistry on every breast cancer; ≥1% of nuclei staining counts as positive (1-10% is 'ER-low' and behaves more like negative). HR-positive/HER2-negative disease receives endocrine therapy (tamoxifen, aromatase inhibitors, SERDs) with CDK4/6 inhibitors in high-risk or metastatic settings; HR status combined with HER2 defines the four clinical subtypes (HR+/HER2−, HER2+, triple-negative). Endometrial, ovarian and some other cancers are also ER/PR tested. Loss of ER at relapse and ESR1 mutations mark endocrine resistance.", wikipedia: W("Estrogen_receptor"), cancers: ["breast-hr-positive", "tnbc"], targets: ["estrogen-receptor"], technologies: ["endocrine-therapy", "histopathology-ihc"], related: ["her2-positive", "aromatase-inhibitor", "serd", "endocrine-resistance"], sections: ["hormonal", "diagnostics"] }),
  t({ id: "her2-positive", name: "HER2-positive (IHC 3+ or ISH-amplified)", category: "Pathology & biomarkers", aka: ["HER2-positive", "HER2 positive", "HER2+", "HER2-negative", "HER2 negative", "HER2−", "IHC 3+", "IHC 2+", "HER2 IHC", "HER2-amplified", "HER2 amplification", "ISH-amplified", "HER2 overexpression", "HER2-overexpressing", "HER2-mutant", "HER2 status", "ASCO/CAP"], tldr: "A cancer with too much HER2 growth-signal protein, either scored 3+ on the stain or shown to have extra copies of the gene. Once the most aggressive breast cancer subtype, it is now among the most treatable thanks to anti-HER2 drugs.", summary: "About 15-20% of breast cancers and a similar share of gastric/GEJ cancers are HER2-positive by ASCO/CAP criteria (IHC 3+, or IHC 2+ with in situ hybridisation amplification). They receive trastuzumab, pertuzumab, T-DM1 and T-DXd in curative and metastatic settings, with response-adapted pathways (KATHERINE, DESTINY-Breast). HER2-low (IHC 1+ or 2+/ISH-negative) and ultralow tumours are not 'positive' but respond to T-DXd, so the category is now a spectrum. HER2 mutations (rather than amplification) in lung cancer are targeted by T-DXd and zongertinib; HER2 amplification also occurs in colorectal, bladder and biliary cancers.", wikipedia: W("HER2"), cancers: ["breast-her2-positive", "gastric", "nsclc"], targets: ["her2"], drugs: ["trastuzumab", "trastuzumab-deruxtecan", "pertuzumab"], trials: ["katherine", "aphinity"], related: ["her2-low", "fish", "hormone-receptor-status", "ihc"], sections: ["targeted-therapy", "diagnostics"] }),
  t({ id: "fish", name: "FISH / ISH (in situ hybridisation)", category: "Pathology & biomarkers", aka: ["FISH", "ISH", "in situ hybridisation", "in situ hybridization", "fluorescence in situ hybridization", "fluorescence in situ hybridisation", "break-apart FISH", "EBER in situ hybridisation", "EBER"], tldr: "A test that uses glowing DNA probes on a tissue slide to count gene copies or spot rearranged genes inside individual cells, used to confirm HER2 amplification, MYCN in neuroblastoma, or ALK and MYC rearrangements.", summary: "Fluorescence in situ hybridisation (or chromogenic ISH) shows whether a gene is amplified (extra signals per nucleus, as in HER2 with ratio ≥2.0 or ≥6 copies), deleted (del(17p) in CLL, 1p/19q in oligodendroglioma) or broken and rejoined (break-apart probes for ALK, ROS1, MYC, BCL2, BCL6 in 'double-hit' lymphoma). It works on routine fixed tissue and resolves equivocal IHC 2+ HER2 results. Interphase FISH is standard in myeloma and leukaemia cytogenetics; EBER ISH detects Epstein-Barr virus in tumours. NGS increasingly replaces it for fusions.", wikipedia: W("Fluorescence_in_situ_hybridization"), technologies: ["histopathology-ihc", "cgp"], related: ["her2-positive", "cytogenetics", "gene-amplification", "gene-fusion"], sections: ["diagnostics"] }),
  t({ id: "tumour-markers", name: "Tumour markers (CEA, LDH, chromogranin, thyroglobulin)", category: "Pathology & biomarkers", aka: ["tumour marker", "tumor marker", "tumor markers", "serum markers", "CEA", "LDH", "Lactate dehydrogenase", "lactate dehydrogenase", "LDH level", "raised LDH", "elevated LDH", "chromogranin", "thyroglobulin", "calcitonin", "beta-hCG", "hCG", "5-HIAA", "NSE", "CA 15-3", "CA 72-4"], tldr: "Substances released into the blood by some cancers that can be measured with a simple test, useful for tracking whether treatment is working or the cancer is coming back, but rarely good enough to diagnose or screen.", summary: "CEA is followed after colorectal cancer surgery and in monitoring metastatic disease. LDH is prognostic in melanoma, lymphoma (part of the IPI) and germ cell tumours; AFP and hCG diagnose and stage testicular cancer; chromogranin A and 5-HIAA track neuroendocrine tumours; thyroglobulin monitors differentiated thyroid cancer after thyroidectomy and calcitonin monitors medullary thyroid cancer; PSA, CA-125 and CA 19-9 have their own entries. Markers rise in benign conditions too, so they are interpreted as trends alongside imaging; ctDNA is increasingly the more specific alternative.", wikipedia: W("Tumor_marker"), cancers: ["colorectal", "neuroendocrine", "thyroid", "melanoma"], related: ["ctdna", "cfdna", "muc16"], sections: ["diagnostics"] }),
  t({ id: "child-pugh", name: "Child-Pugh score", category: "Pathology & biomarkers", aka: ["Child-Pugh", "Child-Pugh A", "Child-Pugh B", "Child-Pugh class", "Child–Pugh", "ALBI", "ALBI grade", "liver function reserve"], tldr: "A score of how well a damaged liver is still working, from five simple measures (bilirubin, albumin, clotting, fluid in the abdomen, confusion). Class A is well compensated, C is failing. Liver cancer trials almost all require class A.", summary: "Because hepatocellular carcinoma nearly always arises in cirrhosis, the liver's reserve determines whether a patient can survive resection, tolerate TACE or radioembolisation, or be given systemic therapy, and it competes with the cancer as a cause of death. Almost every phase 3 trial in liver cancer enrolled Child-Pugh A patients only, so evidence in class B is thin. The ALBI grade (albumin and bilirubin only) is a more objective alternative used in modern trials and in the BCLC algorithm.", wikipedia: W("Child%E2%80%93Pugh_score"), cancers: ["hcc"], related: ["cirrhosis", "bclc-staging", "hepatectomy"], sections: ["diagnostics"] }),
  t({ id: "cirrhosis", name: "Cirrhosis", category: "Pathology & biomarkers", aka: ["cirrhotic", "liver cirrhosis", "liver fibrosis", "MASLD", "MASH", "NASH", "NAFLD", "fatty liver", "chronic hepatitis B", "hepatitis B", "hepatitis C"], tldr: "Permanent scarring of the liver after years of damage from hepatitis B or C, alcohol or fatty liver disease. It is the soil in which most liver cancers grow, and its severity limits which cancer treatments a patient can withstand.", summary: "Around 80-90% of hepatocellular carcinomas arise in cirrhotic livers, at roughly 2-4% per year, which is why patients with cirrhosis are offered six-monthly ultrasound and AFP surveillance. Hepatitis B vaccination and antiviral therapy, hepatitis C cure with direct-acting antivirals and, prospectively, GLP-1 agonists for metabolic liver disease are the main preventive levers. Cirrhosis also complicates treatment: it causes portal hypertension, low platelets and impaired drug clearance, and is graded by Child-Pugh and ALBI for treatment eligibility.", wikipedia: W("Cirrhosis"), cancers: ["hcc"], related: ["child-pugh", "bclc-staging", "portal-vein-tumour-thrombus"], sections: ["prevention"] }),
  t({ id: "hpv-status", name: "HPV status (HPV-positive / HPV-negative)", category: "Pathology & biomarkers", aka: ["HPV-positive", "HPV positive", "HPV-negative", "HPV negative", "HPV-driven", "HPV-associated", "HPV-related", "high-risk HPV", "HPV16", "HPV 16", "ctHPV", "ctHPV DNA", "HPV ctDNA", "HPV DNA"], tldr: "Whether a cancer is caused by human papillomavirus. HPV-positive throat cancers are a different, far more curable disease than smoking-related ones, and the virus's DNA in blood can track the cancer.", summary: "Persistent high-risk HPV (types 16 and 18 mainly) causes virtually all cervical cancer and rising shares of oropharyngeal, anal, vulval and penile cancers; p16 immunohistochemistry is the surrogate marker in the oropharynx. HPV-positive oropharyngeal cancer has 3-year survival above 80% and its own AJCC staging, so trials test de-escalating radiotherapy dose or omitting chemotherapy, none of which has yet succeeded in a randomised trial. Circulating HPV DNA (ctHPV) detects recurrence months before imaging. HPV vaccination and HPV-based cervical screening are the route to eliminating cervical cancer.", wikipedia: W("Human_papillomavirus_infection"), cancers: ["head-and-neck", "cervical"], technologies: ["hpv-vaccine"], related: ["head-neck-subsites", "squamous-cell-carcinoma", "dysplasia", "ctdna"], sections: ["prevention", "diagnostics"] }),
  t({ id: "ebv-term", name: "Epstein-Barr virus (EBV) in cancer", category: "Pathology & biomarkers", aka: ["EBV", "Epstein-Barr", "Epstein–Barr virus", "EBV-positive", "EBV-associated", "EBV-driven", "EBV DNA", "EBER"], tldr: "The common glandular-fever virus, carried lifelong by most adults, which in a minority of people drives nasopharyngeal cancer, some stomach cancers and several lymphomas.", summary: "EBV infects B cells and epithelium; it causes nearly all nasopharyngeal carcinoma (endemic in southern China), about 9% of gastric cancers (a TCGA subtype with high PD-L1 and immunotherapy sensitivity), Burkitt lymphoma, Hodgkin lymphoma in part, post-transplant lymphoproliferative disease and NK/T-cell lymphoma. Plasma EBV DNA screens for and monitors nasopharyngeal cancer; EBV-specific T cells (tabelecleucel) treat post-transplant lymphoma; EBV vaccines are in early trials. EBER in situ hybridisation is the tissue test.", wikipedia: W("Epstein%E2%80%93Barr_virus"), cancers: ["head-and-neck", "gastric", "hodgkin-lymphoma", "dlbcl"], related: ["plasma-ebv-dna", "fish", "hpv-status"], sections: ["diagnostics"] }),
  t({ id: "mss-pmmr", name: "Microsatellite-stable (MSS) / mismatch-repair proficient (pMMR)", category: "Pathology & biomarkers", aka: ["MSS", "pMMR", "microsatellite-stable", "microsatellite stable", "mismatch repair proficient", "mismatch-repair proficient", "MMR-proficient", "MMR proficient", "MSI-low", "MSS/pMMR"], tldr: "The 'normal' result on the mismatch-repair test: the tumour has intact DNA spell-checking and few mutations. It describes about 95% of metastatic colorectal cancers and means checkpoint inhibitors alone are unlikely to work.", summary: "The opposite of MSI-high/dMMR. MSS tumours have low mutational burden and few neoantigens, so PD-1 blockade produced almost no responses in colorectal cancer (KEYNOTE-016), and the immunotherapy revolution in dMMR colorectal and endometrial cancer (CheckMate 8HW, dostarlimab) has bypassed them. Making MSS colorectal cancer immune-responsive with combinations (botensilimab-balstilimab, KRAS inhibitors plus PD-1, cancer vaccines) is one of the field's biggest open problems. In endometrial cancer pMMR patients benefit less from adding immunotherapy to chemotherapy but still gain (RUBY, NRG-GY018).", wikipedia: W("Microsatellite_instability"), cancers: ["colorectal", "endometrial"], trials: ["checkmate-8hw"], related: ["msi", "tmb", "cold-vs-hot", "immuno-oncology"], sections: ["immunotherapy", "diagnostics"] }),
  t({ id: "gbrca-mutation", name: "Germline BRCA mutation (gBRCA)", category: "Pathology & biomarkers", aka: ["gBRCA", "gBRCAm", "BRCA-mutated", "BRCA-mutant", "BRCA mutation", "BRCA carriers", "BRCA carrier", "BRCA1/2", "BRCA1", "BRCA2", "sBRCA", "somatic BRCA", "BRCA-deficient", "BRCA wild-type", "BRCA status", "HRR mutation", "HRR-mutant", "HRRm", "PALB2", "BRCA mutations"], tldr: "An inherited fault in the BRCA1 or BRCA2 gene, present in every cell from birth, that greatly raises the risk of breast, ovarian, prostate and pancreatic cancer and makes those cancers sensitive to PARP inhibitors and platinum.", summary: "About 1 in 300-400 people (1 in 40 in Ashkenazi Jews) carries a pathogenic germline BRCA variant; lifetime breast cancer risk is 60-70% and ovarian 20-45%. Testing is now offered to all ovarian, pancreatic and metastatic prostate cancer patients, to triple-negative and young breast cancer patients, and increasingly to all breast cancer patients, with cascade testing of relatives. Carriers get intensified screening, risk-reducing mastectomy and salpingo-oophorectomy, and PARP inhibitors: adjuvant olaparib (OlympiA), maintenance in ovarian cancer (SOLO-1) and in prostate and pancreatic cancer. Somatic (tumour-only) BRCA mutations respond similarly; HRR genes such as PALB2, ATM and RAD51C extend the concept.", wikipedia: W("BRCA_mutation"), targets: ["brca"], technologies: ["parp-inhibitor", "germline-testing"], drugs: ["olaparib"], trials: ["olympia"], cancers: ["ovarian", "tnbc", "prostate", "pancreatic"], related: ["hrd", "germline-vs-somatic", "hereditary-cancer-syndromes", "salpingo-oophorectomy"], sections: ["targeted-therapy", "prevention"] }),
  t({ id: "wild-type", name: "Wild-type (WT)", category: "Pathology & biomarkers", aka: ["wild type", "wildtype", "RAS wild-type", "KRAS wild-type", "BRAF wild-type", "TP53 wild-type", "TP53-wild-type", "EGFR wild-type", "unmutated"], tldr: "The normal, unmutated version of a gene. Saying a tumour is 'RAS wild-type' means its RAS gene is not mutated, which for colorectal cancer means EGFR antibodies can work.", summary: "Borrowed from genetics, wild-type is the reference sequence against which mutations are defined. It matters when a mutation predicts resistance rather than sensitivity: only RAS/BRAF wild-type colorectal cancers respond to cetuximab or panitumumab; TP53 wild-type tumours can respond to MDM2 inhibitors; unmutated IGHV in CLL predicts shorter remissions with chemoimmunotherapy. Because 'wild-type' depends on what was tested, a tumour can be wild-type on a small panel and mutated on a larger one.", wikipedia: W("Wild_type"), related: ["driver-mutation", "kras-mutation-subtypes", "tp53-mutated", "cgp"], sections: ["diagnostics"] }),
  t({ id: "gene-amplification", name: "Gene amplification and copy-number change", category: "Pathology & biomarkers", aka: ["amplification", "amplified", "amplifications", "copy number", "copy-number", "copy number alteration", "copy number gain", "gene copy number", "MYCN-amplified", "MET amplification", "CCNE1 amplification", "deletion", "homozygous deletion", "del(17p)", "1q gain", "loss of heterozygosity", "LOH", "genomic instability", "chromosomal instability", "aneuploidy"], tldr: "Cancer cells often have extra copies of a growth gene (amplification) or have lost copies of a protective one (deletion), rather than a spelling change within the gene. Extra copies of HER2 or MYCN are classic examples that change treatment.", summary: "Amplification (detected by FISH, ISH or NGS copy-number calls) drives overexpression: HER2 in breast and gastric cancer, MYCN in high-risk neuroblastoma, MET amplification as a resistance route to EGFR inhibitors, CCNE1 in ovarian and gastric cancer, MDM2 in liposarcoma, CDK4 in glioma. Deletions remove tumour suppressors: del(17p)/TP53 in CLL and myeloma (predicting chemo-resistance), CDKN2A/B in glioma (defining grade 4), MTAP (creating a PRMT5 vulnerability), 9p21 loss linked to immunotherapy resistance. Loss of heterozygosity and large-scale copy changes are summed into genomic-scar scores used to infer HRD and predict PARP inhibitor benefit.", wikipedia: W("Gene_duplication"), targets: ["her2", "mdm2", "prmt5-mtap"], technologies: ["cgp", "histopathology-ihc"], related: ["fish", "her2-positive", "hrd", "cytogenetics"], sections: ["diagnostics"] }),
  t({ id: "egfr-mutation-subtypes", name: "EGFR mutation subtypes (exon 19 deletion, L858R, exon 20 insertion, T790M)", category: "Pathology & biomarkers", aka: ["EGFR-mutant", "EGFR-mutated", "EGFR mutation", "EGFR mutations", "EGFR-positive", "exon 19 deletion", "exon 19 del", "ex19del", "L858R", "exon 20 insertion", "exon 20 ins", "ex20ins", "T790M", "C797S", "uncommon EGFR mutations", "G719X", "S768I", "L861Q", "EGFR-TKI", "EGFR TKI", "EGFR inhibitor", "EGFR inhibitors"], tldr: "Lung cancers with a mutated EGFR gene are treated with EGFR pills, but which pill and how well it works depends on exactly where the mutation is. Exon 19 deletions and L858R are the 'classic' sensitive ones; exon 20 insertions resist most pills; T790M and C797S appear when resistance develops.", summary: "EGFR mutations occur in about 15% of Western and 40-50% of East Asian lung adenocarcinomas, mostly in never-smokers. Exon 19 deletions (best outcomes) and L858R respond to osimertinib, now standard first line (FLAURA) and adjuvant (ADAURA), with amivantamab-lazertinib (MARIPOSA) or osimertinib plus chemotherapy (FLAURA2) as intensified options. Exon 20 insertions need amivantamab or sunvozertinib. T790M was the resistance mutation to first-generation TKIs that osimertinib overcame; C797S and MET amplification are the main escape routes from osimertinib. Testing is by tissue NGS or plasma ctDNA at diagnosis and at progression.", wikipedia: W("Epidermal_growth_factor_receptor"), cancers: ["nsclc"], targets: ["egfr"], drugs: ["osimertinib", "gefitinib", "erlotinib", "afatinib", "sunvozertinib"], trials: ["adaura"], related: ["driver-mutation", "gatekeeper-mutation", "tki-term", "cfdna"], sections: ["targeted-therapy"] }),
  t({ id: "kras-mutation-subtypes", name: "KRAS mutation subtypes (G12C, G12D, G12V)", category: "Pathology & biomarkers", aka: ["G12C", "G12D", "G12V", "G12R", "G13D", "Q61H", "KRAS G12C", "KRAS G12D", "KRAS-mutant", "KRAS-mutated", "KRAS mutation", "KRAS mutations", "RAS-mutant", "RAS mutation", "RAS-mutated", "non-G12C", "pan-RAS", "pan-KRAS", "RAS(ON)", "RAS(OFF)", "RAS mutations"], tldr: "KRAS, the most commonly mutated cancer gene, comes in flavours named by the exact amino acid change. G12C (common in smokers' lung cancer) was the first to get a drug; G12D dominates pancreatic and colorectal cancer and its inhibitors are arriving now.", summary: "KRAS is mutated in about 90% of pancreatic, 40% of colorectal and 30% of lung adenocarcinomas. The G12C variant (13% of lung adenocarcinoma) is targeted by sotorasib and adagrasib, approved in 2021-22 with modest durability; G12D (40% of pancreatic cancer) is the target of zoldonrasib and others; daraxonrasib and related RAS(ON) multi-selective inhibitors cover several variants and produced the first positive phase 3 in pancreatic cancer. Variant also predicts behaviour: G12C lung tumours are smoking-related and immunogenic, while colorectal KRAS mutations of any type preclude EGFR antibodies. Co-mutations (STK11, KEAP1, TP53) modify prognosis and immunotherapy benefit.", wikipedia: W("KRAS"), cancers: ["nsclc", "pancreatic", "colorectal"], targets: ["kras"], technologies: ["kras-inhibitors"], drugs: ["sotorasib", "adagrasib"], related: ["driver-mutation", "wild-type", "stk11-keap1"], sections: ["targeted-therapy"] }),
  t({ id: "braf-v600-mutation", name: "BRAF V600E mutation", category: "Pathology & biomarkers", aka: ["V600E", "V600", "BRAF V600E", "BRAF V600", "BRAF-mutant", "BRAF-mutated", "BRAF mutation", "BRAF-mutant melanoma", "BRAF/MEK", "BRAF + MEK", "class II BRAF", "class III BRAF", "BRAF inhibitor", "MEK inhibitor", "BRAF inhibitors", "MEK inhibitors"], tldr: "A single spelling change in the BRAF gene that jams a growth switch permanently on. It is found in half of melanomas and in some colon, thyroid, lung and brain tumours, and is treated with a BRAF pill plus a MEK pill.", summary: "V600E (valine to glutamate at position 600) is the commonest BRAF mutation; class II and III mutations behave differently and resist the same drugs. Dabrafenib-trametinib, encorafenib-binimetinib and vemurafenib-cobimetinib treat metastatic and adjuvant melanoma, with immunotherapy usually given first in metastatic disease (DREAMseq). Encorafenib-cetuximab treats BRAF-mutant colorectal cancer (BEACON), dabrafenib-trametinib has a tumour-agnostic approval including glioma and thyroid cancer, and the combination has moved into paediatric low-grade glioma. BRAF-mutant colorectal cancer is aggressive and often overlaps with MSI-high sporadic tumours.", wikipedia: W("BRAF_(gene)"), cancers: ["melanoma", "colorectal", "thyroid", "nsclc"], targets: ["braf"], drugs: ["vemurafenib"], related: ["driver-mutation", "tumour-agnostic", "tki-term"], sections: ["targeted-therapy"] }),
  t({ id: "gatekeeper-mutation", name: "On-target resistance mutations (gatekeeper, solvent-front, compound)", category: "Pathology & biomarkers", aka: ["gatekeeper", "gatekeeper mutation", "solvent-front mutation", "solvent front", "compound mutations", "compound mutation", "G1202R", "G2032R", "on-target resistance", "secondary mutation", "resistance mutation", "acquired resistance mutation", "kinase domain mutation", "resistance mutations", "gatekeeper mutations", "secondary mutations", "solvent-front mutations"], tldr: "When a cancer becomes resistant to a targeted pill, it often does so by changing the exact spot where the drug binds: a 'gatekeeper' or 'solvent-front' mutation. Next-generation drugs are designed to fit around these changes.", summary: "Gatekeeper mutations (EGFR T790M, ABL T315I, KIT T670I) alter a residue at the entrance to the ATP pocket; solvent-front mutations (ALK G1202R, ROS1 G2032R, NTRK G595R) change the drug's contact surface; compound mutations stack two or more changes and defeat successive drug generations. Each generation of inhibitor answers the last: osimertinib for T790M, lorlatinib and neladalkib for G1202R, ponatinib and asciminib for T315I, repotrectinib for G2032R. Re-biopsy or ctDNA at progression identifies the mutation and guides the switch; off-target bypass (MET amplification, histologic transformation) is the other main route.", wikipedia: W("Drug_resistance"), targets: ["egfr", "alk", "ros1"], drugs: ["osimertinib", "ponatinib", "asciminib"], related: ["resistance", "egfr-mutation-subtypes", "tki-term", "cfdna"], sections: ["targeted-therapy"] }),
  t({ id: "stk11-keap1", name: "STK11 / KEAP1 co-mutations", category: "Pathology & biomarkers", aka: ["STK11", "KEAP1", "co-mutation", "co-mutations", "co-mutated", "STK11/KEAP1", "LKB1", "SMARCA4"], tldr: "Two genes whose loss, often alongside a KRAS mutation, makes lung cancer 'cold' to immunotherapy and shortens survival on standard treatment. They are the reason two KRAS-mutant lung cancers can behave completely differently.", summary: "STK11 (LKB1) and KEAP1 are inactivated in about 15-20% of lung adenocarcinomas each. Tumours with these losses have low PD-L1, few infiltrating T cells and poor responses to PD-1 blockade and chemo-immunotherapy, and KEAP1 loss also blunts chemotherapy and radiotherapy through antioxidant (NRF2) activation. They are stratification factors and exclusion criteria in modern lung trials, and are targets of dedicated strategies: glutaminase inhibition for KEAP1, and adding CTLA-4 blockade (POSEIDON subgroup) for STK11. SMARCA4 loss is a third co-mutation with similar prognostic weight.", wikipedia: W("STK11"), cancers: ["nsclc"], targets: ["kras"], related: ["kras-mutation-subtypes", "cold-vs-hot", "pd-l1-testing"], sections: ["immunotherapy", "targeted-therapy"] }),
  t({ id: "tp53-mutated", name: "TP53-mutated (p53-abnormal)", category: "Pathology & biomarkers", aka: ["TP53-mutated", "TP53-mutant", "TP53 mutation", "TP53 mutations", "TP53 loss", "TP53-altered", "p53abn", "p53-abnormal", "p53 abnormal", "p53-mutant", "mutant p53", "TP53/RB1", "TP53 and RB1", "multi-hit TP53"], tldr: "Loss of the p53 'guardian of the genome', the most commonly mutated gene in cancer. In blood cancers and several solid tumours a TP53 mutation marks the highest-risk group, resistant to chemotherapy and hard to treat.", summary: "TP53 is mutated in about half of all cancers and in almost all high-grade serous ovarian and small-cell lung cancers. Where it is variable it defines risk: TP53-mutated AML and MDS (especially multi-hit) have median survivals under a year and are excluded from many trials; del(17p)/TP53 CLL is treated with BTK inhibitors rather than chemoimmunotherapy; p53-abnormal endometrial cancer (by immunohistochemistry) is the aggressive molecular class that benefits from chemotherapy and trastuzumab if HER2-positive; TP53 and RB1 co-loss in prostate and lung adenocarcinoma predicts neuroendocrine transformation. Restoring p53 (eprenetapopt, MDM2 inhibitors for wild-type tumours) has so far disappointed.", wikipedia: W("P53"), targets: ["tp53", "mdm2"], cancers: ["aml", "cll", "endometrial", "ovarian"], related: ["wild-type", "cytogenetics", "li-fraumeni"], sections: ["diagnostics"] }),
  t({ id: "cytogenetics", name: "Cytogenetics and karyotype", category: "Pathology & biomarkers", aka: ["cytogenetic", "karyotype", "complex karyotype", "monosomal karyotype", "chromosomal abnormalities", "high-risk cytogenetics", "adverse cytogenetics", "favourable cytogenetics", "translocation", "t(4;14)", "t(11;14)", "t(8;21)", "inv(16)", "hyperdiploid", "hypodiploid", "metaphase", "translocations", "karyotypes"], tldr: "Looking at a cancer's chromosomes under the microscope to find missing, extra, broken or swapped pieces. It has been the main risk-sorting tool in leukaemia, myeloma and lymphoma for decades.", summary: "Conventional karyotyping needs dividing cells and gives a whole-genome overview at low resolution; FISH targets specific abnormalities; NGS and optical genome mapping are replacing both. Cytogenetic risk groups drive treatment: t(8;21) and inv(16) AML are favourable and avoid transplant, complex or monosomal karyotypes are adverse; t(4;14), del(17p) and 1q gain define high-risk myeloma; hypodiploidy is adverse in childhood ALL; t(11;14) myeloma predicts venetoclax sensitivity. The Philadelphia chromosome t(9;22) is the founding example. Solid tumours use the same ideas for sarcoma translocations (EWSR1-FLI1) and 1p/19q co-deletion in oligodendroglioma.", wikipedia: W("Cytogenetics"), cancers: ["aml", "multiple-myeloma", "all-leukemia", "cll"], targets: ["ewsr1-fli1"], related: ["fish", "philadelphia-chromosome", "gene-amplification", "gene-fusion"], sections: ["diagnostics"] }),
  t({ id: "flow-cytometry", name: "Flow cytometry (immunophenotyping)", category: "Pathology & biomarkers", aka: ["immunophenotype", "immunophenotyping", "multiparameter flow cytometry", "MFC", "next-generation flow", "NGF", "CD markers", "cluster of differentiation"], tldr: "A machine that streams cells one by one past lasers and reads the surface proteins (CD markers) each carries, identifying what kind of cell it is. It is how leukaemias and lymphomas are typed and how residual disease is counted.", summary: "Antibodies tagged with fluorescent dyes label CD19, CD20, CD33, CD34, CD38, BCMA and dozens of other markers; the pattern (immunophenotype) distinguishes B from T from myeloid lineages and normal from malignant cells. It diagnoses acute leukaemia, CLL and myeloma from blood or marrow within hours, and multiparameter or next-generation flow measures minimal residual disease to one cell in 100,000-1,000,000, guiding transplant and maintenance decisions. It also confirms that a CAR-T target (CD19, BCMA) is still present after relapse, since antigen loss is a recognised escape.", wikipedia: W("Flow_cytometry"), cancers: ["aml", "all-leukemia", "cll", "multiple-myeloma"], related: ["mrd", "umrd", "blasts", "antigen-escape"], sections: ["diagnostics"] }),
  t({ id: "blasts", name: "Blasts (leukaemic blast cells)", category: "Pathology & biomarkers", aka: ["blast count", "blast percentage", "leukaemic blasts", "leukemic blasts", "myeloblasts", "lymphoblasts", "blast crisis", "blast phase", "excess blasts", "circulating blasts"], tldr: "Immature blood cells that should mature in the marrow but in acute leukaemia multiply without growing up. The percentage of blasts in the marrow defines the disease: 20% or more is acute leukaemia.", summary: "Normal marrow has under 5% blasts; MDS with excess blasts has 5-19%; AML or ALL is diagnosed at ≥20% (or with defining genetic lesions at lower counts under WHO 2022/ICC). Blasts crowd out normal blood production, causing anaemia, infection and bleeding, and very high counts (hyperleukocytosis) can clog vessels. Remission is defined as under 5% marrow blasts with recovered counts, though flow cytometry and molecular MRD now detect disease far below that. In CML, progression from chronic phase to blast crisis (≥20% blasts) transforms a controllable disease into an acute leukaemia.", wikipedia: W("Blast_cell"), cancers: ["aml", "all-leukemia"], related: ["flow-cytometry", "mds", "complete-response-term", "philadelphia-chromosome"], sections: ["diagnostics"] }),
  t({ id: "cfdna", name: "Cell-free DNA (cfDNA)", category: "Pathology & biomarkers", aka: ["cfDNA", "cell-free DNA", "circulating cell-free DNA", "plasma DNA", "liquid biopsy", "plasma NGS", "plasma genotyping", "blood-based genotyping", "tissue-informed", "tumour-informed", "tumor-informed", "tumour-naive", "tumor-naive", "fragmentomics", "liquid biopsies"], tldr: "Short pieces of DNA floating in the blood, shed by dying cells all over the body. Most is from normal cells; the small tumour-derived fraction (ctDNA) is what liquid biopsies fish out.", summary: "A tube of blood contains nanograms of cell-free DNA, of which tumour DNA may be 0.01-10%. Assays detect it by deep sequencing with error correction (Guardant360, FoundationOne Liquid, MSK-ACCESS), by tumour-informed panels built from the patient's own tumour mutations (Signatera, RaDaR), or by methylation and fragment-size patterns that also reveal the tissue of origin (Galleri, fragmentomics). Uses span genotyping when tissue is scarce, resistance monitoring, MRD after surgery and multi-cancer screening. Pitfalls are CHIP-derived variants, low shedding by some tumours (brain, kidney) and pre-analytic handling, hence dedicated collection tubes.", wikipedia: W("Cell-free_fetal_DNA"), technologies: ["liquid-biopsy", "mced", "fragmentomics", "mrd-testing"], related: ["ctdna", "mrd", "clonal-haematopoiesis", "core-needle-biopsy"], sections: ["diagnostics"] }),
  t({ id: "umrd", name: "Undetectable MRD (uMRD / MRD-negative)", category: "Pathology & biomarkers", aka: ["uMRD", "MRD-negative", "MRD negative", "MRD negativity rate", "MRD-positive", "MRD positive", "MRD-persistent", "MRD persistence", "MRD-guided", "MRD-driven", "MRD-adapted", "sustained MRD negativity", "uMRD4", "MRD 10^-5", "MRD 10-6"], tldr: "The test for leftover cancer cells found none, down to the sensitivity of the assay (often one cell in 100,000 or a million). It is the deepest remission we can measure and is becoming a treatment goal and trial endpoint in blood cancers.", summary: "In CLL, undetectable MRD at the end of fixed-duration venetoclax therapy predicts years off treatment and defines when to stop; in myeloma, MRD negativity at 10^-5 or 10^-6 (by next-generation flow or sequencing) is accepted by the FDA as an early endpoint for accelerated approval and guides de-escalation trials; in ALL, converting MRD-positive to negative with blinatumomab (BLAST) was the basis of its approval; in AML, NPM1 or flow MRD decides who needs transplant. MRD-positive after therapy predicts relapse and triggers intensification. The depth (10^-4 versus 10^-6) matters and assays are not interchangeable.", wikipedia: W("Minimal_residual_disease"), cancers: ["cll", "multiple-myeloma", "all-leukemia", "aml"], drugs: ["venetoclax", "blinatumomab"], technologies: ["mrd-testing"], related: ["mrd", "flow-cytometry", "fixed-duration", "complete-response-term"], sections: ["diagnostics"] }),
  t({ id: "deauville", wikipedia: W("Deauville_Criteria"), links: [{ label: "Cheson et al., Lugano classification: recommendations for initial evaluation, staging and response assessment of Hodgkin and non-Hodgkin lymphoma (Journal of Clinical Oncology 2014)", url: "https://doi.org/10.1200/JCO.2013.54.8800" }], name: "Deauville score and PET-adapted therapy", category: "Pathology & biomarkers", aka: ["Deauville", "Deauville score", "interim PET", "end-of-treatment PET", "PET-adapted", "PET-guided", "PET-negative", "PET-positive", "PET-directed", "Lugano classification", "Lugano", "metabolic response", "complete metabolic response"], tldr: "A 1-to-5 scale for how brightly a lymphoma lights up on a PET scan, compared with the liver and the middle of the chest. Scores of 1-3 after two cycles mean the treatment is working and allow it to be shortened; 4-5 means intensify.", summary: "The Deauville five-point scale (1 no uptake; 2 ≤ mediastinum; 3 ≤ liver; 4 moderately above liver; 5 markedly above or new lesions) underpins the Lugano response criteria for lymphoma. Interim PET after two cycles is used to omit bleomycin or radiotherapy in Hodgkin lymphoma (RATHL, HD16/HD17), to escalate to BEACOPP in non-responders, and to shorten R-CHOP in early-stage DLBCL (FLYER). PET-adapted de-escalation is spreading to HER2-positive breast cancer (PHERGain, omitting chemotherapy in PET responders). A complete metabolic response is the PET equivalent of complete remission.", cancers: ["hodgkin-lymphoma", "dlbcl", "breast-her2-positive"], technologies: ["fdg-pet", "pet-ct"], related: ["complete-response-term", "de-escalation", "r-chop", "abvd-beacopp"], sections: ["imaging"] }),
  t({ id: "molecular-response", name: "Molecular response (MMR, MR4, treatment-free remission)", category: "Pathology & biomarkers", aka: ["major molecular response", "MR4", "MR4.5", "deep molecular response", "complete molecular response", "BCR-ABL1 transcript", "BCR::ABL1 IS", "International Scale", "treatment-free remission", "TFR", "molecular relapse", "cytogenetic response", "complete cytogenetic response", "early molecular response", "cytogenetic responses", "molecular responses"], tldr: "In chronic myeloid leukaemia, how far the leukaemia gene signal in the blood has fallen, measured in logs: a 1,000-fold drop is a major molecular response, a 10,000-fold drop (MR4) is 'deep'. Deep responses held for two years let some patients stop their pills.", summary: "Quantitative PCR for BCR::ABL1 transcripts on the International Scale defines milestones: ≤10% at 3 months (early molecular response), ≤1% (complete cytogenetic response equivalent), ≤0.1% (MMR) by 12 months, ≤0.01% (MR4) and ≤0.0032% (MR4.5). Missing milestones triggers a switch of TKI. Sustained deep response for at least two years permits a supervised stop; about half stay in treatment-free remission and the rest regain response on restarting (EURO-SKI). 'Molecular relapse' is a rising transcript before any clinical sign. The concept is being borrowed for ctDNA-guided stopping in solid tumours.", wikipedia: W("Chronic_myelogenous_leukemia"), drugs: ["imatinib", "asciminib", "nilotinib", "dasatinib"], related: ["philadelphia-chromosome", "umrd", "tki-term", "fixed-duration"], sections: ["targeted-therapy", "diagnostics"] }),
  t({ id: "philadelphia-chromosome", name: "Philadelphia chromosome (Ph+, BCR::ABL1)", category: "Pathology & biomarkers", aka: ["Philadelphia", "Ph+", "Ph-positive", "Ph-negative", "BCR-ABL", "BCR-ABL1", "BCR::ABL1", "t(9;22)", "Philadelphia-positive", "Ph+ ALL", "p190 transcript", "p210 transcript", "BCR::ABL1 transcript type"], tldr: "A swapped piece between chromosomes 9 and 22 that fuses two genes into BCR::ABL1, a runaway kinase. It causes chronic myeloid leukaemia and a hard-to-treat quarter of adult acute lymphoblastic leukaemia, and was the target of imatinib, the first modern targeted cancer drug.", summary: "Described by Nowell and Hungerford in 1960 and explained by Rowley in 1973, the Philadelphia chromosome defines CML and Ph+ ALL. Imatinib (2001) turned CML into a chronic condition with near-normal life expectancy; dasatinib, nilotinib, bosutinib, ponatinib (covers T315I) and asciminib (allosteric) followed. In Ph+ ALL, TKIs plus chemotherapy or chemotherapy-free TKI plus blinatumomab (GIMEMA D-ALBA) now cure most patients without transplant. Ph-like ALL has a similar gene expression signature without the fusion and responds to some of the same drugs. Detected by karyotype, FISH or PCR for the fusion transcript.", wikipedia: W("Philadelphia_chromosome"), cancers: ["all-leukemia"], drugs: ["imatinib", "dasatinib", "ponatinib", "asciminib", "blinatumomab"], related: ["molecular-response", "gene-fusion", "cytogenetics", "tki-term"], sections: ["targeted-therapy"] }),
  t({ id: "staging-systems", name: "Disease-specific staging and risk systems (FIGO, Ann Arbor, IPI, R-ISS, ELN, IMDC)", category: "Pathology & biomarkers", aka: ["FIGO", "FIGO stage", "AJCC", "AJCC 8th edition", "UICC", "Ann Arbor", "Ann Arbor staging", "R-ISS", "R2-ISS", "ISS stage", "ELN 2022", "ELN risk", "IMDC", "IMDC risk", "Heng criteria", "INRG", "COG risk group", "Rai stage", "Binet stage", "Masaoka", "Enneking", "risk group", "risk-group", "risk stratification", "risk-stratified", "prognostic index", "prognostic score", "nomogram"], tldr: "Beyond the generic TNM system, gynaecological cancers (FIGO), lymphoma (Ann Arbor, IPI), myeloma (R-ISS), AML (ELN), kidney cancer (IMDC), neuroblastoma (INRG) and CLL (Rai, Binet) each have their own system that combines stage, blood tests, genetics and fitness into risk groups. The name on the report tells you which rulebook sets the treatment intensity.", summary: "FIGO stages gynaecological cancers (with the 2023 endometrial revision adding molecular class). Ann Arbor/Lugano stages lymphoma and the IPI adds age, LDH, performance status and extranodal sites; R-ISS and R2-ISS combine stage, LDH and cytogenetics in myeloma; ELN 2022 assigns AML to favourable, intermediate or adverse genetic risk that decides transplant; IMDC (Heng) criteria stratify metastatic kidney cancer and select immunotherapy doublets; INRG and COG groups stratify neuroblastoma; Rai and Binet stage CLL. Each maps to a treatment intensity, is the basis of trial eligibility and stratification, and is periodically revised as new markers (ctDNA, MRD, gene expression) prove more predictive.", wikipedia: W("Cancer_staging"), related: ["tnm-staging", "gleason-grade-group", "bclc-staging", "cytogenetics", "performance-status"], sections: ["diagnostics"] }),
  t({ id: "performance-status", name: "Performance status (ECOG, Karnofsky)", category: "Pathology & biomarkers", aka: ["ECOG", "ECOG 0-1", "ECOG 0", "ECOG 1", "ECOG 2", "ECOG PS", "ECOG performance status", "Karnofsky", "Karnofsky score", "KPS", "PS 0-1", "poor performance status", "fit patients", "unfit patients", "frail", "frailty", "IMWG frailty index", "IMWG frailty score", "comorbidity", "comorbidities", "HCT-CI", "HCT comorbidity index", "cisplatin-ineligible", "platinum-ineligible", "transplant-eligible", "transplant-ineligible"], tldr: "A simple score of how well a patient can get about and look after themselves: ECOG 0 is fully active, 1 restricted from strenuous work, 2 up more than half the day, 3 in bed more than half the day, 4 bedbound. It predicts how treatment will be tolerated and gates almost every trial.", summary: "The ECOG/WHO scale (0-5) and the Karnofsky scale (100-0) are the standard fitness measures in oncology. Most phase 3 trials enrol only ECOG 0-1, so evidence for the many patients with PS 2-3 is thin; 'fit' versus 'unfit' (for intensive chemotherapy, cisplatin, transplant) is often decided by performance status plus organ function and comorbidity, and phrases like 'cisplatin-ineligible' or 'transplant-ineligible' define whole treatment pathways. Geriatric assessment captures frailty more precisely than PS and changes treatment in older adults. Poor PS caused by the cancer itself can improve dramatically when an effective targeted drug works.", wikipedia: W("Performance_status"), technologies: ["geriatric-assessment"], related: ["staging-systems", "cachexia", "sarcopenia", "dose-modification"], sections: ["supportive-care"] }),

  // ---- Treatment jargon ----
  t({ id: "chemoradiation", name: "Chemoradiation (chemoradiotherapy, CRT)", category: "Treatment jargon", aka: ["chemoradiotherapy", "chemo-radiotherapy", "chemoradiation", "definitive chemoradiation", "concurrent chemoradiation", "concurrent chemoradiotherapy", "sequential chemoradiation", "radiochemotherapy", "trimodality therapy", "trimodality", "bimodality"], tldr: "Radiotherapy given at the same time as chemotherapy, which sensitises the cancer to radiation. It is the curative treatment for cervical, anal, laryngeal and oropharyngeal cancers, stage III lung cancer and glioblastoma, and is given before surgery in oesophageal and rectal cancer, at the cost of more acute mouth and gullet inflammation.", summary: "Concurrent chemoradiation (usually with cisplatin, or 5-FU and mitomycin, or carboplatin-paclitaxel) is definitive treatment for cervical, anal, laryngeal and oropharyngeal cancers, stage III lung cancer (followed by durvalumab, PACIFIC), glioblastoma (with temozolomide) and bladder preservation (trimodality with TURBT), and is preoperative in oesophageal (CROSS) and rectal cancer. Concurrent beats sequential in most comparisons at the cost of more acute toxicity (mucositis, oesophagitis). Chemotherapy acts as a radiosensitiser rather than for its own systemic effect, so doses are lower than in systemic regimens.", wikipedia: W("Chemoradiotherapy"), cancers: ["cervical", "head-and-neck", "nsclc", "esophageal", "glioblastoma", "urothelial"], trials: ["pacific", "cross"], related: ["organ-preservation", "imrt-term", "mucositis"], sections: ["radiation", "chemotherapy"] }),
  t({ id: "induction-therapy", name: "Induction therapy", category: "Treatment jargon", aka: ["induction", "induction chemotherapy", "induction regimen", "remission induction", "re-induction", "reinduction", "induction failure", "primary refractory", "induction regimens"], tldr: "The first, most intensive block of treatment, intended to knock the cancer into remission. In leukaemia it is the hospital stay that clears the marrow; in solid tumours it is chemotherapy given before definitive local treatment.", summary: "In acute leukaemia, induction (7+3 cytarabine-anthracycline in AML, multi-agent chemotherapy in ALL) aims for a complete remission and is followed by consolidation and sometimes maintenance or transplant; failure to achieve remission ('primary refractory') is the worst prognostic sign. In myeloma, quadruplet induction precedes autologous transplant. In head and neck and nasopharyngeal cancer, induction chemotherapy before chemoradiation improves survival in nasopharyngeal carcinoma (gemcitabine-cisplatin) but not consistently elsewhere. The term overlaps with 'neoadjuvant' when surgery follows.", wikipedia: W("Induction_chemotherapy"), cancers: ["aml", "all-leukemia", "multiple-myeloma", "head-and-neck"], related: ["consolidation-therapy", "maintenance-therapy", "seven-plus-three", "complete-response-term"], sections: ["chemotherapy"] }),
  t({ id: "consolidation-therapy", name: "Consolidation therapy", category: "Treatment jargon", aka: ["consolidation", "consolidation chemotherapy", "consolidation immunotherapy", "post-remission therapy", "intensification"], tldr: "Treatment given after a good response to kill the cancer cells that are presumably left but cannot be seen, to make the remission last. Durvalumab after chemoradiation for lung cancer is the best-known example.", summary: "In leukaemia, consolidation courses of cytarabine (or transplant) follow induction to eradicate residual disease. In lymphoma, radiotherapy to bulky sites or autologous transplant consolidates chemotherapy response; in myeloma, consolidation follows transplant before maintenance. In solid tumours the word entered common use with PACIFIC (a year of durvalumab after chemoradiation in stage III lung cancer) and ADRIATIC (durvalumab after chemoradiation in limited-stage small-cell lung cancer), and 'consolidative' SBRT or surgery to residual oligometastatic disease follows the same logic.", wikipedia: W("Consolidation_therapy"), trials: ["pacific"], drugs: ["durvalumab"], cancers: ["nsclc", "sclc", "aml"], related: ["induction-therapy", "maintenance-therapy", "chemoradiation", "oligometastatic"], sections: ["chemotherapy", "immunotherapy"] }),
  t({ id: "salvage-therapy", name: "Salvage therapy", category: "Treatment jargon", aka: ["salvage", "salvage chemotherapy", "salvage surgery", "salvage radiotherapy", "salvage treatment", "salvage regimen", "salvage cystectomy", "salvage laryngectomy", "salvage transplant"], tldr: "Treatment given after the first treatment has failed or the cancer has come back, aiming to rescue the situation. It can still be curative (salvage surgery after organ-preservation fails) or a later line of palliation.", summary: "Salvage surgery removes the organ when chemoradiation or watch-and-wait fails (laryngectomy, cystectomy, abdominoperineal resection, TME after regrowth). Salvage radiotherapy treats a rising PSA after prostatectomy; salvage chemotherapy (ICE, DHAP, GDP) followed by autologous transplant was the standard for relapsed lymphoma until CAR-T proved superior in second line (ZUMA-7, TRANSFORM). Organ-preservation strategies are only safe where salvage is feasible and centres have the surgical capacity to deliver it.", wikipedia: W("Salvage_therapy"), trials: ["zuma-7", "transform"], related: ["organ-preservation", "relapsed-refractory", "first-line", "autologous-transplant"], sections: ["surgery", "chemotherapy"] }),
  t({ id: "relapsed-refractory", name: "Relapsed / refractory (R/R)", category: "Treatment jargon", aka: ["R/R", "relapsed/refractory", "relapsed or refractory", "relapsed and refractory", "refractory", "relapsed", "primary refractory", "chemorefractory", "chemo-refractory", "treatment-refractory", "heavily pretreated", "pretreated", "previously treated", "triple-class refractory", "penta-refractory", "BCG-refractory", "double-refractory"], tldr: "Relapsed means the cancer came back after responding; refractory means it never responded or grew during treatment. 'R/R' is the label on most trials of new blood cancer drugs.", summary: "The distinction matters for prognosis and drug choice: refractory disease is biologically more resistant, and the interval to relapse (early relapse within 12 months of chemoimmunotherapy in lymphoma, platinum-resistant relapse within 6 months in ovarian cancer) is itself a stratification factor. Regulators define trial populations by prior lines and drug classes, so terms such as 'triple-class refractory' (myeloma resistant to a proteasome inhibitor, an immunomodulator and a CD38 antibody) or 'BCG-unresponsive' bladder cancer describe specific unmet needs that new drugs are approved for. Most accelerated approvals are in R/R settings before drugs move to earlier lines.", wikipedia: W("Relapse"), related: ["first-line", "salvage-therapy", "platinum-sensitivity", "accelerated-approval", "resistance"], sections: ["chemotherapy"] }),
  t({ id: "platinum-sensitivity", name: "Platinum-sensitive / platinum-resistant", category: "Treatment jargon", aka: ["platinum-sensitive", "platinum sensitive", "platinum-resistant", "platinum resistant", "platinum-refractory", "platinum-free interval", "PFI", "platinum-eligible", "platinum-ineligible", "platinum-pretreated", "post-platinum", "platinum doublet", "platinum-based", "platinum-based chemotherapy", "platinum doublets", "platinum-etoposide", "carboplatin-paclitaxel", "platinum resistance"], tldr: "Whether a cancer that responded to platinum chemotherapy came back more than six months later (sensitive, so platinum can be used again) or sooner (resistant, so something else is needed). The dividing line shapes ovarian and small-cell lung cancer treatment.", summary: "In ovarian cancer, relapse ≥6 months after platinum is treated with another platinum doublet, often followed by PARP maintenance, and secondary cytoreduction may help; relapse within 6 months (resistant) or during treatment (refractory) has response rates under 15% to single agents and is where mirvetuximab (folate receptor alpha), and trials of new ADCs, are focused. Small-cell lung cancer uses a 90-day cut-off for platinum-etoposide rechallenge. 'Platinum-ineligible' (kidney function, hearing, neuropathy) defines a treatment pathway in bladder cancer. Platinum-resistance mechanisms include restored homologous recombination (BRCA reversion) and drug efflux.", wikipedia: W("Platinum-based_antineoplastic"), cancers: ["ovarian", "sclc", "urothelial"], technologies: ["platinum"], drugs: ["cisplatin", "carboplatin"], related: ["relapsed-refractory", "rechallenge", "hrd", "doublet-triplet"], sections: ["chemotherapy"] }),
  t({ id: "mcrpc-mhspc", name: "mCRPC and mHSPC (castration-resistant vs hormone-sensitive prostate cancer)", category: "Treatment jargon", aka: ["castration-resistant", "castration resistant", "castrate-resistant", "mCRPC", "nmCRPC", "CRPC", "castration-sensitive", "castration sensitive", "hormone-sensitive", "hormone sensitive", "mHSPC", "mCSPC", "HSPC", "hormone-naive", "hormone-refractory", "biochemical recurrence", "PSA recurrence", "rising PSA", "PSA progression", "rPFS"], tldr: "Prostate cancer starts out fed by testosterone (hormone-sensitive) and shrinks when it is removed. When it learns to grow despite castrate testosterone levels it is called castration-resistant, a later and more dangerous stage with its own treatments.", summary: "Metastatic hormone-sensitive disease (mHSPC) is treated with androgen deprivation plus an ARPI (abiraterone, enzalutamide, apalutamide, darolutamide) and sometimes docetaxel (STAMPEDE, LATITUDE, ARASENS), which delays castration resistance by years. Castration-resistant disease (CRPC), defined by PSA or radiographic progression with testosterone <50 ng/dL, arises through androgen receptor amplification, mutations, splice variants (AR-V7) and intratumoural androgen synthesis; it is treated with ARPI switch, docetaxel and cabazitaxel, PARP inhibitors for HRR mutations, 177Lu-PSMA-617 (VISION, PSMAfore) and radium-223. Non-metastatic CRPC (rising PSA, clear scans) has its own approvals. Radiographic PFS (rPFS) is the usual endpoint.", wikipedia: W("Prostate_cancer#Castration-resistant_prostate_cancer"), cancers: ["prostate"], targets: ["androgen-receptor"], trials: ["stampede", "latitude", "vision", "psmafore"], drugs: ["abiraterone", "enzalutamide"], related: ["castration-resistance", "adt", "arpi", "endocrine-resistance"], sections: ["hormonal"] }),
  t({ id: "adt", name: "Androgen deprivation therapy (ADT)", category: "Treatment jargon", aka: ["ADT", "androgen deprivation", "androgen-deprivation", "androgen suppression", "hormone therapy", "castration", "medical castration", "chemical castration", "castrate levels", "GnRH agonist", "GnRH antagonist", "LHRH agonist", "testosterone suppression", "short-term ADT", "long-term ADT", "intermittent ADT", "GnRH agonists"], tldr: "Switching off testosterone, the hormone that feeds prostate cancer, with injections (or tablets) that stop the testicles making it, or by removing them. It has been the backbone of advanced prostate cancer treatment since 1941.", summary: "GnRH agonists (leuprolide, goserelin) and antagonists (degarelix, oral relugolix) lower testosterone to castrate levels; bilateral orchiectomy does the same permanently. ADT is combined with radiotherapy for intermediate- and high-risk localised disease (4-6 months to 2-3 years), and with ARPIs and sometimes docetaxel in metastatic hormone-sensitive disease. Side effects are hot flushes, fatigue, loss of muscle and bone, weight gain, sexual dysfunction and metabolic and cardiovascular risk, hence interest in intermittent schedules and in whether metastasis-directed therapy can postpone it. Endocrine therapy in breast cancer is the analogous concept for oestrogen.", wikipedia: W("Androgen_deprivation_therapy"), cancers: ["prostate"], technologies: ["androgen-deprivation"], drugs: ["leuprolide", "degarelix"], related: ["castration-resistance", "arpi", "orchiectomy"], sections: ["hormonal"] }),
  t({ id: "arpi", name: "Androgen receptor pathway inhibitor (ARPI)", category: "Treatment jargon", aka: ["ARPI", "ARPIs", "ARSI", "androgen receptor signalling inhibitor", "androgen receptor pathway inhibitor", "novel hormonal agent", "NHA", "next-generation antiandrogen", "second-generation antiandrogen", "AR antagonist", "AR inhibitor", "antiandrogen", "anti-androgen", "AR-V7", "AR-targeted", "AR antagonists"], tldr: "The newer prostate cancer hormone pills (abiraterone, enzalutamide, apalutamide, darolutamide) that block the androgen receptor or the last steps of androgen production, used on top of standard testosterone suppression.", summary: "Abiraterone blocks CYP17 androgen synthesis (given with prednisone); enzalutamide, apalutamide and darolutamide are potent AR antagonists. Adding an ARPI to ADT extends survival in metastatic hormone-sensitive disease (LATITUDE, ARCHES, TITAN, ARASENS), in non-metastatic castration-resistant disease and in castration-resistant disease before or after docetaxel. Resistance arises via AR amplification, ligand-binding domain mutations, the AR-V7 splice variant and lineage plasticity to neuroendocrine disease; switching ARPIs after failure gives little benefit, so PSMA radioligands, PARP inhibitors and chemotherapy follow. Older antiandrogens (bicalutamide) are weaker first-generation drugs.", wikipedia: W("Antiandrogen"), cancers: ["prostate"], targets: ["androgen-receptor"], drugs: ["abiraterone", "enzalutamide", "bicalutamide"], trials: ["latitude"], related: ["adt", "castration-resistance"], sections: ["hormonal"] }),
  t({ id: "aromatase-inhibitor", name: "Aromatase inhibitor", category: "Treatment jargon", aka: ["aromatase inhibitors", "aromatase inhibition", "ovarian suppression", "ovarian function suppression", "OFS", "extended endocrine therapy", "adjuvant endocrine therapy", "endocrine therapy"], tldr: "Pills that stop the body making oestrogen (after the menopause, when it comes from fat and muscle rather than the ovaries), starving hormone receptor-positive breast cancer. Taken for five to ten years after surgery, they halve recurrence.", summary: "Letrozole, anastrozole and exemestane block the aromatase enzyme; in premenopausal women they only work with ovarian function suppression (GnRH agonist or oophorectomy, SOFT/TEXT). They modestly beat tamoxifen in postmenopausal adjuvant therapy (ATAC, BIG 1-98) and are the partner drug for CDK4/6 inhibitors in metastatic disease. Side effects are joint pain, bone loss (needing bisphosphonates), vaginal dryness and cardiovascular effects, and adherence over 5-10 years is a real problem. Resistance often comes through ESR1 mutations, which favour switching to a SERD.", wikipedia: W("Aromatase_inhibitor"), cancers: ["breast-hr-positive"], technologies: ["endocrine-therapy", "cdk46-inhibitor"], drugs: ["letrozole", "tamoxifen"], related: ["hormone-receptor-status", "serd", "endocrine-resistance", "salpingo-oophorectomy"], sections: ["hormonal"] }),
  t({ id: "serd", name: "Selective oestrogen receptor degrader (SERD)", category: "Treatment jargon", aka: ["SERD", "SERDs", "oral SERDs", "ER degrader", "estrogen receptor degrader", "SERM", "selective oestrogen receptor modulator", "CERAN", "PROTAC ER degrader", "oestrogen receptor degrader"], tldr: "Drugs that do not just block the oestrogen receptor but mark it for destruction, so the cancer cell loses the receptor altogether. The new oral versions work even when the receptor has mutated (ESR1) to escape older hormone pills.", summary: "Fulvestrant (2002) is an injectable SERD limited by incomplete degradation; elacestrant (2023, EMERALD) was the first oral SERD, approved for ESR1-mutant metastatic disease, followed by camizestrant (SERENA-6, switching at ctDNA-detected ESR1 mutation), imlunestrant and vepdegestrant (a PROTAC). Oral SERDs are now in adjuvant trials (CAMBRIA, lidERA) and in combinations with CDK4/6 and PI3K/AKT inhibitors. Tamoxifen is the older selective modulator (SERM) that blocks the receptor in breast but stimulates it in bone and uterus.", wikipedia: W("Selective_estrogen_receptor_degrader"), cancers: ["breast-hr-positive"], targets: ["estrogen-receptor"], technologies: ["endocrine-therapy", "protac-degrader"], drugs: ["fulvestrant", "elacestrant", "tamoxifen"], trials: ["emerald", "serena-6"], related: ["endocrine-resistance", "aromatase-inhibitor", "hormone-receptor-status"], sections: ["hormonal"] }),
  t({ id: "hypofractionation", name: "Hypofractionation (fewer, larger radiotherapy doses)", category: "Treatment jargon", aka: ["hypofractionated", "hypofractionated radiotherapy", "ultra-hypofractionated", "ultrahypofractionation", "moderate hypofractionation", "fractionation", "fractions", "fractionated", "single-fraction", "five-fraction", "conventional fractionation", "conventionally fractionated", "accelerated fractionation", "dose per fraction", "short-course radiotherapy", "short-course", "long-course"], tldr: "Giving radiotherapy in fewer, bigger daily doses (fractions) so a course takes one to three weeks instead of five to seven. Randomised trials showed equal control and side effects in breast (START, FAST-Forward) and prostate (CHHiP, PACE-B) cancer, and a single dose suffices for bone pain; adoption lags where health systems are paid per fraction.", summary: "Normal tissue tolerates radiation better when it is split into daily fractions, historically 1.8-2 Gy over 5-7 weeks. Randomised trials showed moderate hypofractionation (2.7-3 Gy, 15-20 fractions) is equivalent in breast (START, whole-breast 40 Gy/15) and prostate (CHHiP, PROFIT), and ultra-hypofractionation (5 fractions: FAST-Forward for breast 26 Gy/5, PACE-B for prostate) also holds up. Single 8 Gy fractions suffice for bone pain. SBRT takes the principle to its extreme. Short-course (5 × 5 Gy) rectal radiotherapy is part of total neoadjuvant therapy. Adoption lags in some health systems that are paid per fraction.", wikipedia: W("Hypofractionation"), cancers: ["breast-hr-positive", "prostate", "colorectal"], related: ["gray-unit", "sbrt-term", "imrt-term", "total-neoadjuvant-therapy"], sections: ["radiation"] }),
  t({ id: "gray-unit", name: "Gray unit (Gy)", category: "Treatment jargon", aka: ["cGy", "centigray", "EQD2", "BED", "biologically effective dose", "dose escalation", "dose-escalated", "radiation dose", "absorbed dose", "prescribed dose", "total dose", "60 Gy", "70 Gy", "GBq", "MBq", "becquerel"], tldr: "The unit of radiation dose absorbed by tissue: one gray is one joule per kilogram. A curative course is typically 50-70 Gy in total; a single bone-pain treatment is 8 Gy. Radiopharmaceuticals are prescribed by activity in becquerels (GBq) instead.", summary: "Because biological effect depends on both total dose and dose per fraction, different schedules are compared with the equivalent dose in 2 Gy fractions (EQD2) or biologically effective dose (BED); cervical brachytherapy aims for ≥85 Gy EQD2, early lung SBRT for BED ≥100 Gy. Dose escalation beyond 60 Gy did not help in stage III lung cancer (RTOG 0617) but did in prostate cancer. For radioligand therapy the administered activity (7.4 GBq of 177Lu-PSMA-617) is fixed, and dosimetry estimates the resulting gray to tumour and kidneys. Whole-body doses above about 4 Gy are lethal without marrow rescue, which is the basis of total body irradiation conditioning.", wikipedia: W("Gray_(unit)"), technologies: ["radioligand-therapy"], related: ["hypofractionation", "dosimetry", "brachytherapy-term", "conditioning-regimen"], sections: ["radiation", "radiopharma"] }),
  t({ id: "re-irradiation", name: "Re-irradiation", category: "Treatment jargon", aka: ["reirradiation", "re-irradiated", "repeat radiotherapy", "second course of radiotherapy", "in-field recurrence", "previously irradiated"], tldr: "Giving radiotherapy again to a region that has already been treated, once thought impossible because normal tissues remember the first dose. Modern precision techniques make it feasible in selected patients.", summary: "Recurrent head and neck cancer, glioma, rectal cancer and spinal metastases are the main settings. Cumulative dose to critical structures (spinal cord, brainstem, bowel) limits what can be given, so SBRT, IMRT, protons and brachytherapy, which spare surrounding tissue, are preferred, and the interval since the first course matters as some recovery occurs. Toxicity (necrosis, fistula, carotid blow-out in the neck) is higher than for first treatment, so re-irradiation is often combined with or replaced by surgery or systemic therapy when possible.", wikipedia: W("Radiation_therapy"), cancers: ["head-and-neck", "glioblastoma", "colorectal"], related: ["gray-unit", "sbrt-term", "brachytherapy-term", "salvage-therapy"], sections: ["radiation"] }),
  t({ id: "dose-dense-chemotherapy", name: "Dose-dense and metronomic chemotherapy", category: "Treatment jargon", aka: ["dose-dense", "dose dense", "dose-intense", "dose intensity", "interval-compressed", "metronomic", "metronomic chemotherapy", "low-dose metronomic", "dose-dense AC", "weekly paclitaxel"], tldr: "Two opposite ways of rescheduling the same drugs: dose-dense gives standard doses more often (every two weeks instead of three, supported by growth factors) to deny the tumour recovery time; metronomic gives small doses continuously to attack tumour blood vessels with little toxicity.", summary: "Dose-dense adjuvant chemotherapy improved survival in breast cancer (CALGB 9741, EBCTCG meta-analysis) and interval-compressed VDC/IE is standard in Ewing sarcoma; it needs G-CSF support. Metronomic oral chemotherapy (capecitabine, cyclophosphamide, methotrexate, vinorelbine) exploits anti-angiogenic and immune effects, is cheap and well tolerated, and is used in maintenance (CM in triple-negative breast, SYSUCC-001) and low-resource settings such as Tata Memorial's head and neck trials. Both are examples of gaining efficacy from schedule rather than new molecules.", wikipedia: W("Metronomic_therapy"), technologies: ["cytotoxic-chemotherapy", "g-csf-growth-factors"], cancers: ["tnbc", "sarcoma", "head-and-neck"], related: ["chemotherapy-regimen", "neutropenia", "maintenance-therapy"], sections: ["chemotherapy"] }),
  t({ id: "doublet-triplet", name: "Doublet, triplet and quadruplet regimens", category: "Treatment jargon", aka: ["doublet", "doublets", "triplet", "triplets", "quadruplet", "quadruplets", "quad", "two-drug", "three-drug", "four-drug", "IO-TKI doublet", "IO-IO", "IO/IO", "chemo-doublet", "dual blockade", "IO-TKI doublets"], tldr: "Shorthand for how many active drugs are combined: a doublet is two, a triplet three, a quadruplet four. More drugs usually mean more responses and more side effects, and trials test whether the extra drug earns its place.", summary: "Platinum doublets (cisplatin or carboplatin plus a partner) are the chemotherapy standard in lung, bladder and ovarian cancer. FOLFOXIRI is a chemotherapy triplet; quadruplet induction (daratumumab, bortezomib, lenalidomide, dexamethasone) is now standard in myeloma; IO-TKI doublets (pembrolizumab-axitinib) and IO-IO doublets (nivolumab-ipilimumab) compete in kidney cancer; prostate cancer moved from ADT alone to doublets and triplets (ADT + ARPI + docetaxel, PEACE-1, ARASENS). The question in each case is whether the combination beats sequential use of the same drugs, which is rarely tested directly.", wikipedia: W("Combination_therapy"), related: ["chemotherapy-regimen", "platinum-sensitivity", "backbone-add-on", "vrd"], sections: ["chemotherapy"] }),
  t({ id: "chemotherapy-regimen", name: "Regimen and cycles", category: "Treatment jargon", aka: ["regimen", "regimens", "chemotherapy regimen", "treatment regimen", "cycles", "chemotherapy cycles", "cycles of chemotherapy", "21-day cycle", "28-day cycle", "every 3 weeks", "q3w", "q2w", "q4w", "day 1", "days 1-14", "×6 cycles", "× 6", "chemotherapy cycle"], tldr: "A regimen is a named recipe of drugs, doses and timing; a cycle is one round of it, usually two to four weeks, giving normal tissues time to recover before the next. 'Six cycles of FOLFOX' means six repeats of that recipe.", summary: "Regimens are named by acronym (R-CHOP, FOLFOX, AC-T, VRd, 7+3) or trial (the KEYNOTE-522 regimen), specify each drug's dose per body surface area or weight and its schedule (day 1, days 1-14), and are given for a defined number of cycles or until progression or intolerance. Cycle length is set by marrow recovery, so dose-dense schedules need growth factor support. Modern regimens increasingly mix chemotherapy with antibodies and immunotherapy, and fixed-duration versus continuous designs are a live question in many diseases.", wikipedia: W("Chemotherapy_regimen"), related: ["doublet-triplet", "folfox-family", "r-chop", "dose-dense-chemotherapy", "dose-modification"], sections: ["chemotherapy"] }),
  t({ id: "anthracycline", name: "Anthracyclines (doxorubicin, epirubicin)", category: "Treatment jargon", aka: ["anthracyclines", "anthracycline-based", "anthracycline-free", "anthracycline-containing", "liposomal doxorubicin", "AC-T", "FEC", "anthracycline cardiotoxicity"], tldr: "A family of red chemotherapy drugs derived from a soil bacterium that damage cancer DNA. Cornerstones of breast cancer, lymphoma, leukaemia and sarcoma treatment, but they weaken the heart in a dose-dependent way, so there is a lifetime limit.", summary: "Doxorubicin, epirubicin, daunorubicin and idarubicin intercalate DNA and poison topoisomerase II. They anchor AC/EC in breast cancer, CHOP in lymphoma, 7+3 in AML and doxorubicin-ifosfamide in sarcoma. Cumulative doses above about 450 mg/m² doxorubicin cause cardiomyopathy, and even lower doses matter in children and with trastuzumab, which motivates anthracycline-free regimens (TCHP, docetaxel-cyclophosphamide), dexrazoxane, liposomal formulations and cardiac surveillance. They also cause alopecia, myelosuppression, and secondary leukaemia (topoisomerase-related, 1-2%), and as ADC payloads they are being revisited.", wikipedia: W("Anthracycline"), technologies: ["cytotoxic-chemotherapy", "cardio-oncology"], drugs: ["doxorubicin"], cancers: ["breast-hr-positive", "dlbcl", "aml", "sarcoma"], related: ["cardiotoxicity", "secondary-malignancy", "r-chop", "seven-plus-three"], sections: ["chemotherapy"] }),
  t({ id: "taxane", name: "Taxanes (paclitaxel, docetaxel, nab-paclitaxel)", category: "Treatment jargon", aka: ["taxanes", "taxane-based", "taxane-pretreated", "post-taxane", "taxane-naive", "weekly paclitaxel", "gemcitabine/nab-paclitaxel", "carboplatin/paclitaxel"], tldr: "Chemotherapy drugs originally from the yew tree that freeze the cell's internal scaffolding (microtubules) so it cannot divide. Used in breast, lung, ovarian, prostate, gastric and head and neck cancers; their main lasting side effect is nerve damage in the hands and feet.", summary: "Paclitaxel (Taxol, 1992) and docetaxel are given with platinum in ovarian and lung cancer, sequentially with anthracyclines in breast cancer, as the chemotherapy partner in KEYNOTE-522 and CLEOPATRA, and as first chemotherapy in prostate cancer (docetaxel, then cabazitaxel after progression). Nab-paclitaxel is an albumin-bound form that avoids solvent hypersensitivity and is standard with gemcitabine in pancreatic cancer. Peripheral neuropathy, alopecia, neutropenia and hypersensitivity reactions are the main toxicities; taxane-derived payloads are less common in ADCs than tubulin inhibitors such as MMAE, which act on the same target.", wikipedia: W("Taxane"), technologies: ["cytotoxic-chemotherapy"], drugs: ["paclitaxel", "docetaxel"], related: ["peripheral-neuropathy", "tubulin-inhibitor-payloads", "doublet-triplet"], sections: ["chemotherapy"] }),
  t({ id: "alkylating-agent", name: "Alkylating agents and antimetabolites", category: "Treatment jargon", aka: ["alkylating", "alkylator", "alkylators", "alkylating agent", "alkylating agents", "alkylating chemotherapy", "antimetabolite", "antimetabolites", "fluoropyrimidine", "fluoropyrimidines", "nucleoside analogue", "purine analogue", "vinca alkaloid", "vinca alkaloids", "vinca", "5-FU", "purine analogues"], tldr: "The two oldest chemotherapy families: alkylators (cyclophosphamide, temozolomide, melphalan) glue DNA strands together so cells cannot copy them; antimetabolites (5-FU, capecitabine, methotrexate, gemcitabine) are fake building blocks that jam DNA synthesis.", summary: "Alkylating agents descend from mustard gas (nitrogen mustard, 1946): cyclophosphamide anchors lymphoma and breast regimens and lymphodepletion, temozolomide treats glioblastoma, melphalan and busulfan are transplant conditioning, and platinum drugs act similarly. Antimetabolites include fluoropyrimidines (5-FU, capecitabine, S-1) in gastrointestinal and breast cancer, methotrexate and cytarabine in leukaemia, gemcitabine in pancreatic and bladder cancer and pemetrexed in non-squamous lung cancer. Alkylators are mutagenic and cause secondary leukaemia and infertility; antimetabolite toxicity depends on enzymes such as DPD (5-FU) and can be reduced by pre-treatment genotyping.", wikipedia: W("Alkylating_antineoplastic_agent"), technologies: ["cytotoxic-chemotherapy"], drugs: ["cyclophosphamide", "fluorouracil", "methotrexate", "gemcitabine", "temozolomide", "melphalan"], related: ["secondary-malignancy", "conditioning-regimen", "lymphodepletion", "folfox-family"], sections: ["chemotherapy"] }),
  t({ id: "folfox-family", name: "FOLFOX, FOLFIRI, FOLFIRINOX and CAPOX", category: "Treatment jargon", aka: ["FOLFOX", "mFOLFOX6", "FOLFIRI", "FOLFOXIRI", "FOLFIRINOX", "mFOLFIRINOX", "modified FOLFIRINOX", "CAPOX", "XELOX", "CAPEOX", "NALIRIFOX", "FOLFOX/CAPOX", "fluoropyrimidine-based"], tldr: "The standard chemotherapy recipes for bowel and pancreatic cancer, named from their ingredients: FOL (folinic acid) + F (5-fluorouracil) + OX (oxaliplatin), IRI (irinotecan), or both (FOLFIRINOX). CAPOX swaps the 5-FU infusion for capecitabine tablets.", summary: "FOLFOX or CAPOX for 3-6 months is adjuvant therapy for stage III colon cancer (IDEA showed 3 months suffices for low-risk disease); FOLFOX or FOLFIRI with an antibody (bevacizumab, or cetuximab/panitumumab for left-sided RAS wild-type) is first-line metastatic treatment, with FOLFOXIRI for fit patients needing maximal response. FOLFIRINOX (2011) and NALIRIFOX are the most active pancreatic regimens for fit patients, and FOLFOX is part of total neoadjuvant therapy for rectal cancer and of gastric and biliary regimens. Oxaliplatin causes cumulative cold-triggered neuropathy, irinotecan causes diarrhoea and neutropenia (UGT1A1-dependent).", wikipedia: W("FOLFOX"), cancers: ["colorectal", "pancreatic", "gastric"], drugs: ["oxaliplatin", "irinotecan", "fluorouracil"], related: ["alkylating-agent", "peripheral-neuropathy", "total-neoadjuvant-therapy", "chemotherapy-regimen"], sections: ["chemotherapy"] }),
  t({ id: "flot-term", name: "FLOT regimen (perioperative chemotherapy for gastric cancer)", category: "Treatment jargon", aka: ["FLOT4", "FLOT regimen", "perioperative FLOT", "docetaxel quadruplet", "ECF", "ECX", "MAGIC regimen"], tldr: "Four cycles of chemotherapy before and four after surgery for stomach and junction cancer, using fluorouracil, leucovorin, oxaliplatin and docetaxel. It replaced the older ECF recipe after the FLOT4 trial and is now the Western standard.", summary: "The MAGIC trial (2006) established perioperative ECF; FLOT4 (2019) showed FLOT improved median survival from 35 to 50 months and raised complete pathological responses. Adding PD-1 blockade (MATTERHORN durvalumab, KEYNOTE-585) improved event-free survival, and trastuzumab and zolbetuximab are being tested in HER2-positive and claudin 18.2-positive disease. FLOT is toxic (neutropenia, neuropathy, diarrhoea) and only about half of patients complete the postoperative half, so ctDNA-guided and response-adapted variants are under study. East Asian practice favours D2 surgery followed by adjuvant S-1 or CAPOX instead.", wikipedia: W("Gastric_cancer#Treatment"), cancers: ["gastric", "esophageal"], drugs: ["oxaliplatin", "docetaxel", "fluorouracil"], related: ["flot", "gastrectomy", "neoadjuvant-adjuvant", "gej", "folfox-family"], sections: ["chemotherapy"] }),
  t({ id: "r-chop", name: "R-CHOP (lymphoma chemoimmunotherapy)", category: "Treatment jargon", aka: ["R-CHOP", "R-CHOP21", "CHOP-R", "Pola-R-CHP", "polatuzumab-R-CHP", "R-CHOEP", "DA-EPOCH-R", "R-CVP", "bendamustine-rituximab", "chemoimmunotherapy", "chemo-immunotherapy regimen", "R-ICE", "R-DHAP", "R-GDP"], tldr: "R-CHOP is the standard first treatment for diffuse large B-cell lymphoma: rituximab (an antibody against CD20) plus four chemotherapy drugs (cyclophosphamide, doxorubicin, vincristine, prednisone), given every three weeks for six cycles with curative intent. Patients who relapse within a year now go to CAR-T rather than more chemotherapy.", summary: "CHOP dates from the 1970s; adding rituximab (2002) raised cure rates by about 15 percentage points. Pola-R-CHP swaps vincristine for polatuzumab vedotin and improved progression-free survival (POLARIX); PET-guided shortening to four cycles suffices for low-risk early-stage disease (FLYER). Patients who relapse within a year now go to CAR-T rather than salvage chemotherapy and autologous transplant; bispecific antibodies (glofitamab, epcoritamab) are moving into first line combinations. BR (bendamustine-rituximab) and R-CVP are gentler regimens for indolent lymphomas. 'Chemoimmunotherapy' in lymphoma means antibody plus chemotherapy, not checkpoint inhibitors.", wikipedia: W("R-CHOP"), cancers: ["dlbcl", "cll"], drugs: ["rituximab", "cyclophosphamide", "doxorubicin", "vincristine", "bendamustine"], related: ["anthracycline", "deauville", "salvage-therapy", "chemotherapy-regimen"], sections: ["chemotherapy", "immunotherapy"] }),
  t({ id: "abvd-beacopp", name: "ABVD, BEACOPP and BrECADD (Hodgkin lymphoma regimens)", category: "Treatment jargon", aka: ["ABVD", "A+AVD", "AVD", "BV-AVD", "brentuximab vedotin-AVD", "BEACOPP", "escalated BEACOPP", "eBEACOPP", "BrECADD", "N-AVD", "nivolumab-AVD", "Stanford V"], tldr: "The chemotherapy recipes that cure most Hodgkin lymphoma: ABVD (four drugs, the long-standing standard), the more intensive German BEACOPP, and newer versions that replace bleomycin with brentuximab vedotin (A+AVD) or add nivolumab (N-AVD).", summary: "ABVD (doxorubicin, bleomycin, vinblastine, dacarbazine) cures 70-80% of advanced disease with interim PET guiding bleomycin omission (RATHL); escalated BEACOPP raises progression-free survival to about 90% at the cost of infertility and secondary cancers. A+AVD improved survival over ABVD (ECHELON-1), N-AVD beat A+AVD on progression-free survival in SWOG S1826 (2024), and BrECADD matched escalated BEACOPP with less toxicity (HD21). Late effects of these curative regimens (cardiac, pulmonary, breast cancer after radiotherapy) drive the continuing effort to de-escalate.", wikipedia: W("ABVD"), cancers: ["hodgkin-lymphoma"], drugs: ["brentuximab-vedotin", "nivolumab", "doxorubicin", "vinblastine", "bleomycin"], related: ["deauville", "late-effects", "secondary-malignancy", "de-escalation"], sections: ["chemotherapy"] }),
  t({ id: "seven-plus-three", name: "7+3 induction chemotherapy", category: "Treatment jargon", aka: ["7+3", "7 + 3", "cytarabine-anthracycline", "cytarabine plus daunorubicin", "intensive chemotherapy", "intensive induction", "non-intensive", "non-intensive therapy", "less intensive", "CPX-351", "Vyxeos", "HiDAC", "high-dose cytarabine", "FLAG-IDA"], tldr: "The classic first treatment for acute myeloid leukaemia, unchanged since 1973: seven days of continuous cytarabine plus three days of an anthracycline, given in hospital. Fit patients still get it, now with a targeted drug added according to their leukaemia's genetics.", summary: "7+3 achieves complete remission in 60-80% of younger adults and is followed by consolidation (high-dose cytarabine) or allogeneic transplant depending on ELN risk. Additions by genotype: midostaurin or quizartinib for FLT3 mutations, gemtuzumab ozogamicin for favourable-risk CD33-positive disease, CPX-351 (liposomal 7+3) for secondary AML. Patients unfit for intensive chemotherapy receive venetoclax plus azacitidine, which is eroding the boundary between 'intensive' and 'non-intensive' approaches. Induction mortality is 5-10% and the main risks are infection and bleeding during weeks of aplasia.", wikipedia: W("Acute_myeloid_leukemia#Treatment"), cancers: ["aml"], drugs: ["venetoclax", "azacitidine", "midostaurin", "gilteritinib"], related: ["induction-therapy", "anthracycline", "hma", "allogeneic-transplant"], sections: ["chemotherapy"] }),
  t({ id: "vrd", name: "VRd and Dara-VRd (myeloma induction regimens)", category: "Treatment jargon", aka: ["VRd", "RVd", "Dara-VRd", "D-VRd", "Isa-VRd", "Dara-Rd", "DRd", "KRd", "Dara-KRd", "VMP", "Dara-VMP", "VCd", "bortezomib-based", "lenalidomide-based", "CD38 antibody + PI + IMiD", "PI + IMiD + dexamethasone"], tldr: "The alphabet soup of myeloma treatment: V (bortezomib, Velcade), R (lenalidomide, Revlimid), d (dexamethasone), Dara (daratumumab), Isa (isatuximab), K (carfilzomib). Dara-VRd, a four-drug quadruplet, is now the standard first treatment for most patients.", summary: "VRd was the standard triplet for a decade (SWOG S0777). Adding a CD38 antibody made quadruplets standard: Dara-VRd before and after autologous transplant (PERSEUS) and in transplant-ineligible patients (CEPHEUS), Isa-VRd in IMROZ, with Dara-Rd (MAIA) for frailer patients. Bortezomib causes neuropathy and is often dropped after induction; lenalidomide continues as maintenance. MRD negativity rates above 60% with quadruplets are prompting trials of MRD-guided de-escalation and of CAR-T or bispecifics in place of transplant (CARTITUDE-5/6).", wikipedia: W("Multiple_myeloma#Treatment"), cancers: ["multiple-myeloma"], drugs: ["bortezomib", "lenalidomide", "daratumumab"], trials: ["cartitude-4"], related: ["proteasome-inhibitor", "imid", "autologous-transplant", "umrd", "doublet-triplet"], sections: ["chemotherapy", "targeted-therapy"] }),
  t({ id: "proteasome-inhibitor", name: "Proteasome inhibitor (bortezomib, carfilzomib, ixazomib)", category: "Treatment jargon", aka: ["proteasome inhibitors", "proteasome inhibition", "PI-based"], tldr: "Drugs that block the cell's protein-recycling machine. Myeloma cells make huge amounts of antibody protein and choke on the backlog when the proteasome is blocked; normal cells cope far better.", summary: "Bortezomib (2003) was the first, given subcutaneously to limit neuropathy; carfilzomib is irreversible and more potent but has cardiovascular toxicity; ixazomib is oral. They pair with immunomodulatory drugs and dexamethasone in VRd/KRd induction, in relapsed combinations with daratumumab or isatuximab, and bortezomib is also used in mantle cell lymphoma and AL amyloidosis. Resistance and the shift to CD38 antibodies, CAR-T and bispecifics have reduced their role at relapse, but they remain in nearly every first-line regimen.", wikipedia: W("Proteasome_inhibitor"), cancers: ["multiple-myeloma"], drugs: ["bortezomib", "ixazomib"], related: ["vrd", "imid", "peripheral-neuropathy"], sections: ["targeted-therapy"] }),
  t({ id: "imid", name: "Immunomodulatory drugs (IMiDs) and CELMoDs", category: "Treatment jargon", aka: ["IMiD", "IMiDs", "immunomodulatory drugs", "immunomodulatory agents", "immunomodulatory imide drugs", "CELMoD", "CELMoDs", "cereblon modulators", "cereblon E3 ligase modulators", "IKZF1/3 degradation", "cereblon modulator", "immunomodulatory drug"], tldr: "Thalidomide and its descendants lenalidomide and pomalidomide, which hijack a cellular waste-disposal tag (cereblon) to destroy two proteins myeloma cells depend on, while also revving up T and NK cells. CELMoDs such as iberdomide and mezigdomide bind cereblon more tightly and work after lenalidomide fails; clots, low blood counts and birth defects are class risks.", summary: "Thalidomide's return from the 1960s disaster as a myeloma drug (1999) and the discovery that it acts as a molecular glue degrader of IKZF1/3 via cereblon founded the whole field of targeted protein degradation. Lenalidomide is in nearly every myeloma induction and maintenance regimen and treats del(5q) MDS and some lymphomas; pomalidomide follows lenalidomide failure. CELMoDs (iberdomide, mezigdomide) bind cereblon more tightly and are active in lenalidomide-refractory disease (EXCALIBER). Class effects are cytopenias, thrombosis (prophylaxis required), rash, and secondary cancers; teratogenicity mandates pregnancy-prevention programmes.", wikipedia: W("Immunomodulatory_imide_drug"), cancers: ["multiple-myeloma"], drugs: ["lenalidomide", "pomalidomide", "thalidomide"], technologies: ["molecular-glue-platforms", "protac-degrader"], related: ["vrd", "proteasome-inhibitor", "vte", "mds"], sections: ["targeted-therapy"] }),
  t({ id: "hma", name: "Hypomethylating agents (azacitidine, decitabine)", category: "Treatment jargon", aka: ["HMA", "HMAs", "hypomethylating", "hypomethylating agent", "hypomethylating agents", "oral azacitidine", "oral decitabine-cedazuridine", "venetoclax-azacitidine", "venetoclax + azacitidine", "ven-aza", "Ven/Aza", "HMA-venetoclax", "venetoclax + HMA", "HMA failure"], tldr: "Low-intensity chemotherapy that strips chemical 'off' switches (methyl groups) from DNA so silenced genes can be read again. The mainstay for older patients with AML and high-risk MDS, especially combined with venetoclax.", summary: "Azacitidine and decitabine (approved 2004-06) extend survival in higher-risk MDS and were the only option for AML patients unfit for intensive chemotherapy until venetoclax-azacitidine (VIALE-A, 2020) roughly doubled responses and became the standard, now available fully orally. They are given in outpatient cycles for as long as they work; 'HMA failure' defines a population with very poor outcomes where menin inhibitors, IDH inhibitors and trials of new agents are focused. Response can take several cycles, so early stopping is a common error.", wikipedia: W("Azacitidine"), cancers: ["aml"], drugs: ["azacitidine", "venetoclax"], technologies: ["epigenetic-drugs"], related: ["mds", "seven-plus-three", "performance-status"], sections: ["epigenetics", "chemotherapy"] }),
  t({ id: "tki-term", name: "Tyrosine kinase inhibitor (TKI)", category: "Treatment jargon", aka: ["TKI", "TKIs", "tyrosine kinase inhibitors", "kinase inhibitor", "multikinase inhibitor", "multi-kinase inhibitor", "multi-targeted TKI", "EGFR-TKI", "ALK TKI", "BTK inhibitor", "BTK inhibitors", "BTK inhibition", "targeted pill", "-nib", "TKI-pretreated", "TKI-naive", "first-generation", "second-generation", "third-generation", "next-generation TKI", "kinase inhibitors", "multikinase inhibitors", "next-generation TKIs", "targeted pills"], tldr: "Pills that block the on-switch enzyme (a kinase) that a particular cancer depends on: imatinib for CML, osimertinib for EGFR lung cancer, ibrutinib for CLL. Usually taken daily at home and continued as long as they work.", summary: "Small molecules that occupy the ATP pocket (or an allosteric site) of a kinase; selectivity ranges from single-target (osimertinib, asciminib) to multikinase (sorafenib, lenvatinib, cabozantinib, which also hit VEGF receptors). Generations improve potency, brain penetration and coverage of resistance mutations. They produce rapid responses in oncogene-addicted cancers, and resistance emerges through on-target mutations or bypass pathways. Class toxicities depend on off-target kinases: rash and diarrhoea (EGFR), hypertension and hand-foot reaction (VEGFR), QT prolongation, and pneumonitis. Not every kinase inhibitor is 'tyrosine' (CDK4/6 and MEK are serine/threonine kinases) but the shorthand is used broadly.", wikipedia: W("Tyrosine_kinase_inhibitor"), technologies: ["kinase-inhibitors"], drugs: ["imatinib", "osimertinib", "ibrutinib", "zanubrutinib", "lenvatinib", "cabozantinib"], related: ["gatekeeper-mutation", "driver-mutation", "oncogene-addiction", "rash-skin-toxicity"], sections: ["targeted-therapy"] }),
  t({ id: "immuno-oncology", name: "Immuno-oncology (IO) and checkpoint blockade", category: "Treatment jargon", aka: ["I-O", "immuno-oncology", "checkpoint blockade", "immune checkpoint blockade", "ICB", "ICI", "ICIs", "PD-1 blockade", "PD-(L)1", "PD-(L)1 blockade", "PD-1/PD-L1", "anti-PD-1", "anti-PD-L1", "anti-CTLA-4", "anti-PD(L)1", "chemo-IO", "chemo-immunotherapy", "chemoimmunotherapy", "IO-based", "IO-naive", "post-IO", "IO-refractory", "immunotherapy-refractory", "immunotherapy-resistant", "dual checkpoint blockade", "dual immune checkpoint blockade", "IO combination", "IO + chemo"], tldr: "Treatments that take the brakes off the patient's own immune system so it attacks the cancer, chiefly antibodies against PD-1, PD-L1 and CTLA-4. 'IO' is industry shorthand; 'chemo-IO' means chemotherapy plus a checkpoint inhibitor, the commonest first-line combination.", summary: "Since ipilimumab (2011) and pembrolizumab/nivolumab (2014), checkpoint inhibitors have become standard in melanoma, lung, kidney, bladder, head and neck, liver, gastric, oesophageal, cervical, endometrial, triple-negative breast and MSI-high cancers, and in curative settings before and after surgery. Benefit tracks PD-L1 expression, tumour mutational burden and MSI status but imperfectly; 'cold' tumours (pancreatic, prostate, MSS colorectal, most glioblastoma) remain resistant, and roughly 40% of responders eventually progress. Immune-related adverse events affect any organ. Next steps include LAG-3, TIGIT (mixed), PD-1×VEGF bispecifics (ivonescimab), and combining IO with ADCs.", wikipedia: W("Immune_checkpoint_inhibitor"), technologies: ["checkpoint-inhibitor", "bispecific-antibody"], drugs: ["pembrolizumab", "nivolumab", "ipilimumab", "durvalumab", "atezolizumab"], related: ["irae", "pd-l1-testing", "cold-vs-hot", "tmb", "msi", "mss-pmmr"], sections: ["immunotherapy"] }),
  t({ id: "backbone-add-on", name: "Backbone, add-on and monotherapy", category: "Treatment jargon", aka: ["backbone", "chemotherapy backbone", "backbone therapy", "add-on", "add-on therapy", "monotherapy", "single agent", "single-agent", "single-agent activity", "combination partner", "chemotherapy backbones", "single agents"], tldr: "Trial-design vocabulary: the backbone is the established treatment everyone in the trial receives; the add-on is the new drug tested on top of it; monotherapy means the drug alone. Most modern approvals are add-ons to a backbone.", summary: "Testing a new drug added to standard therapy (backbone) versus the backbone alone is the fastest route to approval because it needs no head-to-head against the standard, but it means patients receive more drugs and more toxicity, and it can obscure whether the new agent could replace rather than supplement (the 'chemotherapy-free' question in CLL, lung cancer and myeloma). Single-agent activity in early trials (objective response rate as monotherapy) is the usual evidence that a drug contributes. Regulators sometimes require 'contribution of components' studies when a combination is approved without it.", wikipedia: W("Combination_therapy"), related: ["doublet-triplet", "control-arm", "orr", "de-escalation"], sections: ["chemotherapy"] }),
  t({ id: "cross-resistance", name: "Cross-resistance", category: "Treatment jargon", aka: ["cross-resistant", "cross resistance", "payload cross-resistance", "cross-reactive resistance", "collateral sensitivity", "optimal sequencing"], tldr: "When a cancer that has become resistant to one drug is also resistant to another it has never seen, because the two share a mechanism. It is the central worry in deciding the order (sequencing) of similar drugs.", summary: "Two ADCs carrying topoisomerase-I payloads (T-DXd, sacituzumab govitecan, datopotamab deruxtecan) may fail one after another because resistance is to the payload, not the antibody; ARPIs show near-complete cross-resistance in prostate cancer; second-generation ALK or BTK inhibitors overcome some but not all resistance to the first. Cross-resistance data usually come from retrospective series, which is why 'optimal sequencing' remains unresolved in HR-positive breast, HER2-positive breast, prostate and CLL, and why some trials test switching mechanisms (payload class, target) rather than drugs of the same class. The opposite, collateral sensitivity, is when resistance to one drug creates vulnerability to another.", wikipedia: W("Cross-resistance"), technologies: ["adc"], related: ["adc-sequencing", "resistance", "rechallenge", "first-line"], sections: ["adcs", "targeted-therapy"] }),
  t({ id: "rechallenge", name: "Rechallenge and retreatment", category: "Treatment jargon", aka: ["re-challenge", "rechallenged", "retreatment", "re-treatment", "re-treated", "platinum rechallenge", "anti-EGFR rechallenge", "immunotherapy rechallenge", "re-exposure", "re-induction", "drug holiday", "treatment holiday", "treatment break", "intermittent therapy", "intermittent dosing", "stop-and-restart", "stop and go", "drug holidays"], tldr: "Giving a drug again after a break, on the theory that the cancer's resistance faded while it was off the drug. Sometimes it works: bowel cancers can respond again to EGFR antibodies once resistant clones have receded.", summary: "Anti-EGFR rechallenge in RAS wild-type colorectal cancer works when ctDNA shows RAS-mutant clones have declined (CHRONOS, CRICKET). Platinum rechallenge is standard for platinum-sensitive relapse in ovarian and small-cell lung cancer; BTK inhibitor or venetoclax retreatment after fixed-duration CLL therapy is effective; checkpoint inhibitor rechallenge after stopping for toxicity or after a treatment-free interval gives responses in a minority. Planned drug holidays (intermittent ADT, stop-and-go FOLFOX in OPTIMOX, adaptive therapy in prostate cancer) trade some disease control for toxicity relief and may slow resistance by preserving sensitive cells.", wikipedia: W("Drug_holiday"), related: ["platinum-sensitivity", "fixed-duration", "clonal-evolution", "cross-resistance"], sections: ["chemotherapy"] }),
  t({ id: "fixed-duration", name: "Fixed-duration vs continuous therapy", category: "Treatment jargon", aka: ["fixed-duration", "fixed duration", "time-limited", "time-limited therapy", "finite therapy", "continuous therapy", "continuous treatment", "indefinite treatment", "treatment-free", "treatment-free interval", "treatment-free survival", "off-treatment", "treatment discontinuation", "stopping rules", "stop trial", "treatment cessation", "elective discontinuation", "stopping rule"], tldr: "Whether a drug is taken for a set period (say 12 months) and then stopped even though it is still working, or continued indefinitely until it fails. Fixed-duration gives patients years off treatment; continuous therapy avoids the risk of the cancer regrowing.", summary: "The debate is sharpest in CLL, where venetoclax-based regimens for 12-15 months (CLL14, GLOW) compete with indefinite BTK inhibitors, and MRD status at the end of therapy predicts who stays in remission. In CML, treatment-free remission after deep response is established; in myeloma, lenalidomide maintenance is continuous but MRD-guided stopping trials are under way; in metastatic melanoma and lung cancer, immunotherapy is often stopped at two years with durable benefit (KEYNOTE-006, CheckMate 153). Fixed-duration reduces cumulative toxicity and cost and permits retreatment; continuous therapy is simpler to prove in trials because progression-free survival keeps counting.", wikipedia: W("Chronic_lymphocytic_leukemia#Treatment"), cancers: ["cll", "multiple-myeloma", "melanoma"], drugs: ["venetoclax", "ibrutinib"], related: ["umrd", "molecular-response", "maintenance-therapy", "rechallenge"], sections: ["targeted-therapy"] }),
  t({ id: "step-up-dosing", name: "Step-up dosing (T-cell engagers)", category: "Treatment jargon", aka: ["step-up", "step-up dose", "step-up doses", "priming dose", "ramp-up", "ramp-up dosing", "venetoclax ramp-up", "dose ramp", "inpatient monitoring", "outpatient administration", "outpatient step-up"], tldr: "Starting a bispecific T-cell engager (teclistamab, glofitamab, epcoritamab, tarlatamab) at a tiny dose and increasing it over the first week, so T cells are switched on gradually and the fever-and-low-blood-pressure reaction (cytokine release syndrome) stays mild. The hospital stay it needs has slowed community adoption.", summary: "Bispecific T-cell engagers (teclistamab, glofitamab, epcoritamab, tarlatamab) are given in step-up doses over the first week, often with steroid or tocilizumab premedication and inpatient monitoring, after which CRS risk falls sharply and dosing can continue in clinic. The requirement for hospital beds during step-up has slowed community adoption and motivates subcutaneous formulations, prophylactic tocilizumab and outpatient protocols. Venetoclax uses a similar five-week ramp-up in CLL to prevent tumour lysis syndrome.", wikipedia: W("Bispecific_T-cell_engager"), technologies: ["t-cell-engager", "bispecific-antibody"], drugs: ["teclistamab", "glofitamab", "epcoritamab", "tarlatamab", "venetoclax"], related: ["crs", "icans", "community-oncology-networks"], sections: ["immunotherapy"] }),
  t({ id: "de-escalation", links: [{ label: "ClinicalTrials.gov NCT03036488: KEYNOTE-522", url: "https://clinicaltrials.gov/study/NCT03036488" }, { label: "ClinicalTrials.gov NCT02743494: CheckMate 577", url: "https://clinicaltrials.gov/study/NCT02743494" }], name: "De-escalation, escalation and response-adapted therapy", category: "Treatment jargon", aka: ["de-escalation", "de-escalate", "de-escalated", "de-escalating", "de-intensification", "de-intensify", "treatment de-escalation", "treatment intensification", "intensification", "response-adapted", "response-guided", "risk-adapted", "risk-adapted therapy", "biomarker-guided", "ctDNA-guided", "MRD-guided", "PET-adapted", "omission of chemotherapy", "chemotherapy omission", "chemotherapy-free", "chemo-free", "less is more", "treatment omission"], tldr: "Giving less treatment to patients who are doing well and more to those who are not, using a marker such as scan response, ctDNA or MRD to decide. The aim is to cure the same number of people with less harm.", summary: "Examples: omitting chemotherapy in low-risk HR-positive breast cancer by genomic assays (TAILORx, MINDACT) or in HER2-positive disease by PET response (PHERGain); shortening adjuvant FOLFOX to 3 months (IDEA); ctDNA-guided omission or escalation of adjuvant chemotherapy in colon cancer (DYNAMIC, CIRCULATE); PET-guided omission of radiotherapy or bleomycin in lymphoma; 12 versus 6 months of trastuzumab (PERSEPHONE); radiotherapy dose reduction in HPV-positive oropharynx cancer (which has repeatedly failed); and MRD-guided stopping in CLL and myeloma. De-escalation trials need non-inferiority designs and large numbers, and are rarely funded by industry. Escalation trials add drugs to non-responders (KEYNOTE-522 residual disease, CheckMate 577).", trials: ["dynamic", "circulate-japan", "keynote-522", "checkmate-577"], related: ["non-inferiority", "deauville", "umrd", "ctdna", "organ-preservation"], sections: ["chemotherapy"] }),
  t({ id: "organ-preservation", wikipedia: W("Watchful_waiting"), links: [{ label: "Garcia-Aguilar et al., OPRA: organ preservation in rectal adenocarcinoma treated with total neoadjuvant therapy (Journal of Clinical Oncology 2022)", url: "https://doi.org/10.1200/JCO.22.00032" }], name: "Organ preservation (watch-and-wait, bladder-sparing, larynx preservation)", category: "Treatment jargon", aka: ["organ-preservation", "organ preservation", "organ-sparing", "organ sparing", "bladder-sparing", "bladder preservation", "bladder-preserving", "larynx preservation", "larynx-preserving", "sphincter preservation", "sphincter-sparing", "watch-and-wait", "watch and wait", "non-operative management", "nonoperative management", "NOM", "rectum preservation", "limb preservation", "breast preservation", "fertility-sparing", "nerve-sparing"], tldr: "Curing a cancer with drugs and radiotherapy so that the organ (rectum, bladder, larynx, limb) does not have to be removed, keeping surgery in reserve for the minority whose cancer regrows.", summary: "Definitive chemoradiation preserves the larynx (VA Larynx trial) and the anus (Nigro); trimodality therapy preserves the bladder in selected muscle-invasive cancer and complete responders to enfortumab vedotin plus pembrolizumab are being spared cystectomy in trials; total neoadjuvant therapy with watch-and-wait for clinical complete responders preserves the rectum in about half of patients (OPRA), and dostarlimab alone cured dMMR rectal cancers without surgery or radiation. Requirements are reliable response assessment (MRI, endoscopy, ctDNA), intensive surveillance and the capacity for timely salvage surgery when regrowth occurs. Patients often accept some extra recurrence risk to keep their organ.", cancers: ["colorectal", "urothelial", "head-and-neck"], related: ["total-neoadjuvant-therapy", "chemoradiation", "salvage-therapy", "stoma", "de-escalation"], sections: ["radiation", "surgery"] }),
  t({ id: "active-surveillance-term", name: "Active surveillance and observation", category: "Treatment jargon", aka: ["active surveillance", "watchful waiting", "expectant management", "surveillance MRI", "imaging surveillance", "surveillance imaging", "wait-and-see", "surveillance strategy", "post-treatment surveillance", "follow-up imaging"], tldr: "Deliberately not treating a cancer yet, but checking it regularly with blood tests, scans or biopsies and treating only if it shows signs of progressing. Standard for low-risk prostate cancer, small kidney masses and several other slow conditions.", summary: "Active surveillance avoids or defers the harms of treatment for cancers unlikely to cause trouble: Grade Group 1 prostate cancer (ProtecT showed no survival penalty at 15 years), small renal masses, papillary thyroid microcarcinoma, low-risk DCIS (COMET), smouldering myeloma and early-stage CLL, and stage I testicular cancer after orchiectomy. It differs from watchful waiting, which forgoes curative intent. 'Surveillance' also describes the scheduled follow-up after curative treatment (CT, ctDNA, MRI in small-cell lung cancer instead of prophylactic cranial irradiation), and after complete response in organ-preservation strategies (SANO in oesophageal cancer).", wikipedia: W("Active_surveillance_of_prostate_cancer"), cancers: ["prostate", "rcc", "thyroid", "cll"], trials: ["protect", "sano"], related: ["active-surveillance", "gleason-grade-group", "dcis", "smoldering-myeloma", "organ-preservation"], sections: ["diagnostics"] }),
  t({ id: "curative-intent", name: "Curative intent vs palliative intent", category: "Treatment jargon", aka: ["curative intent", "curative-intent", "curative", "curable", "potentially curable", "cure rate", "with curative intent", "palliative intent", "palliative", "palliation", "palliative chemotherapy", "palliative treatment", "non-curative", "life-prolonging", "best supportive care", "BSC", "supportive care alone", "symptom control", "cure rates"], tldr: "Whether the goal of treatment is to eliminate the cancer for good (curative) or to control it, relieve symptoms and extend life when cure is not possible (palliative). The intent, not the drug, defines the word: the same chemotherapy can be either.", summary: "Curative-intent treatment usually combines surgery or radiotherapy with systemic therapy for localised or locally advanced disease and accepts more toxicity for a chance of cure; palliative-intent treatment for metastatic disease balances life extension against quality of life, and includes palliative radiotherapy for pain or bleeding and palliative surgery for obstruction. Best supportive care means symptom management without anticancer treatment and is the comparator in some trials. A growing minority of metastatic settings (oligometastatic disease, germ cell tumours, some lymphomas, MSI-high colorectal cancer on immunotherapy) blur the line, and early palliative care alongside curative or life-prolonging treatment improves outcomes.", wikipedia: W("Palliative_care"), technologies: ["palliative-care", "palliative-radiotherapy"], related: ["oligometastatic", "hospice-end-of-life", "locally-advanced", "resectability"], sections: ["supportive-care"] }),
  t({ id: "locally-advanced", name: "Locally advanced and locoregional disease", category: "Treatment jargon", aka: ["locally advanced", "locally-advanced", "locoregional", "loco-regional", "locoregionally advanced", "locoregional disease", "locoregional control", "locoregional recurrence", "local recurrence", "local control", "regional recurrence", "distant recurrence", "distant metastasis", "distant metastases", "distant relapse", "local therapy", "local treatment", "locoregional therapy", "local-regional"], tldr: "Cancer that has grown beyond its organ into nearby tissue or lymph nodes but has not spread to distant sites. It is treated with the goal of cure but usually needs several treatments (surgery, radiotherapy, drugs) together.", summary: "Locally advanced disease (typically stage III) is where multimodality treatment matters most: chemoradiation for stage III lung, oesophageal and cervical cancer, neoadjuvant therapy before surgery for rectal, gastric and pancreatic cancer, and induction or concurrent chemotherapy in head and neck cancer. 'Locoregional' pairs the primary site and its regional nodes; locoregional recurrence after treatment can often still be salvaged, whereas distant recurrence generally cannot. Local control is a radiotherapy and surgery outcome measured separately from survival. Borderline resectable and unresectable are the surgeon's subdivisions of the same stage.", wikipedia: W("Cancer_staging"), related: ["chemoradiation", "resectability", "neoadjuvant-adjuvant", "tnm-staging", "curative-intent"], sections: ["radiation", "surgery"] }),
  t({ id: "resectability", name: "Resectable, borderline resectable and unresectable", category: "Treatment jargon", aka: ["resectable", "resectability", "unresectable", "non-resectable", "inoperable", "operable", "borderline resectable", "borderline-resectable", "potentially resectable", "initially unresectable", "upfront surgery", "upfront resection", "conversion to resectability", "conversion surgery", "downstaged"], tldr: "The surgeon's verdict on whether the tumour can be completely removed. Resectable means yes; unresectable means it has wrapped around vital vessels, is too extensive or the patient is too frail; borderline means maybe, especially after chemotherapy shrinks it.", summary: "Resectability is judged on imaging by involvement of arteries and veins (pancreatic cancer's borderline definitions concern the superior mesenteric vessels), extent of nodal disease (N2-3 in lung cancer) and liver remnant volume, and is not the same as stage: some stage IV colorectal liver metastases are resectable and some stage II pancreatic tumours are not. Unresectable does not mean incurable: stage III lung cancer is cured by chemoradiation plus durvalumab in a third of patients, and 'conversion therapy' (FOLFOXIRI-bevacizumab in liver metastases, RAS inhibitors in pancreatic cancer) turns some unresectable cancers into resectable ones. Multidisciplinary review is required because surgeons differ in what they will attempt.", wikipedia: W("Segmental_resection"), cancers: ["pancreatic", "nsclc", "colorectal", "hcc"], related: ["locally-advanced", "resection-margins", "downstaging", "multidisciplinary-tumour-board", "whipple"], sections: ["surgery"] }),
  t({ id: "limited-extensive-stage", name: "Limited-stage vs extensive-stage (small-cell lung cancer)", category: "Treatment jargon", aka: ["limited-stage", "limited stage", "LS-SCLC", "extensive-stage", "extensive stage", "ES-SCLC", "very limited stage", "thoracic radiotherapy", "consolidative thoracic radiotherapy", "limited-vs-extensive-stage"], tldr: "Small-cell lung cancer uses a two-way split instead of the usual four stages: limited (confined to one side of the chest and treatable within one radiation field, about a third of patients) or extensive (everything else).", summary: "Limited-stage disease receives concurrent platinum-etoposide and thoracic radiotherapy (45 Gy twice daily or 60-70 Gy once daily) with curative intent, now followed by durvalumab consolidation (ADRIATIC), and cures 25-35%; extensive-stage disease receives platinum-etoposide with atezolizumab or durvalumab (IMpower133, CASPIAN), responds in most patients and relapses in most within a year, with tarlatamab now the preferred second-line drug. Prophylactic cranial irradiation or MRI surveillance follows response in both. TNM staging is applied in parallel but the two-stage system still drives treatment.", wikipedia: W("Small-cell_carcinoma"), cancers: ["sclc"], drugs: ["durvalumab", "atezolizumab", "tarlatamab"], related: ["chemoradiation", "prophylactic-cranial-irradiation", "consolidation-therapy"], sections: ["radiation", "chemotherapy"], trials: ["adriatic", "convert"] }),
  t({ id: "intravesical-therapy", name: "Intravesical therapy (BCG and bladder instillations)", category: "Treatment jargon", aka: ["intravesical", "intravesical BCG", "BCG", "Bacillus Calmette-Guérin", "bladder instillation", "instillation", "instillations", "intravesical chemotherapy", "intravesical gemcitabine", "intravesical mitomycin", "BCG maintenance", "BCG shortage", "TAR-200", "intravesical gene therapy", "BCG shortages", "bladder instillations"], tldr: "Putting a drug directly into the bladder through a catheter and leaving it for an hour or two, so it treats the lining without going round the body. BCG, a weakened tuberculosis vaccine, has been the most effective such drug for 45 years.", summary: "A single instillation of mitomycin or gemcitabine after TURBT reduces recurrence of low-risk tumours; six weekly BCG instillations plus maintenance for 1-3 years (SWOG schedule) is standard for intermediate- and high-risk NMIBC and carcinoma in situ, provoking a local immune response. BCG shortages have forced reduced-dose and alternative schedules. For BCG-unresponsive disease, intravesical nadofaragene firadenovec (gene therapy), cretostimogene (oncolytic virus), the TAR-200 gemcitabine-releasing device and systemic pembrolizumab now compete with cystectomy; adding durvalumab to BCG (POTOMAC, 2026) extended disease-free survival in high-risk disease. Chemohyperthermia and electromotive delivery are other enhancements.", wikipedia: W("BCG_vaccine#Cancer"), cancers: ["urothelial"], related: ["turbt", "nmibc-vs-mibc", "carcinoma-in-situ", "cystectomy"], sections: ["immunotherapy"] }),
  t({ id: "intraperitoneal-chemotherapy", name: "Intraperitoneal (IP) chemotherapy", category: "Treatment jargon", aka: ["intraperitoneal", "intraperitoneal chemotherapy", "IP chemotherapy", "IP/IV", "intraperitoneal paclitaxel", "intraperitoneal cisplatin", "IP catheter", "regional chemotherapy", "locoregional chemotherapy"], tldr: "Delivering chemotherapy directly into the abdominal cavity through a catheter, so the tumour deposits on the lining get a far higher dose than the rest of the body would tolerate.", summary: "Intraperitoneal cisplatin and paclitaxel after optimal debulking improved survival in ovarian cancer in GOG-172 (2006) but toxicity and catheter problems limited uptake, and GOG-252 (with bevacizumab) showed no advantage, so HIPEC given once at surgery has largely replaced repeated IP cycles. In gastric cancer with peritoneal metastases, intraperitoneal paclitaxel with systemic chemotherapy (PHOENIX-GC, Japanese phase 3) showed borderline benefit and is used in Japan; PIPAC is the laparoscopic aerosol version. Regional chemotherapy in general (hepatic arterial infusion, isolated limb perfusion, intravesical, intrathecal) shares the same rationale of concentrating dose where the cancer is.", wikipedia: W("Intraperitoneal_chemotherapy"), cancers: ["ovarian", "gastric"], technologies: ["hipec", "isolated-limb-perfusion"], related: ["hipec-procedure", "peritoneum", "debulking", "liver-directed-therapy"], sections: ["chemotherapy"] }),
  t({ id: "liver-directed-therapy", name: "Liver-directed therapy (TACE, TARE, HAI, ablation)", category: "Treatment jargon", aka: ["liver-directed", "liver-directed therapy", "liver-directed treatment", "locoregional treatment", "locoregional therapies", "hepatic arterial infusion", "HAI", "HAI pump", "hepatic artery infusion", "intra-arterial", "intra-arterial chemotherapy", "hepatic-dominant", "liver-dominant", "liver-limited", "liver-confined", "intrahepatic"], tldr: "The set of treatments aimed only at tumours in the liver, delivered through its artery or by needle, used when the liver is the main or only site of disease: chemoembolisation, radioactive beads, ablation and infusion pumps.", summary: "Because the liver is a common and often the sole site of spread (colorectal cancer, uveal melanoma, neuroendocrine tumours) and the primary site of hepatocellular carcinoma, treating it locally can control disease for years. Options are resection and ablation for limited disease, TACE and radioembolisation for multifocal disease, hepatic arterial infusion of floxuridine via an implanted pump (MSK, PUMP trial) for colorectal metastases, percutaneous hepatic perfusion (chemosaturation) for uveal melanoma metastases, and SBRT or proton therapy for lesions near vessels. They are increasingly combined with systemic therapy, and trials test sequencing rather than replacement.", wikipedia: W("Liver_cancer#Treatment"), cancers: ["hcc", "colorectal", "melanoma", "neuroendocrine"], technologies: ["percutaneous-hepatic-perfusion", "thermal-ablation"], related: ["tace", "tare", "hepatectomy", "radiofrequency-ablation"], sections: ["surgery", "radiopharma"] }),
  t({ id: "total-neoadjuvant-therapy", name: "Total neoadjuvant therapy (TNT, rectal cancer)", category: "Treatment jargon", aka: ["total neoadjuvant therapy", "total neoadjuvant treatment", "TNT approach", "short-course radiotherapy then chemotherapy", "consolidation chemotherapy", "induction TNT", "consolidation TNT", "RAPIDO", "PRODIGE 23", "OPRA"], tldr: "Giving all the chemotherapy and radiotherapy for rectal cancer before surgery rather than splitting it around the operation. It improves completion of chemotherapy, shrinks more tumours completely, and makes avoiding surgery possible for some patients.", summary: "Classic management was chemoradiation, surgery, then adjuvant FOLFOX, which a large share of patients never completed. TNT (RAPIDO: short-course radiotherapy then FOLFOX/CAPOX; PRODIGE 23: FOLFIRINOX then chemoradiation) halved distant metastases and doubled pathological complete responses, and OPRA showed that with consolidation chemotherapy about half of patients can be managed by watch-and-wait without surgery. PROSPECT showed FOLFOX alone can replace radiotherapy in selected intermediate-risk tumours, and dMMR rectal cancer is now treated with dostarlimab alone. The optimal sequence and who can safely skip which component remain active questions.", wikipedia: W("Colorectal_cancer#Rectal_cancer"), cancers: ["colorectal", "rectal-cancer"], related: ["organ-preservation", "total-mesorectal-excision", "chemoradiation", "hypofractionation", "folfox-family"], sections: ["radiation", "chemotherapy"] }),
  t({ id: "downstaging", name: "Downstaging and conversion therapy", category: "Treatment jargon", aka: ["downstaged", "downstage", "down-staging", "conversion therapy", "conversion chemotherapy", "conversion to resectable", "tumour shrinkage", "tumour downsizing", "downsizing", "within Milan criteria after downstaging", "bridging to transplant"], tldr: "Using drugs, radiotherapy or embolisation to shrink a cancer from a stage where curative treatment is impossible to one where it is: for example, shrinking liver metastases until they can be cut out, or liver cancer until it fits transplant criteria.", summary: "Downstaging is central to liver transplantation for hepatocellular carcinoma (patients beyond Milan criteria who respond to TACE or radioembolisation and stay within criteria for 3-6 months achieve post-transplant survival similar to those within criteria from the start, UNOS-DS) and to colorectal liver metastases, where 15-30% of initially unresectable patients become resectable after FOLFOXIRI or doublet plus antibody ('conversion therapy'). Neoadjuvant therapy that converts mastectomy to lumpectomy, or borderline to resectable pancreatic cancer, follows the same logic. Pathological downstaging (ypT/ypN lower than clinical stage) after neoadjuvant therapy is itself a favourable prognostic sign.", wikipedia: W("Neoadjuvant_therapy"), cancers: ["hcc", "colorectal", "pancreatic"], related: ["resectability", "bclc-staging", "tace", "neoadjuvant-adjuvant"], sections: ["surgery", "chemotherapy"] }),
  t({ id: "autologous-transplant", name: "Autologous stem cell transplant (ASCT)", category: "Treatment jargon", aka: ["ASCT", "auto-SCT", "autoSCT", "autologous transplant", "autologous stem cell transplantation", "autologous HSCT", "auto-HSCT", "autologous", "high-dose chemotherapy", "high-dose therapy", "HDT", "stem cell rescue", "stem cell support", "HDC-ASCT", "tandem transplant", "transplant-eligible myeloma"], tldr: "High-dose chemotherapy (melphalan in myeloma, BEAM in lymphoma) that would permanently destroy the bone marrow, made survivable by giving the patient back their own previously collected stem cells, which engraft in 10-14 days. Standard for fit myeloma patients and relapsed Hodgkin lymphoma; the cells rescue the marrow, they do not fight the cancer.", summary: "Stem cells are mobilised with G-CSF (plus plerixafor), collected by apheresis and frozen; after melphalan (myeloma) or BEAM (lymphoma) conditioning they are reinfused and engraft in 10-14 days. ASCT after quadruplet induction remains standard for fit myeloma patients (PERSEUS, DETERMINATION) though CAR-T is challenging it (CARTITUDE-5/6); in DLBCL it has been displaced from second line by CAR-T (ZUMA-7, TRANSFORM) but remains for later relapse and for Hodgkin lymphoma and germ cell tumours; tandem transplant is part of high-risk neuroblastoma therapy. Mortality is 1-2%; risks are infection during aplasia and later secondary MDS.", wikipedia: W("Hematopoietic_stem_cell_transplantation"), cancers: ["multiple-myeloma", "dlbcl", "hodgkin-lymphoma", "neuroblastoma"], trials: ["zuma-7", "transform", "cartitude-4"], drugs: ["melphalan"], related: ["apheresis", "conditioning-regimen", "allogeneic-transplant"], sections: ["cell-therapy", "chemotherapy"] }),
  t({ id: "allogeneic-transplant", name: "Allogeneic stem cell transplant (allo-SCT)", category: "Treatment jargon", aka: ["allo-SCT", "alloSCT", "allo-HSCT", "alloHCT", "HSCT", "HCT", "allogeneic transplant", "allogeneic transplantation", "allogeneic stem cell transplantation", "allogeneic HSCT", "allogeneic", "donor transplant", "bone marrow transplant", "BMT", "haploidentical", "haplo", "matched sibling donor", "matched unrelated donor", "MUD", "cord blood transplant", "post-transplant cyclophosphamide", "PTCy", "donor lymphocyte infusion", "DLI", "transplant-eligible", "transplant-ineligible"], tldr: "Replacing a patient's blood system with a donor's: chemotherapy wipes out the marrow, donor stem cells rebuild it, and the donor's immune cells hunt down leftover leukaemia. It is the only cure for adverse-risk or relapsed AML, high-risk ALL, MDS and myelofibrosis, and the riskiest treatment in oncology because of graft-versus-host disease and infection.", summary: "Used for adverse-risk or relapsed AML, high-risk ALL and MDS, myelofibrosis and some lymphomas. Donors are HLA-matched siblings, matched unrelated donors from registries, haploidentical relatives (now safe with post-transplant cyclophosphamide) or cord blood. Conditioning is myeloablative or reduced-intensity depending on age and fitness. The graft-versus-leukaemia effect is the cure mechanism; graft-versus-host disease, infection and organ toxicity are the price, with treatment-related mortality of 10-25%. MRD-guided transplant decisions, CAR-T bridging and maintenance drugs after transplant (FLT3 inhibitors, azacitidine) are refining who needs it.", wikipedia: W("Hematopoietic_stem_cell_transplantation"), cancers: ["aml", "all-leukemia"], technologies: ["allogeneic-cell-therapy"], related: ["conditioning-regimen", "gvhd", "autologous-transplant", "umrd"], sections: ["cell-therapy"] }),
  t({ id: "conditioning-regimen", name: "Conditioning regimen (myeloablative, reduced-intensity)", category: "Treatment jargon", aka: ["conditioning", "conditioning chemotherapy", "conditioning regimen", "myeloablative", "myeloablative conditioning", "reduced-intensity", "reduced-intensity conditioning", "RIC", "non-myeloablative", "total body irradiation", "TBI", "busulfan-cyclophosphamide", "BuCy", "BuMel", "BEAM", "fludarabine-based conditioning", "treosulfan-based"], tldr: "The chemotherapy (with or without whole-body radiation) given in the days before a stem cell transplant to destroy the diseased marrow and, for donor transplants, suppress the patient's immune system so the graft is not rejected.", summary: "Myeloablative conditioning (busulfan-cyclophosphamide, cyclophosphamide-TBI, high-dose melphalan for myeloma, BEAM for lymphoma) gives maximal anti-leukaemic effect but is tolerable only under about 60; reduced-intensity and non-myeloablative regimens (fludarabine-based, low-dose TBI, treosulfan) rely on the donor immune effect and have extended allogeneic transplant to older patients at the cost of higher relapse. Regimen choice is a trade-off between relapse and toxicity (mucositis, organ damage, infertility, veno-occlusive disease). Lymphodepletion before CAR-T is a milder cousin of the same idea.", wikipedia: W("Hematopoietic_stem_cell_transplantation#Conditioning_regimens"), drugs: ["melphalan", "cyclophosphamide", "treosulfan"], related: ["allogeneic-transplant", "autologous-transplant", "lymphodepletion", "gray-unit", "mucositis"], sections: ["cell-therapy", "chemotherapy"] }),
  t({ id: "gvhd", name: "Graft-versus-host disease (GVHD) and graft-versus-leukaemia", category: "Treatment jargon", aka: ["GVHD", "GvHD", "graft-versus-host", "graft-versus-host disease", "acute GVHD", "chronic GVHD", "cGVHD", "aGVHD", "steroid-refractory GVHD", "graft-versus-leukaemia", "graft-versus-leukemia", "GVL", "graft-versus-tumour", "GVHD prophylaxis"], tldr: "After a donor transplant, the donor's immune cells may attack the patient's skin, gut and liver (graft-versus-host disease) while also hunting down leftover leukaemia (graft-versus-leukaemia). The two effects are linked, so doctors try to keep enough of the second without too much of the first.", summary: "Acute GVHD (first 100 days: rash, diarrhoea, jaundice) affects 30-50% of recipients; chronic GVHD (skin, mouth, eyes, lungs, joints) can last years and is the main cause of late morbidity. Prophylaxis uses calcineurin inhibitors, methotrexate, post-transplant cyclophosphamide or abatacept; treatment is steroids, then ruxolitinib (REACH2/3), belumosudil, axatilimab or ibrutinib for refractory disease. Donor lymphocyte infusions deliberately provoke graft-versus-leukaemia at relapse. Allogeneic CAR-T and NK products use gene editing or donor selection to avoid GVHD, and CRS is a different, cytokine-driven phenomenon.", wikipedia: W("Graft-versus-host_disease"), drugs: ["ruxolitinib", "belumosudil", "ibrutinib"], related: ["allogeneic-transplant", "conditioning-regimen", "irae", "crs"], sections: ["cell-therapy"] }),
  t({ id: "lymphodepletion", name: "Lymphodepletion before CAR-T", category: "Treatment jargon", aka: ["lymphodepleting", "lymphodepleting chemotherapy", "lymphodepletion chemotherapy", "LD chemo", "Flu/Cy", "fludarabine/cyclophosphamide", "fludarabine-cyclophosphamide", "bendamustine lymphodepletion", "making room", "homeostatic expansion"], tldr: "A short course of chemotherapy (usually fludarabine and cyclophosphamide) given in the days before a CAR-T infusion to clear out the patient's own lymphocytes, making room and growth signals for the engineered cells to expand.", summary: "Lymphodepletion removes regulatory T cells and cytokine sinks, raising IL-7 and IL-15 levels so infused CAR-T cells proliferate; its intensity correlates with expansion, response and also toxicity. Fludarabine shortages led to bendamustine substitution with similar outcomes. It causes a week or two of cytopenias and infection risk and contributes to prolonged cytopenias after CAR-T. In vivo CAR-T approaches and some allogeneic products aim to work without lymphodepletion, which would remove a major barrier to outpatient and community delivery. Vein-to-vein time includes the wait for manufacturing before lymphodepletion can begin.", wikipedia: W("Chimeric_antigen_receptor_T_cell"), technologies: ["car-t", "in-vivo-car-t"], drugs: ["cyclophosphamide", "bendamustine"], related: ["conditioning-regimen", "vein-to-vein-time", "cytopenias", "apheresis"], sections: ["cell-therapy"] }),
  t({ id: "bridging-therapy", name: "Bridging therapy", category: "Treatment jargon", aka: ["bridging", "bridging chemotherapy", "bridging radiotherapy", "bridge to CAR-T", "bridge to transplant", "bridged", "holding therapy"], tldr: "Treatment given to keep a fast-growing cancer in check during the weeks between deciding on CAR-T (or transplant) and actually receiving it, while the cells are being manufactured or a donor found.", summary: "Aggressive lymphomas and leukaemias can progress or cause organ damage in the 3-6 weeks it takes to manufacture autologous CAR-T cells, so patients often receive bridging chemotherapy, steroids, radiotherapy to bulky sites, or bispecific antibodies; response to bridging and low disease burden at infusion predict better CAR-T outcomes and less CRS. Bridging must avoid drugs that harm T cells before apheresis and be timed so its toxicity has cleared before lymphodepletion. Its necessity is a strong argument for faster manufacturing and off-the-shelf allogeneic products; in the ZUMA-7 trial design, permitting bridging chemotherapy was a point of methodological debate.", wikipedia: W("Chimeric_antigen_receptor_T_cell"), technologies: ["car-t", "allogeneic-cell-therapy"], trials: ["zuma-7"], related: ["vein-to-vein-time", "lymphodepletion", "apheresis", "salvage-therapy"], sections: ["cell-therapy"] }),
  t({ id: "vein-to-vein-time", name: "Vein-to-vein time and manufacturing slots", category: "Treatment jargon", aka: ["vein-to-vein", "vein to vein", "manufacturing time", "manufacturing slot", "manufacturing slots", "turnaround time", "manufacturing failure", "out-of-specification", "OOS product", "slot allocation", "chain of identity", "chain of custody", "cryopreserved product", "fresh product", "manufacturing failures"], tldr: "For CAR-T, the number of days from collecting the patient's cells to infusing the finished product, typically three to six weeks. Every day counts when the disease is aggressive, and manufacturing capacity (slots) limits how many patients can be treated.", summary: "Vein-to-vein time includes shipping, manufacturing (transduction, expansion, release testing), cryopreservation and scheduling; commercial products average 3-4 weeks in the US and longer in Europe. Delays force bridging therapy and cost lives, which is the motivation for rapid manufacturing platforms (T-Charge, 2-day processes), point-of-care and closed automated manufacturing, in vivo CAR-T and allogeneic products. Slots are allocated per centre and per month, out-of-specification products may still be infused under expanded access, and chain-of-identity software tracks each patient's cells. In ZUMA-7 the median vein-to-vein time of about 4 weeks versus 52 days in another trial was cited as a reason for different outcomes.", wikipedia: W("Chimeric_antigen_receptor_T_cell"), technologies: ["car-t", "closed-automated-cell-manufacturing", "point-of-care-cell-manufacturing", "cell-therapy-orchestration-software"], related: ["apheresis", "bridging-therapy", "lymphodepletion"], sections: ["cell-therapy"] }),
  t({ id: "antigen-escape", name: "Antigen escape (antigen loss, lineage switch)", category: "Treatment jargon", aka: ["antigen escape", "antigen loss", "antigen-negative relapse", "CD19-negative relapse", "CD19-negative", "BCMA-negative", "BCMA loss", "target loss", "target downregulation", "antigen downregulation", "antigen-low", "lineage switch", "lineage plasticity", "trogocytosis", "antigen heterogeneity", "antigen-negative"], tldr: "When a cancer treated with a therapy aimed at one surface marker (CD19, BCMA, HER2) survives by shedding that marker, so the drug has nothing to grab. About a third of relapses after CD19 CAR-T are antigen-negative.", summary: "Mechanisms include mutations or splice variants that remove the epitope, deletion of the gene (TNFRSF17/BCMA biallelic loss in myeloma), lineage switch (B-ALL relapsing as myeloid leukaemia under CD19 pressure), trogocytosis (CAR-T cells stripping antigen off tumour cells), and pre-existing antigen-low subclones. Responses are dual-targeting CARs (CD19/CD22, BCMA/GPRC5D), sequencing to a different antigen (GPRC5D or FcRH5 after BCMA), logic-gated CARs and antigen-independent strategies. It is distinct from T-cell-intrinsic failure (exhaustion, poor persistence), which is the other main cause of relapse, and flow cytometry at relapse distinguishes the two.", wikipedia: W("Chimeric_antigen_receptor_T_cell"), technologies: ["car-t", "t-cell-engager", "logic-gated-therapeutics"], targets: ["cd19", "bcma"], related: ["t-cell-exhaustion-term", "resistance", "flow-cytometry"], sections: ["cell-therapy"] }),
  t({ id: "t-cell-exhaustion-term", name: "T-cell exhaustion and CAR-T persistence", category: "Treatment jargon", aka: ["exhaustion", "exhausted T cells", "T-cell fitness", "T cell fitness", "T-cell dysfunction", "CAR-T persistence", "CAR persistence", "CAR-T expansion", "peak expansion", "in vivo expansion", "B-cell aplasia", "loss of persistence", "memory phenotype", "stem-like T cells"], tldr: "Immune T cells that have been fighting too long become 'exhausted': sluggish, covered in inhibitory receptors, unable to kill. It limits both the patient's natural anti-tumour response and how long engineered CAR-T cells keep working (persistence).", summary: "Exhaustion is driven by chronic antigen exposure and marked by PD-1, TIM-3, LAG-3 and TOX expression; checkpoint inhibitors partly reverse it, which is their mechanism. For CAR-T, the fitness of the patient's starting T cells (damaged by prior chemotherapy, especially bendamustine) predicts expansion and response, and peak expansion and persistence correlate with durable remission; ongoing B-cell aplasia is a convenient marker that CD19 CAR-T cells are still active. Engineering answers include 4-1BB costimulation (longer persistence than CD28), armoured CARs, knockout of exhaustion-associated genes, and collecting cells earlier in the disease course. Persistence matters less when the tumour is eliminated quickly, as in ALL.", wikipedia: W("T_cell_exhaustion"), technologies: ["car-t", "armored-car", "checkpoint-inhibitor"], related: ["antigen-escape", "cold-vs-hot", "hypogammaglobulinaemia"], sections: ["cell-therapy", "immunotherapy"] }),
  t({ id: "prrt-term", name: "PRRT (peptide receptor radionuclide therapy)", category: "Treatment jargon", aka: ["PRRT", "peptide receptor radionuclide therapy", "177Lu-DOTATATE", "lutetium DOTATATE", "DOTATATE", "DOTATOC", "somatostatin analogue", "somatostatin analogues", "SSA", "SSAs", "SSTR-targeted", "SSTR imaging", "somatostatin receptor imaging", "alpha PRRT"], tldr: "A radioactive drug for neuroendocrine tumours: a small peptide that homes to the somatostatin receptor on the tumour cells carries lutetium-177, which irradiates them from within. Given four times, two months apart.", summary: "Neuroendocrine tumours overexpress somatostatin receptor 2, imaged with gallium-68 or copper-64 DOTATATE PET and treated first with cold somatostatin analogues (octreotide, lanreotide) for symptom and growth control. 177Lu-DOTATATE (NETTER-1, approved 2018) improved progression-free survival dramatically in midgut NETs and NETTER-2 (2024) moved it to first line in high-grade tumours; 177Lu-edotreotide (COMPETE) followed. Alpha-emitting versions (212Pb-DOTAMTATE, 225Ac-DOTATATE) are in phase 3 for PRRT-refractory disease. Toxicities are marrow suppression, kidney dose and a small risk of MDS. Together with radioiodine and PSMA therapy it defines the theranostic model.", wikipedia: W("Peptide_receptor_radionuclide_therapy"), cancers: ["neuroendocrine"], targets: ["sstr2"], technologies: ["radioligand-therapy", "targeted-alpha-therapy"], drugs: ["ga68-dotatate"], related: ["prrt", "theranostics", "dosimetry", "radioiodine-therapy", "alpha-vs-beta"], sections: ["radiopharma"] }),
  t({ id: "radioiodine-term", name: "Radioiodine therapy (I-131)", category: "Treatment jargon", aka: ["radioiodine", "radioactive iodine", "radioiodine ablation", "radioiodine therapy", "I-131", "131I", "iodine-131", "RAI-refractory", "radioiodine-refractory", "RAI-avid", "radioiodine-avid", "iodine-avid", "iodine uptake", "redifferentiation", "recombinant TSH", "rhTSH"], tldr: "Swallowing a capsule of radioactive iodine after thyroid surgery: thyroid cells (including cancer cells) are the only ones that soak up iodine, so the radiation destroys leftover thyroid tissue and metastases while sparing everything else. It was the first targeted radiotherapy, in 1946.", summary: "Differentiated (papillary and follicular) thyroid cancer retains iodine uptake, so I-131 ablates remnant tissue after total thyroidectomy in intermediate- and high-risk patients and treats iodine-avid metastases; low-risk patients no longer need it (ESTIMABL2, IoN). Thyroglobulin and whole-body scans monitor for recurrence. 'Radioiodine-refractory' disease (about 5-15%, more in poorly differentiated and BRAF-mutant tumours) is treated with lenvatinib, sorafenib or targeted drugs for RET, NTRK and BRAF alterations, and MEK/BRAF inhibitors can restore iodine uptake ('redifferentiation'). Side effects are salivary gland damage, dry mouth and a small excess of secondary cancers at high cumulative doses.", wikipedia: W("Iodine-131"), cancers: ["thyroid"], drugs: ["lenvatinib", "sorafenib"], related: ["radioiodine-therapy", "thyroidectomy", "theranostics", "prrt", "tumour-markers"], sections: ["radiopharma"] }),
  t({ id: "cns-penetration", name: "CNS penetration (brain-penetrant drugs)", category: "Treatment jargon", aka: ["CNS penetration", "CNS-penetrant", "CNS penetrant", "brain-penetrant", "brain penetrant", "brain penetration", "blood-brain barrier penetration", "BBB-penetrant", "CNS-active", "intracranial efficacy", "CNS efficacy", "CNS progression", "CNS protection", "CSF concentration", "Kp,uu", "efflux transporter", "P-glycoprotein substrate", "efflux transporters"], tldr: "How well a drug crosses from the blood into the brain, where most cancer drugs are kept out by the blood-brain barrier. Brain-penetrant pills can treat and prevent brain metastases; those that are not leave the brain as a sanctuary where the cancer regrows.", summary: "Third-generation EGFR (osimertinib) and ALK (alectinib, lorlatinib) inhibitors were designed for CNS penetration and cut brain progression dramatically compared with earlier drugs; tucatinib, and unexpectedly T-DXd, are active against HER2-positive brain metastases; temozolomide, lomustine and vorasidenib are brain-penetrant by design. Penetration is measured as unbound brain-to-plasma ratio (Kp,uu) or CSF concentration and is limited by efflux pumps (P-glycoprotein, BCRP). Intracranial response rates and CNS progression-free survival are now standard secondary endpoints in lung and breast cancer trials, and intrathecal or intraventricular delivery bypasses the barrier for leptomeningeal disease.", wikipedia: W("Blood%E2%80%93brain_barrier"), drugs: ["osimertinib", "tucatinib", "trastuzumab-deruxtecan", "temozolomide"], related: ["brain-metastases", "leptomeningeal-disease", "intrathecal-therapy", "tki-term"], sections: ["targeted-therapy"] }),
  t({ id: "pharmacokinetics", name: "Pharmacokinetics (PK), half-life and exposure", category: "Treatment jargon", aka: ["pharmacokinetic", "pharmacokinetics", "PK/PD", "pharmacodynamics", "half-life", "half life", "exposure-response", "exposure–response", "drug exposure", "AUC", "Cmax", "steady state", "steady-state", "bioavailability", "oral bioavailability", "drug-drug interaction", "CYP3A4", "food effect", "therapeutic drug monitoring", "TDM", "flat dosing", "weight-based dosing", "body surface area", "mg/m²", "mg/kg", "pharmacodynamic"], tldr: "How a drug moves through the body: how much is absorbed, how high the blood level gets, how long it lasts (half-life) and how it is cleared. These numbers decide the dose, the schedule and whether a pill can be taken with food or other medicines.", summary: "Antibodies have half-lives of 2-4 weeks and are dosed every 2-6 weeks, often now at flat doses (pembrolizumab 400 mg q6w) rather than by weight; small molecules are dosed daily and interact with CYP3A4 inhibitors, acid suppressants and food; chemotherapy is dosed by body surface area with organ-function adjustments. Exposure-response analyses link drug levels to efficacy and toxicity and underpin Project Optimus's push to find optimal rather than maximal doses; therapeutic drug monitoring is used for busulfan, methotrexate and increasingly for TKIs. Radiopharmaceutical PK determines tumour versus kidney and marrow dose (dosimetry). Poor oral bioavailability has ended more than one promising drug's development.", wikipedia: W("Pharmacokinetics"), technologies: ["project-optimus"], related: ["therapeutic-index", "mtd", "dose-modification", "dosimetry"], sections: ["drug-discovery"], journals: ["clinical-pharmacology-and-therapeutics"] }),
  t({ id: "therapeutic-index", name: "Therapeutic index (therapeutic window)", category: "Treatment jargon", aka: ["therapeutic window", "therapeutic ratio", "narrow therapeutic index", "narrow therapeutic window", "wide therapeutic window", "safety margin", "tolerability", "tolerable", "well tolerated", "well-tolerated", "toxicity profile", "safety profile", "on-target toxicity", "off-target toxicity", "on-target off-tumour", "on-target, off-tumour", "off-tumour", "mechanism-based toxicity", "class effect", "class effects", "toxicity profiles"], tldr: "The gap between the dose that works and the dose that harms. Classic chemotherapy has a narrow window (the dose that kills the tumour nearly kills the patient); a wider window is the whole point of targeted drugs, ADCs and immunotherapy.", summary: "Toxicity can be on-target (the drug hits its intended molecule in normal tissue that also expresses it: EGFR inhibitors and skin, HER2 and heart, CD19 CAR-T and normal B cells, 'on-target off-tumour') or off-target (unintended molecules: hERG and QT prolongation, kinase promiscuity). ADCs widen the window by delivering payloads selectively, but the payload's free fraction sets their class effects (ILD for deruxtecan, ocular toxicity for MMAF, neuropathy for MMAE). Dose-finding in phase 1 traditionally sought the maximum tolerated dose; Project Optimus reframes it as finding the dose with the best therapeutic index, and tolerability over months of continuous therapy is now recognised as part of efficacy.", wikipedia: W("Therapeutic_index"), technologies: ["project-optimus", "adc"], related: ["pharmacokinetics", "mtd", "dose-limiting-toxicity", "ild"], sections: ["drug-discovery"] }),
  t({ id: "centralisation", links: [{ label: "Birkmeyer et al., Hospital volume and surgical mortality in the United States (NEJM 2002)", url: "https://doi.org/10.1056/NEJMsa012337" }], name: "Centralisation and high-volume centres", category: "Treatment jargon", aka: ["centralisation", "centralization", "centralised", "centralized", "high-volume centre", "high-volume centres", "high-volume center", "high-volume", "volume-outcome", "volume–outcome", "hospital volume", "surgeon volume", "specialist centre", "referral centre", "tertiary centre", "expert centre", "reference centre", "centres of excellence", "regionalisation", "regionalization", "centers of excellence", "reference centres", "referral centres", "specialist centres"], tldr: "Concentrating complex cancer surgery (oesophagus, pancreas, bladder, liver) and rare cancer care in fewer hospitals that perform each operation often. Hospitals and surgeons with high volumes have fewer deaths and complications, so the Netherlands, Denmark and parts of the UK mandate minimum volumes; patients travel further, and rural access suffers.", summary: "The volume-outcome relationship is among the most robust findings in health services research: mortality after oesophagectomy, pancreatectomy, cystectomy and complex hepatobiliary surgery is roughly halved in high-volume centres, and the Netherlands, Denmark and parts of the UK have mandated minimum volumes. The same logic applies to sarcoma, paediatric cancers, CAR-T and allogeneic transplant, which are delivered only in accredited centres. Costs are travel burden, inequity for rural patients and loss of local skills, which telemedicine, hub-and-spoke networks and shared care (systemic therapy locally, surgery centrally) try to mitigate.", technologies: ["telemedicine-teleoncology", "community-oncology-networks"], related: ["oesophagectomy", "whipple", "surgical-morbidity", "rare-cancers"], sections: ["surgery"] }),
  t({ id: "surgical-morbidity", name: "Surgical morbidity and postoperative complications", category: "Treatment jargon", aka: ["morbidity", "postoperative morbidity", "perioperative morbidity", "perioperative mortality", "postoperative mortality", "30-day mortality", "90-day mortality", "operative mortality", "postoperative complications", "complication rate", "complication rates", "anastomotic leak", "anastomotic leakage", "anastomosis", "pancreatic fistula", "wound infection", "surgical site infection", "Clavien-Dindo", "length of stay", "readmission", "failure to rescue", "textbook outcome", "readmissions"], tldr: "The harms of an operation itself: complications (leaks, infections, bleeding, pneumonia), time in hospital, and deaths within 30 or 90 days. Big cancer operations carry real risk, which is weighed against their chance of cure and drives the search for less invasive alternatives.", summary: "Morbidity is graded by the Clavien-Dindo scale and reported alongside mortality; oesophagectomy and pancreaticoduodenectomy have 30-50% complication rates and 2-5% mortality, colectomy far less. Anastomotic leak (where two ends of bowel are joined) is the most feared complication in gastrointestinal surgery and can delay adjuvant chemotherapy or cause death. Complications are reduced by centralisation, minimally invasive approaches, enhanced recovery (ERAS) protocols, prehabilitation and geriatric assessment; 'failure to rescue' (dying from a complication) distinguishes good from poor hospitals more than complication rates do. Ninety-day mortality is now preferred over 30-day because deaths from complications are often later.", wikipedia: W("Complication_(medicine)"), technologies: ["prehabilitation", "geriatric-assessment"], related: ["centralisation", "eras-perioperative-nutrition", "oesophagectomy", "whipple", "minimally-invasive-surgery"], sections: ["surgery"] }),

  // ---- Trials & regulation ----
  t({ id: "confirmatory-trial", name: "Confirmatory trial", category: "Trials & regulation", aka: ["confirmatory", "confirmatory study", "confirmatory phase 3", "confirmatory evidence", "post-marketing requirement", "postmarketing requirement", "post-approval trial", "verify clinical benefit", "conversion to full approval", "dangling approval", "dangling accelerated approval", "confirmatory studies", "post-marketing requirements"], tldr: "The randomised trial a company must run after an accelerated approval to prove the drug really helps patients live longer or better. If it fails or never finishes, the approval is supposed to be withdrawn.", summary: "Accelerated approvals rest on surrogate endpoints (response rate, pCR, MRD) from single-arm or early trials; the confirmatory trial tests overall survival, progression-free survival or another clinical benefit against a control. The 2022 FDORA law lets the FDA require the confirmatory trial to be under way at approval and streamlines withdrawal when it fails. Notable failures and withdrawals include PI3K inhibitors in lymphoma, several checkpoint-inhibitor indications ('dangling approvals' reviewed by ODAC in 2021), and melphalan flufenamide. Regulators increasingly scrutinise whether the confirmatory population matches the accelerated one (STARGLO complete response letter).", wikipedia: W("Accelerated_approval_(FDA)"), related: ["accelerated-approval", "full-approval", "approval-withdrawal", "surrogate-endpoint", "complete-response-letter", "surrogate-validation", "trial-lifecycle", "trial-failure-modes"], sections: ["drug-discovery"], trials: ["announce", "atlantis", "keynote-522"] }),
  t({ id: "complete-response-letter", name: "Complete response letter (CRL)", category: "Trials & regulation", aka: ["CRL", "complete response letter", "FDA rejection", "refusal to file", "refuse-to-file", "resubmission", "class 2 resubmission", "negative opinion", "CHMP negative opinion", "complete response letters"], tldr: "The FDA's formal 'not yet' to a drug application, listing what must be fixed before approval: more data, a different trial population, or manufacturing problems. Not the same as 'complete response' to treatment.", summary: "A CRL ends a review cycle without approval; the sponsor can resubmit (class 1 or 2, with 2- or 6-month review clocks), appeal, or abandon. Reasons in oncology have included trials run only in China without US-relevant populations (sintilimab, camrelizumab-rivoceranib), inadequate confirmatory data for a population, unresolved safety signals, and manufacturing site inspection failures, which caused a wave of CRLs in 2022-25. The FDA began publishing CRLs in 2025. The EMA equivalent is a negative CHMP opinion or a withdrawal of the application before opinion.", wikipedia: W("Food_and_Drug_Administration"), related: ["bla-nda", "confirmatory-trial", "regulatory-agencies", "odac"], sections: ["drug-discovery"] }),
  t({ id: "label-indication", name: "Label, indication and label expansion", category: "Trials & regulation", aka: ["label expansion", "label expansions", "indication", "approved indication", "new indication", "expanded indication", "expanded label", "expanded approval", "US label", "FDA label", "drug label", "prescribing information", "on-label", "off-label", "off-label use", "sBLA", "sNDA", "supplemental BLA", "supplemental NDA", "supplemental approval", "boxed warning", "black box warning", "label restriction", "boxed warnings", "label restrictions"], tldr: "A drug's label is the official document stating exactly which patients (the indication) it is approved for, at what dose, with what warnings. Each new cancer, line of therapy or combination added to it is a label expansion, approved through a supplemental application.", summary: "Oncology drugs accumulate indications over years (pembrolizumab has more than 40), each backed by its own trial and reviewed as a supplemental BLA or NDA. The label wording (for example 'PD-L1 CPS ≥10', 'after at least two prior lines', 'in combination with chemotherapy') defines reimbursement and guideline placement, and restrictions can be tightened (dose, population) after new data. Off-label prescribing, guided by NCCN compendium listings, is legal and common, especially for rare cancers, but may not be reimbursed. Boxed warnings flag the most serious risks (ILD for T-DXd, CRS for T-cell engagers) and REMS programmes add access controls.", wikipedia: W("Drug_labelling"), technologies: ["nccn-compendium"], related: ["bla-nda", "full-approval", "accelerated-approval", "companion-diagnostic-term"], sections: ["drug-discovery"] }),
  t({ id: "bla-nda", name: "BLA / NDA / MAA (marketing applications) and PDUFA dates", category: "Trials & regulation", aka: ["BLA", "NDA", "MAA", "biologics license application", "new drug application", "marketing authorisation application", "marketing application", "regulatory submission", "filing accepted", "submission accepted", "regulatory review", "PDUFA", "PDUFA date", "action date", "target action date", "goal date", "rolling submission", "standard review", "10-month review", "6-month review", "new drug applications", "regulatory submissions"], tldr: "The formal application to sell a drug: a New Drug Application for small molecules, a Biologics License Application for antibodies and cell therapies (US), or a Marketing Authorisation Application (EU). The PDUFA date is the deadline by which the FDA has promised a decision.", summary: "Applications run to hundreds of thousands of pages covering trials, manufacturing and labelling. Under the Prescription Drug User Fee Act the FDA commits to act within 10 months of filing acceptance (standard) or 6 months (priority review), plus a 60-day filing period, so 'PDUFA date' is watched by patients and investors alike. Real-Time Oncology Review and rolling submissions shorten the clock; Project Orbis coordinates review with other countries. Outcomes are approval, a complete response letter, or (rarely) withdrawal by the sponsor. Supplemental applications (sBLA/sNDA) add indications to existing drugs.", wikipedia: W("Prescription_Drug_User_Fee_Act"), technologies: ["real-time-oncology-review", "project-orbis"], related: ["label-indication", "complete-response-letter", "breakthrough-designation", "regulatory-agencies"], sections: ["drug-discovery"] }),
  t({ id: "orphan-designation", name: "Orphan drug designation", category: "Trials & regulation", aka: ["orphan", "orphan drug", "orphan designation", "orphan drug status", "orphan status", "orphan indication", "Orphan Drug Act", "orphan exclusivity", "rare disease designation", "rare paediatric disease designation", "priority review voucher", "priority review vouchers"], tldr: "A status for drugs treating rare diseases (under 200,000 US patients, or under 5 in 10,000 in the EU) that gives the company tax credits, fee waivers and seven to ten years of market exclusivity, to make rare-disease drug development worthwhile.", summary: "Most cancers taken subtype by subtype qualify, so oncology accounts for a large share of orphan designations, and blockbuster drugs such as imatinib and rituximab began as orphans. The 1983 US Orphan Drug Act and the 2000 EU Orphan Regulation drove development for rare cancers, but critics note 'salami-slicing' of common cancers into orphan subsets, high prices, and exclusivity blocking competitors. Rare paediatric disease designation adds a transferable priority review voucher worth around $100 million, an incentive that has funded several paediatric oncology drugs (dinutuximab, eflornithine).", wikipedia: W("Orphan_drug"), technologies: ["rare-cancers"], related: ["breakthrough-designation", "fast-track-rmat", "label-indication", "orphan-drug-act", "eu-orphan-regulation", "inflation-reduction-act", "us-regulatory-exclusivity", "amnog", "eu-pharma-package", "bpca-prea"], sections: ["drug-discovery"] }),
  t({ id: "fast-track-rmat", name: "Fast Track and RMAT designations", category: "Trials & regulation", aka: ["Fast Track", "fast-track designation", "Fast Track designation", "RMAT", "regenerative medicine advanced therapy", "RMAT designation", "PRIME", "PRIority MEdicines", "expedited programme", "expedited program", "expedited pathway", "expedited review", "expedited approval", "fast track designations"], tldr: "Two of the FDA's expedited programmes: Fast Track gives drugs for serious unmet needs more frequent FDA meetings and rolling review; RMAT is the equivalent for cell and gene therapies. Neither guarantees approval or changes the evidence standard.", summary: "Fast Track (1997) is granted on preclinical or early clinical data and is the most common designation; Breakthrough Therapy (2012) requires preliminary evidence of substantial improvement and brings intensive guidance; RMAT (2016, 21st Century Cures Act) applies breakthrough-like benefits to cell therapies, gene therapies and tissue-engineered products, including CAR-T; Priority Review shortens the review clock; Accelerated Approval permits surrogate endpoints. The EMA's PRIME and Japan's Sakigake are counterparts. Designations are frequently announced in press releases and can be rescinded; roughly a third of Fast Track drugs are eventually approved.", wikipedia: W("Fast_track_(FDA)"), related: ["breakthrough-designation", "accelerated-approval", "orphan-designation", "bla-nda", "fdasia-2012", "21st-century-cures-act", "sakigake", "ilap", "eu-regulation-726-2004"], sections: ["drug-discovery"] }),
  t({ id: "conditional-approval", name: "Conditional marketing authorisation (EU)", category: "Trials & regulation", aka: ["conditional approval", "conditional marketing authorisation", "conditional marketing authorization", "CMA", "conditional authorisation", "conditionally approved", "approval under exceptional circumstances", "exceptional circumstances", "conditional NMPA approval", "conditional approval in China", "specific obligations", "conditional approvals", "conditional registration"], tldr: "The European (and Chinese) counterpart of accelerated approval: a drug for an unmet need is authorised on less complete data with specific obligations to deliver confirmatory results, renewed yearly until converted to standard approval.", summary: "European Union, regulation. Conditional marketing authorisation is provided for by Article 14-a of Regulation (EC) No 726/2004 and detailed in Commission Regulation (EC) No 507/2006; China wrote conditional approval into its Drug Administration Law in 2019 and Japan has a statutory conditional early approval system from 2020. Primary text: EUR-Lex for the two EU regulations; the EMA conditional marketing authorisation page explains the procedure.\n\nThe EMA grants conditional marketing authorisation when benefit to public health outweighs the risk of incomplete data, typically on phase 2 or interim phase 3 results; it is valid for one year, renewable, and converts to standard authorisation once obligations are met (median about 4 years). Around 30 oncology drugs hold or held CMAs, including CAR-T products and several ADCs. China's NMPA grants conditional approvals extensively for domestic PD-1 antibodies and other drugs, often on single-arm data, with confirmatory trials required. Approval under exceptional circumstances is for diseases where full data can never be collected.", wikipedia: W("European_Medicines_Agency"), links: [{ label: "Wikipedia", url: W("European_Medicines_Agency") }, { label: "EUR-Lex: Regulation (EC) No 507/2006", url: "https://eur-lex.europa.eu/eli/reg/2006/507/oj" }, { label: "EMA: conditional marketing authorisation", url: "https://www.ema.europa.eu/en/human-regulatory-overview/marketing-authorisation/conditional-marketing-authorisation" }], related: ["accelerated-approval", "full-approval", "confirmatory-trial", "regulatory-agencies", "eu-regulation-726-2004", "china-drug-administration-law", "japan-conditional-early-approval", "fdora-2022", "cancer-drugs-fund", "france-early-access", "eu-pharma-package"], sections: ["drug-discovery"] }),
  t({ id: "full-approval", name: "Full (traditional, regular) approval", category: "Trials & regulation", aka: ["full approval", "traditional approval", "regular approval", "standard approval", "converted to full approval", "conversion to regular approval", "full FDA approval", "received full approval", "gained full approval", "regular FDA approval"], tldr: "The ordinary form of drug approval, granted when a trial has shown real clinical benefit such as longer survival, as opposed to an accelerated approval granted on an early stand-in measure and still awaiting confirmation.", summary: "Most oncology drugs first approved under accelerated approval later 'convert' to full approval when the confirmatory trial reads out positive (blinatumomab in 2018, tarlatamab in 2026 after DeLLphi-304); others go straight to full approval on a positive randomised phase 3. The distinction matters for payers and guidelines, and because a drug with accelerated approval may lose its indication if confirmation fails. Regulators may convert with a narrowed indication (ODAC concerns on dosing, as with belantamab's US label), and the phrase 'full approval' is often reported as a milestone in company and trial pages.", wikipedia: W("New_Drug_Application"), related: ["accelerated-approval", "confirmatory-trial", "conditional-approval", "approval-withdrawal", "fdora-2022", "fdca", "bla-nda", "japan-conditional-early-approval", "cancer-drugs-fund"], sections: ["drug-discovery"] }),
  t({ id: "approval-withdrawal", name: "Indication withdrawal", category: "Trials & regulation", aka: ["withdrawn", "voluntary withdrawal", "voluntarily withdrawn", "withdrawn indication", "withdrawn from the US market", "withdrawn in the US", "market withdrawal", "indication withdrawn", "re-approved", "re-approval", "reapproved"], tldr: "When a drug's approval for a particular cancer is cancelled, usually because the confirmatory trial failed to show benefit, sometimes because of safety. The drug may stay on the market for its other uses, and occasionally an indication is later re-approved on new data.", summary: "Withdrawals cluster around accelerated approvals: atezolizumab and pembrolizumab in some bladder and gastric settings (2021), PI3K inhibitors idelalisib, duvelisib, umbralisib and copanlisib in lymphoma (2022-23), melphalan flufenamide, ibrutinib in mantle cell and marginal zone lymphoma (2023), and tazemetostat (2026). Belantamab mafodotin was withdrawn in 2022 and re-approved in 2025 after DREAMM-7/8. Withdrawals are usually 'voluntary' at the FDA's request; formal revocation is rare and slow. Patients already benefiting are typically allowed to continue, and the drug often remains approved in other regions.", wikipedia: W("Drug_withdrawal"), drugs: ["idelalisib", "duvelisib", "umbralisib", "copanlisib", "tazemetostat", "belantamab-mafodotin"], related: ["accelerated-approval", "confirmatory-trial", "full-approval", "odac", "fdora-2022", "conditional-approval", "eu-regulation-726-2004", "cancer-drugs-fund", "medicare-ced"], sections: ["drug-discovery"] }),
  t({ id: "odac", wikipedia: W("Oncology_Drug_Advisory_Committee"), links: [{ label: "FDA: Oncologic Drugs Advisory Committee", url: "https://www.fda.gov/advisory-committees/human-drug-advisory-committees/oncologic-drugs-advisory-committee" }], name: "ODAC (Oncologic Drugs Advisory Committee)", category: "Trials & regulation", aka: ["ODAC", "advisory committee", "FDA advisory committee", "AdCom", "advisory panel", "ODAC vote", "advisory committee meeting", "briefing document", "FDA briefing document"], tldr: "A panel of outside experts the FDA convenes to debate contentious cancer drug applications in public and vote on whether the evidence is adequate. The FDA usually, but not always, follows the vote.", summary: "ODAC meetings dissect trial design, crossover, subgroup results, dosing and the applicability of foreign data; landmark sessions include the 2021 review of 'dangling' accelerated approvals, the 2022 discussion of China-only trials, the 2023-24 debates on dose optimisation and on PD-1 inhibitors in PD-L1-low gastric and oesophageal cancer, and the 2025 votes on camizestrant (SERENA-6) and belantamab dosing. Briefing documents published before meetings are among the most candid public analyses of oncology trials. Similar committees exist at the EMA (CHMP with its scientific advisory groups).", trials: ["serena-6"], related: ["bla-nda", "complete-response-letter", "approval-withdrawal", "regulatory-agencies"], sections: ["drug-discovery"] }),
  t({ id: "regulatory-agencies", name: "Regulators beyond the FDA (EMA/CHMP, MHRA, PMDA, NMPA, TGA)", category: "Trials & regulation", aka: ["CHMP", "Committee for Medicinal Products for Human Use", "MHRA", "PMDA", "NMPA", "TGA", "Health Canada", "Swissmedic", "ANVISA", "regulator", "regulators", "regulatory agency", "regulatory agencies", "regulatory approval", "marketing authorisation", "marketing authorization", "European Commission approval", "EU approval", "approved in the EU", "approved in Japan", "approved in China", "approved in the UK", "multiregional", "multi-regional trial", "China-only data", "reliance pathway", "Access Consortium", "marketing authorisations", "reliance pathways"], tldr: "Every country or bloc has its own drug regulator: the EMA (with its CHMP committee) for the EU, the MHRA for the UK, the PMDA for Japan, the NMPA for China, the TGA for Australia. The same drug can be approved in one place years before another, or on different evidence.", summary: "The FDA and EMA usually agree but differ in timing and detail (the EMA is stricter on surrogate endpoints and single-arm data); the CHMP issues an opinion that the European Commission formalises about two months later. China's NMPA has approved dozens of domestic PD-1 antibodies and other drugs on China-only or conditional data that the FDA has rejected. Project Orbis (FDA-led) and the Access Consortium (UK, Canada, Australia, Singapore, Switzerland) share reviews to speed approvals; reliance pathways let smaller agencies adopt others' decisions. Regulatory fragmentation and the demand for multiregional trials are recognised bottlenecks for global access.", wikipedia: W("Regulation_of_therapeutic_goods"), technologies: ["project-orbis"], related: ["bla-nda", "conditional-approval", "hta"], sections: ["drug-discovery"] }),
  t({ id: "hta", name: "Health technology assessment (HTA), reimbursement and QALYs", category: "Trials & regulation", aka: ["HTA", "health technology assessment", "reimbursement", "reimbursed", "reimbursement decision", "coverage decision", "payer", "payers", "cost-effectiveness", "cost effectiveness", "cost-effective", "QALY", "QALYs", "quality-adjusted life year", "incremental cost-effectiveness ratio", "willingness-to-pay threshold", "value-based pricing", "managed access", "Cancer Drugs Fund", "technology appraisal", "G-BA", "AMNOG", "HAS", "PBAC", "CADTH", "value assessment", "coverage decisions", "technology appraisals"], tldr: "Approval says a drug works; reimbursement says who will pay. Health technology assessment bodies (NICE, G-BA, PBAC) judge whether the benefit is worth the price, often per quality-adjusted life year, and can delay access for years after approval.", summary: "A QALY is one year of life in perfect health; NICE's threshold is about £20,000-30,000 per QALY (higher for end-of-life treatments), and drugs above it are rejected or admitted via managed access schemes such as the Cancer Drugs Fund with confidential discounts. Germany assesses added benefit and negotiates price after a year of free pricing; France's HAS grades clinical benefit; the US has no national HTA and Medicare must cover approved cancer drugs, though ICER publishes non-binding assessments and the IRA now permits Medicare negotiation. The gap between approval and reimbursement (often 1-2 years in Europe, longer in middle-income countries) is a major access bottleneck.", wikipedia: W("Health_technology_assessment"), technologies: ["nice-guidance", "icer-value-assessment", "drug-price-transparency"], related: ["qol-pro", "financial-toxicity", "regulatory-agencies", "real-world-evidence", "eu-hta-regulation", "nice-methods", "cancer-drugs-fund", "innovative-medicines-fund", "amnog", "inflation-reduction-act", "medicare-ced", "france-early-access", "china-vbp-nrdl", "state-biomarker-testing-laws"], sections: ["drug-discovery"] }),
  t({ id: "crossover", name: "Crossover in trials", category: "Trials & regulation", aka: ["cross-over", "crossover-adjusted", "crossover adjustment", "adjusted for crossover", "permitted crossover", "crossover was permitted", "crossover rate", "post-progression therapy", "subsequent therapy", "subsequent treatment", "RPSFT", "rank-preserving structural failure time", "IPCW", "treatment switching", "unplanned crossover", "confounded by crossover"], tldr: "When patients in a trial's control arm are allowed to switch to the experimental drug after their cancer progresses. It is fair to patients but blurs the survival comparison, because the control group has now had the drug too.", summary: "Crossover is common in trials of drugs already approved elsewhere or clearly active (imatinib in GIST, osimertinib in FLAURA, 177Lu-PSMA in VISION and PSMAfore, where 84% of controls crossed over) and explains why such trials often show large progression-free survival gains but little or no overall survival difference. Statistical corrections (rank-preserving structural failure time, inverse probability of censoring weighting) estimate what survival would have been without crossover but rely on assumptions and are treated cautiously by regulators, who may still demand an OS trend. In regulatory debates, crossover cuts both ways: it can hide a true survival benefit or excuse its absence.", wikipedia: W("Crossover_study"), trials: ["vision", "psmafore", "codebreak-200", "therap", "claridhy"], related: ["os", "pfs", "surrogate-endpoint", "control-arm", "estimand", "trial-failure-modes", "hazard-ratio", "kaplan-meier-curve", "clinical-equipoise"], sections: ["drug-discovery"] }),
  t({ id: "non-inferiority", name: "Non-inferiority trial", category: "Trials & regulation", aka: ["non-inferiority", "noninferiority", "non-inferior", "noninferior", "non-inferiority margin", "non-inferiority trial", "non-inferiority design", "met non-inferiority", "superiority", "superiority trial", "superiority design", "equivalence", "equivalence trial", "non-inferiority designs", "non-inferiority margins", "non-inferiority trials"], tldr: "A trial designed to show a new treatment is not meaningfully worse than the standard, rather than better: used when the new option is shorter, cheaper, less toxic or easier (five radiotherapy fractions instead of 25, six months of trastuzumab instead of twelve).", summary: "The sponsor pre-specifies a non-inferiority margin (the largest loss of efficacy considered acceptable, e.g. a hazard ratio upper confidence limit below 1.2) and the trial succeeds if the confidence interval excludes that margin. Because a bad trial (poor adherence, wrong population) tends toward no difference, non-inferiority trials must be run rigorously and are analysed per-protocol as well as intention-to-treat. They underpin most de-escalation (hypofractionation, IDEA 3 vs 6 months FOLFOX, PERSEPHONE, segmentectomy vs lobectomy, SANO active surveillance) and biosimilar approvals. Choosing the margin is contentious: a 'non-inferior' result can still mean some patients are harmed.", wikipedia: W("Non-inferiority_trial"), trials: ["sano", "persephone", "fast-forward", "pace-b", "tailorx", "dynamic", "convert"], related: ["de-escalation", "hypofractionation", "intention-to-treat", "statistical-significance", "non-inferiority-margin", "randomised-trial", "stepped-wedge-design", "estimand", "trial-failure-modes"], sections: ["drug-discovery"] }),
  t({ id: "futility", trials: ["javelin-hn-100", "trilynx", "magnitude", "dream3r"], wikipedia: W("Interim_analysis"), name: "Futility analysis (stopped for futility)", category: "Trials & regulation", aka: ["stopped for futility", "stopped early for futility", "futility boundary", "futility analysis", "futility stopping", "discontinued for futility", "terminated for futility", "stopped early for efficacy", "stopped early", "early stopping", "stopping boundary", "data monitoring committee", "DMC", "IDMC", "DSMB", "independent data monitoring committee", "futility boundaries"], tldr: "A planned check partway through a trial to see whether the new treatment has any realistic chance of proving better; if not, the trial is stopped to spare patients and money. The opposite rule stops a trial early when benefit is overwhelming.", summary: "Independent data monitoring committees review unblinded interim data against pre-specified boundaries: futility boundaries (often a conditional power below 10-20%) end trials such as TrilynX (xevinapant) and a string of phase 3 immunotherapy combinations; efficacy boundaries (O'Brien-Fleming or Lan-DeMets alpha spending) allow early positive readouts, as in KEYNOTE-006 and CheckMate 067. Stopping early for efficacy can overestimate effect size and truncate safety and survival follow-up, while futility stops sacrifice the chance of a late benefit. Sponsors also stop trials for 'business reasons' or poor accrual, which is not the same as futility.", related: ["interim-analysis", "statistical-significance", "primary-endpoint", "accrual", "data-monitoring-committee", "group-sequential-design", "sample-size-re-estimation", "trial-failure-modes"], sections: ["drug-discovery"] }),
  t({ id: "interim-analysis", trials: ["adaura", "trilynx"], name: "Interim analysis, readout and data cut-off", category: "Trials & regulation", aka: ["interim analysis", "interim analyses", "first interim analysis", "second interim analysis", "prespecified interim", "final analysis", "final OS analysis", "primary analysis", "data cut-off", "data cutoff", "data cut", "readout", "read out", "reads out", "topline", "top-line", "topline results", "top-line data", "headline results", "updated analysis", "long-term follow-up", "extended follow-up", "5-year update", "results expected", "data expected"], tldr: "A trial's results are not one event but a series: pre-planned looks at the data (interim analyses) while it is still running, a data cut-off date that freezes the dataset for each look, a 'topline' announcement of the headline numbers, and a final analysis when enough events have happened.", summary: "Time-to-event trials are 'event-driven': analyses occur after a set number of progressions or deaths, so timing depends on how fast events accrue, and companies announce 'readouts' when those milestones arrive. Interim analyses use alpha-spending so that repeated looks do not inflate false positives; a positive interim for progression-free survival often comes years before the final overall survival analysis. Topline press releases precede peer-reviewed publication by months and may omit key details, which is why the site distinguishes press-release from published evidence. The data cut-off, not the publication date, is the date the numbers describe.", wikipedia: W("Interim_analysis"), related: ["futility", "primary-endpoint", "data-maturity", "statistical-significance", "group-sequential-design", "data-monitoring-committee", "sample-size-re-estimation", "trial-lifecycle"], sections: ["drug-discovery"] }),
  t({ id: "primary-endpoint", name: "Primary, secondary and co-primary endpoints", category: "Trials & regulation", aka: ["primary endpoint", "primary end point", "primary endpoints", "primary outcome", "secondary endpoint", "secondary endpoints", "key secondary", "key secondary endpoint", "co-primary", "co-primary endpoints", "dual primary", "dual primary endpoints", "composite endpoint", "exploratory endpoint", "endpoint", "endpoints", "met its primary endpoint", "met the primary endpoint", "missed its primary endpoint", "positive trial", "negative trial", "technically negative", "primary outcomes", "co-primary endpoint", "composite endpoints", "key secondaries"], tldr: "The primary endpoint is the single measurement a trial is designed and sized to test, declared in advance; if it is met, the trial is 'positive'. Secondary endpoints are additional measures that can support but not rescue a trial that missed its primary.", summary: "Common oncology primary endpoints are overall survival, progression-free survival (often by blinded central review), event-free or disease-free survival, objective response rate, and pathological complete response; dual or co-primary endpoints (PFS and OS) split the type I error between them with hierarchical testing. A trial that misses its primary but shows a survival trend is 'technically negative' (BILCAP, JAVELIN Ovarian) and regulators rarely approve on secondary endpoints alone. Endpoint choice shapes approval speed (surrogates are faster) and interpretation, and changing the primary endpoint mid-trial, or reporting a secondary as if it were primary, are recognised warning signs.", wikipedia: W("Clinical_endpoint"), related: ["surrogate-endpoint", "statistical-significance", "os", "pfs", "efs", "orr"], sections: ["drug-discovery"] }),
  t({ id: "intention-to-treat", name: "Intention-to-treat (ITT) and per-protocol analysis", category: "Trials & regulation", aka: ["ITT", "intention-to-treat", "intent-to-treat", "ITT population", "ITT analysis", "modified intention-to-treat", "mITT", "per-protocol", "per protocol", "per-protocol population", "as-treated", "evaluable population", "efficacy-evaluable", "response-evaluable", "safety population", "full analysis set", "analysis population", "randomised population"], tldr: "Analysing every patient in the group they were randomised to, whether or not they actually took the treatment. It preserves the fairness of randomisation and reflects what happens when a treatment is prescribed in real life; per-protocol analysis, by contrast, counts only those who complied.", summary: "ITT is the primary analysis for superiority trials because excluding non-compliers or early dropouts reintroduces bias. Per-protocol analyses matter for non-inferiority trials, where non-compliance can mask a real difference. 'Modified ITT' variants exclude patients who never received a dose or lacked a baseline measurement and should be pre-specified. 'Response-evaluable' populations in single-arm trials inflate response rates by dropping early progressors, and 'safety population' counts patients as treated. Trial and drug pages on this site report ITT results unless stated.", wikipedia: W("Intention-to-treat_analysis"), related: ["non-inferiority", "prespecified-vs-post-hoc", "double-blind", "control-arm", "estimand", "non-inferiority-margin", "trial-failure-modes", "randomised-trial"], sections: ["drug-discovery"], trials: ["persephone", "tailorx"] }),
  t({ id: "prespecified-vs-post-hoc", name: "Pre-specified vs post-hoc analysis", category: "Trials & regulation", aka: ["pre-specified", "prespecified", "pre-planned", "prespecified analysis", "pre-specified analysis", "post-hoc", "post hoc", "post-hoc analysis", "post-hoc subgroup", "retrospective analysis", "unplanned analysis", "exploratory", "exploratory analysis", "hypothesis-generating", "hypothesis generating", "nominal", "nominal P value", "nominally significant", "data dredging", "p-hacking", "statistical analysis plan", "protocol-specified", "pre-registered", "pre-registration", "preregistered", "registered report", "registered reports", "statistical analysis plans"], tldr: "Whether an analysis was planned and written down before the data were seen (pre-specified) or invented afterwards (post-hoc). Post-hoc findings, especially in subgroups, are prone to be chance and count as hypotheses for a new trial, not as evidence.", summary: "Trial protocols and statistical analysis plans, registered in advance (ClinicalTrials.gov, EU CTR), list the endpoints, populations and tests that will count; regulators approve on pre-specified analyses and treat post-hoc results as exploratory with 'nominal' P values. Post-hoc subgroup analyses have produced both misleading claims (retrospective PD-L1 cut-offs) and genuine discoveries later confirmed (KRAS wild-type for cetuximab). Pre-registration is standard in clinical trials and the site's ideas argue for extending it to animal studies and to 'silent trial' evaluations of AI, where the lack of pre-registration is a known source of false positives.", wikipedia: W("Preregistration_(science)"), related: ["subgroup-analysis", "statistical-significance", "primary-endpoint", "intention-to-treat", "trial-registration", "trial-protocol", "trial-failure-modes", "biomarker-stratified-design"], sections: ["drug-discovery"], trials: ["magnitude", "progesterone-preop-tmh", "mindact"] }),
  t({ id: "subgroup-analysis", name: "Subgroup analysis (forest plots)", category: "Trials & regulation", aka: ["subgroup", "subgroups", "subgroup analysis", "subgroup analyses", "pre-specified subgroup", "prespecified subgroup", "subgroup effect", "subgroup benefit", "forest plot", "forest plots", "interaction test", "test for interaction", "heterogeneity of effect", "consistent across subgroups", "benefit was consistent", "effect modification", "biomarker subgroup", "PD-L1 subgroup", "high-volume subgroup", "regional subgroup", "Asian subgroup", "Western subgroup", "subgroup effects"], tldr: "Splitting a trial's patients into groups (by age, sex, biomarker, region) to see whether the treatment worked the same in each. Shown as a forest plot. Genuine differences are rare and most striking subgroup results are noise, so they need confirmation.", summary: "Trials are powered for the whole population, so subgroups have wide confidence intervals and, with a dozen subgroups, one will look different by chance; the proper test is for interaction, not for significance within each subgroup. Regulators have nonetheless used subgroups to restrict labels (PD-L1 cut-offs in gastro-oesophageal cancer, IMpassion130's PD-L1-positive population) and to question generalisability (regional differences in STARGLO, ex-US benefit in IMbrave050). Biologically plausible, pre-specified subgroups with a stratified randomisation carry more weight; a post-hoc TP53 wild-type subgroup with no interaction test (selinexor in endometrial cancer) needed its own trial.", wikipedia: W("Subgroup_analysis"), related: ["prespecified-vs-post-hoc", "statistical-significance", "pd-l1-testing", "trial-failure-modes", "biomarker-stratified-design", "stratified-randomisation"], sections: ["drug-discovery"], trials: ["rxponder", "progesterone-preop-tmh", "magnitude"] }),
  t({ id: "statistical-significance", name: "Statistical significance (P values, alpha, multiplicity)", category: "Trials & regulation", aka: ["statistically significant", "statistical significance", "not statistically significant", "did not reach statistical significance", "P value", "p-value", "P<0.05", "P = 0.05", "one-sided", "two-sided", "alpha spending", "alpha allocation", "type I error", "multiplicity", "multiple comparisons", "hierarchical testing", "gatekeeping", "Bonferroni", "powered", "underpowered", "sample size", "statistical power", "80% power", "90% power", "numerically", "numerical improvement", "trend toward", "trend towards", "clinically meaningful", "clinical significance", "sample sizes"], tldr: "A result is 'statistically significant' when it would be unlikely (usually under 5%) to arise by chance if the treatment did nothing. It is a threshold, not a measure of benefit size: a tiny gain can pass it in a huge trial and a large one can miss it in a small trial, so ESMO and ASCO grade benefit separately.", summary: "Trials are sized ('powered') to detect a pre-specified effect with 80-90% probability at a 5% two-sided alpha; testing several endpoints or several interim looks would inflate false positives unless alpha is split (allocated) or spent sequentially, so hierarchical testing means a secondary endpoint cannot be claimed if a higher one failed. 'Numerically better', 'trend' and 'nominal P' are phrases for results that did not meet the pre-set bar. Clinical meaningfulness is separate: ASCO and ESMO scales (ESMO-MCBS) grade the size of benefit, and a significant 6-week PFS gain may not matter to patients. Confidence intervals convey both size and uncertainty and are preferred to bare P values.", wikipedia: W("Statistical_significance"), related: ["primary-endpoint", "prespecified-vs-post-hoc", "subgroup-analysis", "non-inferiority", "hazard-ratio", "group-sequential-design", "sample-size-re-estimation", "bayesian-trial-design", "trial-failure-modes", "p-value", "confidence-interval"], sections: ["drug-discovery"] }),
  t({ id: "double-blind", name: "Blinding (double-blind, open-label, placebo-controlled)", category: "Trials & regulation", aka: ["double-blind", "double blind", "double-blinded", "blinded", "open-label", "open label", "unblinded", "placebo-controlled", "placebo-controlled trial", "matching placebo", "single-blind", "investigator-blinded", "assessor-blinded", "blinded assessment", "blinded independent review", "unblinding"], tldr: "Whether patients and doctors know which treatment is being given. Double-blind: neither knows (a placebo hides it). Open-label: both do, unavoidable for surgery or radiotherapy but a source of bias when judging progression and symptoms.", summary: "Blinding protects subjective outcomes (progression on scans, symptom scores, decisions to stop or switch) from expectation bias. Many oncology trials are open-label because the comparators differ in route or schedule; they compensate with blinded independent central review of imaging and hard endpoints such as overall survival. Placebo-controlled designs are standard for maintenance and adjuvant trials (adding a pill or nothing). Unblinding at interim analysis, or effective unblinding through side effects (alopecia, rash), can compromise a trial, and open-label designs tend to show larger investigator-assessed PFS effects than blinded review.", wikipedia: W("Blinded_experiment"), related: ["bicr", "control-arm", "intention-to-treat", "single-arm", "stratified-randomisation", "clinical-equipoise", "placebo", "n-of-1-trial"], sections: ["drug-discovery"], trials: ["act-iv", "olanzapine-appetite-tmh", "keynote-564", "add-aspirin"] }),
  t({ id: "single-arm", wikipedia: W("Single-arm_study_design"), links: [{ label: "FDA guidance: clinical trial considerations to support accelerated approval of oncology therapeutics", url: "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/clinical-trial-considerations-support-accelerated-approval-oncology-therapeutics" }], name: "Single-arm trial", category: "Trials & regulation", aka: ["single-arm", "single arm", "single-arm trial", "single-arm phase 2", "single-arm study", "uncontrolled", "non-randomised", "nonrandomized", "non-randomized", "one-arm", "open-label single-arm", "basket cohort", "expansion cohort", "phase 2 cohort", "expansion cohorts", "single-arm studies", "single-arm trials"], tldr: "A trial where everyone gets the new drug and there is no comparison group; success is judged by the share of tumours that shrink and for how long. Fast and small, it underpinned accelerated approvals for larotrectinib, sotorasib, tarlatamab and most CAR-T products, but it cannot show that patients live longer.", summary: "Single-arm phase 2 trials with objective response rate and duration of response as endpoints supported accelerated approvals for a series of targeted drugs in rare or heavily pretreated populations (larotrectinib, sotorasib, tarlatamab, most CAR-T products) where randomisation was impractical or considered unethical. Their weaknesses are patient selection, lack of a comparator for time-to-event endpoints, and susceptibility to response-evaluable population definitions; the FDA increasingly asks for a randomised confirmatory trial to be under way at approval and has issued guidance on when single-arm data suffice. External or synthetic control arms are attempts to add a comparator after the fact.", related: ["orr", "duration-of-response-term", "external-control-arm", "accelerated-approval", "basket-umbrella-platform", "basket-trial", "trial-failure-modes", "clinical-equipoise", "surrogate-validation"], sections: ["drug-discovery"], trials: ["navigate", "l-mind", "roar-atc", "arrow-thyroid", "nmtrc003", "pathfinder-2"] }),
  t({ id: "external-control-arm", wikipedia: W("Synthetic_control_method"), links: [{ label: "FDA guidance: considerations for the design and conduct of externally controlled trials", url: "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/considerations-design-and-conduct-externally-controlled-trials-drug-and-biological-products" }], name: "External and synthetic control arms", category: "Trials & regulation", aka: ["external control", "external control arm", "external comparator", "synthetic control", "synthetic control arm", "historical control", "historical controls", "historical comparison", "real-world comparator", "real-world control", "natural history control", "matched cohort", "propensity-matched", "propensity score", "Bayesian borrowing", "dynamic borrowing", "hybrid control", "external control arms", "external controls", "synthetic controls"], tldr: "Instead of randomising patients to a control group, comparing a single-arm trial against patients treated in the past or recorded in registries, matched by propensity scores. Regulators accepted this for eflornithine in neuroblastoma and other rare cancers, but unmeasured differences between the groups, including changes in supportive care between eras, can masquerade as drug effects.", summary: "External controls draw on prior trials, electronic health records or registries (Flatiron, TriNetX) and use propensity matching or Bayesian dynamic borrowing to align populations; regulators have accepted them for eflornithine in neuroblastoma, several paediatric and rare-cancer approvals, and in the EU for some CAR-T comparisons. Weaknesses are unmeasured confounding, different eras of supportive care ('bias when standard of care changes between eras'), and differences in outcome assessment. FDA guidance (2023) sets expectations for data quality; they are best used to contextualise single-arm results and to design, not replace, randomised confirmatory trials.", technologies: ["oncology-real-world-data", "flatiron-health"], related: ["single-arm", "real-world-evidence", "control-arm", "accelerated-approval", "bayesian-trial-design", "trial-failure-modes", "registry-based-trial"], sections: ["drug-discovery"], trials: ["nmtrc003", "l-mind", "act-iv", "convert"] }),
  t({ id: "control-arm", name: "Control arm and comparator (investigator's choice)", category: "Trials & regulation", aka: ["control arm", "control group", "comparator", "comparator arm", "active comparator", "active control", "standard arm", "standard-of-care arm", "investigator's choice", "investigator choice", "physician's choice", "treatment of physician's choice", "TPC", "chemotherapy of choice", "versus chemotherapy", "vs chemotherapy", "experimental arm", "treatment arm", "head-to-head", "head to head", "control arms", "comparators"], tldr: "The group in a randomised trial that gets the existing standard treatment, against which the new drug is judged. Whether the control is the true current standard, an outdated one, or a menu of options chosen by each doctor ('investigator's choice') changes how much a positive result means.", summary: "The comparator should be the best available treatment at the time; trials using a weaker control (chemotherapy alone when chemo-immunotherapy was standard, or a suboptimal dose) draw regulatory and ODAC criticism and may not translate into practice. Investigator's or physician's choice from a list of chemotherapies is common in later-line trials (ASCENT, DESTINY-Breast04, TROPiCS-02) and is realistic but heterogeneous. Head-to-head trials of two new agents are rare and mostly sponsored by challengers (MARIPOSA vs osimertinib, HARMONi-2 ivonescimab vs pembrolizumab). Placebo or observation controls are used where no active standard exists, as in adjuvant and maintenance settings.", wikipedia: W("Scientific_control"), trials: ["destiny-breast04", "keynote-024-189", "act-iv", "convert"], related: ["standard-of-care", "double-blind", "backbone-add-on", "non-inferiority", "trial-failure-modes", "external-control-arm", "clinical-equipoise", "pragmatic-trial"], sections: ["drug-discovery"] }),
  t({ id: "dose-limiting-toxicity", links: [{ label: "NCI Dictionary of Cancer Terms: dose-limiting", url: "https://www.cancer.gov/publications/dictionaries/cancer-terms/def/dose-limiting" }], name: "Dose-limiting toxicity (DLT)", category: "Trials & regulation", aka: ["DLT", "DLTs", "dose-limiting", "dose limiting toxicity", "dose-limiting toxicities", "DLT period", "DLT window", "no DLTs", "DLT rate"], tldr: "A side effect in an early trial severe enough (usually grade 3 or worse, or forcing a long treatment pause) that the dose cannot safely go higher. Counting DLTs at each dose level is how phase 1 trials find the maximum tolerated dose.", summary: "Protocols define DLTs in advance (typically grade ≥3 non-haematological toxicity, prolonged grade 4 neutropenia, febrile neutropenia, or inability to deliver a set fraction of planned dose) and observe them over a fixed window, usually the first cycle. If a pre-set proportion of patients at a dose (2 of 6 in a 3+3 design) have DLTs, that dose exceeds tolerance. The one-cycle window misses cumulative and late toxicities (neuropathy, ILD, ocular effects), a recognised limitation for continuously dosed targeted drugs and ADCs that Project Optimus and time-to-event designs aim to correct.", technologies: ["project-optimus"], related: ["mtd", "rp2d", "dose-escalation-design", "ctcae-grading"], sections: ["drug-discovery"] }),
  t({ id: "mtd", name: "Maximum tolerated dose (MTD)", category: "Trials & regulation", aka: ["MTD", "maximum tolerated dose", "maximally tolerated dose", "MTD not reached", "MTD was not reached", "below the MTD", "dose optimisation", "dose optimization", "optimal dose", "optimal biological dose", "OBD", "randomised dose comparison", "dose-response"], tldr: "The highest dose of a drug at which about a third of patients or fewer have dose-limiting side effects, the traditional target of phase 1 trials. For chemotherapy more was better; targeted drugs and antibodies often saturate their target far below it, which is why the FDA's Project Optimus now asks for two doses to be compared.", summary: "Classic dose-finding assumed efficacy and toxicity rise together, so the MTD was the dose at which about a third of patients had dose-limiting toxicity. Many targeted drugs and biologics saturate their target well below the MTD ('MTD not reached'), and approving at the MTD has led to poor tolerability, dose reductions in half of patients and post-marketing dose changes (sotorasib 960 vs 240 mg, belantamab, cabozantinib). Project Optimus (FDA, 2022) now expects randomised comparison of at least two doses before pivotal trials to identify an optimal rather than maximal dose, and the recommended phase 2 dose is chosen on exposure-response, not toxicity alone.", wikipedia: W("Maximum_tolerated_dose"), technologies: ["project-optimus"], related: ["dose-limiting-toxicity", "rp2d", "dose-escalation-design", "therapeutic-index", "pharmacokinetics"], sections: ["drug-discovery"] }),
  t({ id: "rp2d", name: "Recommended phase 2 dose (RP2D)", category: "Trials & regulation", aka: ["RP2D", "recommended phase 2 dose", "recommended phase II dose", "recommended dose", "recommended dose for expansion", "dose selected", "selected dose", "the dose taken forward", "registrational dose"], tldr: "The dose and schedule chosen at the end of a phase 1 trial to test in larger trials, based on safety, blood levels and early signs of activity. It is often, but no longer always, the maximum tolerated dose.", summary: "Choosing the RP2D integrates dose-limiting toxicities, pharmacokinetics (whether exposure plateaus), pharmacodynamic target engagement, and responses across dose levels; expansion cohorts then test it in specific tumour types. Because the RP2D usually becomes the approved dose, errors are expensive: too high causes discontinuations and dose reductions in practice, too low wastes efficacy. Under Project Optimus, sponsors are expected to compare two or more doses in randomised cohorts before selecting the RP2D, and to report the proportion of patients needing reductions. Dose changes after approval (via label updates) are increasingly common.", wikipedia: W("Phase_I_clinical_trial"), technologies: ["project-optimus"], related: ["mtd", "dose-limiting-toxicity", "dose-escalation-design", "pharmacokinetics"], sections: ["drug-discovery"] }),
  t({ id: "dose-escalation-design", technologies: ["project-optimus"], name: "Dose-escalation designs (3+3, BOIN, dose-expansion)", category: "Trials & regulation", aka: ["3+3", "3 + 3", "3+3 design", "rule-based design", "BOIN", "Bayesian optimal interval", "CRM", "continual reassessment method", "mTPI", "TITE-CRM", "model-based dose finding", "model-based design", "dose-finding", "dose finding", "dose-finding study", "dose escalation cohort", "dose escalation", "dose-escalation", "dose escalation phase", "dose-expansion", "dose expansion", "expansion phase", "accelerated titration", "backfill cohort", "dose level", "dose levels", "cohort of 3", "backfill cohorts", "model-based designs"], tldr: "How a phase 1 trial climbs from a tiny starting dose to a useful one: the old 3+3 design treats three patients at a time and moves up if none has serious toxicity; newer statistical designs (BOIN, CRM) use all the data to pick doses more accurately with fewer patients on ineffective levels.", summary: "The 3+3 design (still the most used) is simple but imprecise, treats a large share of patients at sub-therapeutic doses and identifies the MTD poorly; model-based designs such as the continual reassessment method and the Bayesian optimal interval design estimate the toxicity curve continuously and are recommended by the FDA and methodologists, with time-to-event versions handling late toxicities. After escalation, dose-expansion cohorts (often 20-40 patients per tumour type) gather efficacy signals and may be randomised between two doses under Project Optimus. Accelerated titration and single-patient cohorts speed the early low-dose levels, and backfill cohorts add patients at lower doses to inform dose optimisation.", wikipedia: W("Phase_I_clinical_trial#Dose_escalation"), related: ["dose-limiting-toxicity", "mtd", "rp2d", "first-in-human", "project-optimus", "bayesian-trial-design", "seamless-adaptive", "trial-phases"], trials: ["rejoice-ovarian01", "low-dose-nivolumab-tmh"], sections: ["drug-discovery"] }),
  t({ id: "first-in-human", name: "First-in-human (FIH) trial", category: "Trials & regulation", aka: ["first-in-human", "first in human", "FIH", "first-in-human trial", "first-in-human study", "first-in-class", "first in class", "first-in-patient", "phase 0", "microdose", "investigational new drug", "IND-enabling", "IND clearance", "clinical entry", "entered the clinic", "clinical-stage", "preclinical", "pre-clinical", "preclinical-stage", "first-in-human studies", "first-in-human trials"], tldr: "The first time a new drug is given to people, after animal and laboratory testing and clearance of an Investigational New Drug application. In oncology these are phase 1 trials in patients with advanced cancer who have exhausted standard options, starting at a fraction of the dose predicted to be safe; modern designs run straight through to registrational cohorts.", summary: "An Investigational New Drug application (or EU clinical trial authorisation) summarising toxicology, manufacturing and the protocol must be cleared before dosing. Starting doses derive from animal no-adverse-effect levels or, for immune agonists after the TGN1412 disaster, from minimal anticipated biological effect levels. First-in-class drugs (a new mechanism) carry more uncertainty than follow-on agents. Modern FIH trials are seamless: escalation, expansion and sometimes registrational cohorts in one protocol, so a first-in-human study can lead directly to accelerated approval (sotorasib, tarlatamab). 'Entering the clinic' marks a programme's transition from preclinical to clinical stage.", wikipedia: W("Phase_I_clinical_trial"), related: ["dose-escalation-design", "mtd", "seamless-adaptive", "window-of-opportunity-trial", "trial-lifecycle", "trial-phases", "ethics-review", "informed-consent"], sections: ["drug-discovery"] }),
  t({ id: "window-of-opportunity-trial", name: "Window-of-opportunity trial", category: "Trials & regulation", aka: ["window-of-opportunity", "window of opportunity", "window trial", "window trials", "window study", "presurgical trial", "pre-surgical", "pre-operative window", "biomarker window", "pharmacodynamic study", "paired biopsies", "serial biopsies", "on-treatment biopsy", "pre- and post-treatment biopsies", "on-treatment biopsies", "window studies", "window-of-opportunity trials"], tldr: "Giving a new drug for a few weeks in the gap between diagnosis and scheduled surgery, then examining the removed tumour to see what the drug did to it. Patients lose nothing (surgery proceeds as planned) and researchers get a direct look at the drug's biological effect.", summary: "Window trials compare the diagnostic biopsy with the resected tumour after 2-6 weeks of drug, measuring proliferation (Ki-67 in breast cancer, the basis of POETIC and other endocrine studies), immune infiltration after checkpoint inhibitors, target engagement and early resistance signals; they use tens of patients rather than hundreds and can rank candidate drugs or combinations quickly. They cannot measure survival benefit and short exposure may miss slow effects, and delaying surgery must be justified. Neoadjuvant trials with pathological response endpoints are the longer, efficacy-oriented relative; the site's ideas include window designs for ctDNA, neural and microbiome interventions.", wikipedia: W("Neoadjuvant_therapy"), related: ["neoadjuvant-adjuvant", "pcr", "first-in-human", "core-needle-biopsy", "seamless-adaptive", "trial-lifecycle", "biomarker-stratified-design"], sections: ["drug-discovery"] }),
  t({ id: "pivotal-trial", name: "Pivotal (registrational) trial", category: "Trials & regulation", aka: ["pivotal", "pivotal trial", "pivotal study", "pivotal phase 3", "registrational", "registrational trial", "registrational study", "registration trial", "registration-enabling", "registration-directed", "approval-enabling", "pivotal cohort", "registrational cohort", "supported approval", "basis of approval", "approval was based on", "registration trials", "registrational trials"], tldr: "The trial (usually a randomised phase 3, sometimes a large phase 2) whose results are submitted to regulators as the main evidence for approval. When a company calls a trial 'registrational' it is signalling that this is the one that decides.", summary: "Regulators traditionally required two adequate and well-controlled trials, but in oncology one pivotal trial with confirmatory supporting evidence is the norm. Pivotal trials define the approved population, dose and comparator, so their design is negotiated with the FDA in advance (end-of-phase-2 meetings, special protocol assessment). Phase 2 single-arm cohorts serve as pivotal for accelerated approval in rare or refractory diseases. A 'registration-directed' or 'registration-enabling' phase 2 signals a company's intent to file on it. Pivotal trials are the units this site's evidence and trial pages are built around.", wikipedia: W("Phases_of_clinical_research"), related: ["primary-endpoint", "bla-nda", "single-arm", "confirmatory-trial", "trial-lifecycle", "trial-registration", "group-sequential-design"], sections: ["drug-discovery"], trials: ["keynote-522", "adaura", "navigate"] }),
  t({ id: "seamless-adaptive", name: "Seamless, adaptive and Bayesian trial designs", category: "Trials & regulation", aka: ["seamless", "seamless phase 2/3", "seamless phase 1/2", "phase 1/2", "phase 2/3", "adaptive design", "adaptive trial", "adaptive randomisation", "response-adaptive randomisation", "Bayesian", "Bayesian adaptive", "Bayesian design", "I-SPY 2", "I-SPY", "master protocol", "sample size re-estimation", "adaptive enrichment", "biomarker-selected", "biomarker-enriched", "all-comers", "unselected", "unselected population", "adaptive designs", "master protocols", "all-comer", "unselected populations"], tldr: "Trial designs that change as data come in: merging phases so successful drugs move forward without pause, dropping arms or doses that are not working, adding new ones, and shifting randomisation toward what seems to help. Faster and more efficient, but they need careful statistics to stay honest.", summary: "Seamless phase 2/3 trials expand a successful cohort into a registrational one under a single protocol; phase 1/2 trials do the same from dose-finding to expansion. Adaptive platform trials such as I-SPY 2 (neoadjuvant breast cancer, Bayesian response-adaptive randomisation with 'graduation' of drugs likely to succeed in phase 3), STAMPEDE (multi-arm multi-stage in prostate cancer) and GBM AGILE test many drugs against a shared control. Enrichment designs restrict or shift enrolment to biomarker-positive patients when they respond better ('biomarker-selected' versus 'all-comers'). Pre-specified adaptation rules, alpha control and a firewall between the data monitoring committee and the sponsor are required for regulatory acceptance.", wikipedia: W("Adaptive_design_(medicine)"), links: [{ label: "Wikipedia", url: W("Adaptive_design_(medicine)") }, { label: "FDA guidance: adaptive designs for clinical trials of drugs and biologics", url: "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/adaptive-design-clinical-trials-drugs-and-biologics-guidance-industry" }], trials: ["stampede", "nrg-hn002-hn005", "rejoice-ovarian01", "myelomatch", "pediatric-match", "aspen-06"], technologies: ["digital-twins-trials", "n-of-1-platforms"], related: ["basket-umbrella-platform", "interim-analysis", "first-in-human", "basket-trial", "umbrella-trial", "response-adaptive-randomisation", "bayesian-trial-design", "sample-size-re-estimation", "smart-design", "biomarker-stratified-design", "pragmatic-trial", "registry-based-trial", "decentralised-trial", "n-of-1-trial", "cluster-randomised-trial", "stepped-wedge-design", "non-inferiority-margin", "stratified-randomisation", "group-sequential-design", "dose-escalation-design", "data-monitoring-committee", "estimand", "trial-failure-modes", "window-of-opportunity-trial", "master-protocol"], sections: ["drug-discovery"] }),
  t({ id: "accrual", name: "Accrual and enrolment", category: "Trials & regulation", aka: ["accrual", "accrued", "accruing", "enrolment", "enrollment", "enrolling", "enrolled", "fully enrolled", "completed enrolment", "enrolment completed", "recruitment", "recruiting", "recruited", "actively recruiting", "slow accrual", "poor accrual", "closed to accrual", "open to accrual", "target enrolment", "trial participation", "participation rate", "eligibility criteria", "inclusion criteria", "exclusion criteria", "eligible patients"], tldr: "How many patients a trial has signed up, and how fast. Slow accrual is the commonest reason trials take years longer than planned or close without an answer; only about 5-8% of adult cancer patients ever join a trial.", summary: "Accrual depends on the number of eligible patients (narrow eligibility criteria excluding older patients, brain metastases, poor performance status or prior therapies), site activation speed, competing trials, patient awareness and travel burden, with large inequities by race, geography and income. Remedies include broader eligibility (ASCO/Friends of Cancer Research recommendations), decentralised and hybrid trials, community oncology site networks, AI trial matching, and paying for travel. Rare cancers and paediatric trials often need international consortia and a decade to accrue; 'closed to accrual' means the target number was reached and follow-up continues.", wikipedia: W("Clinical_trial#Participants"), technologies: ["ai-trial-matching", "decentralised-clinical-trials", "community-oncology-networks"], related: ["futility", "performance-status", "cancer-health-disparities", "rare-cancers", "informed-consent", "decentralised-trial", "pragmatic-trial", "ethics-review", "trial-lifecycle", "stratified-randomisation"], sections: ["drug-discovery"], trials: ["add-aspirin", "pediatric-match"] }),
  t({ id: "complete-response-term", name: "Complete response (CR) and partial response (PR)", category: "Trials & regulation", aka: ["complete response", "complete responses", "complete remission", "complete remissions", "CR rate", "CRi", "CR/CRi", "complete response rate", "stringent complete response", "sCR", "partial response", "partial responses", "partial remission", "PR rate", "very good partial response", "VGPR", "stable disease", "best response", "best overall response", "deep response", "deep responses", "complete response rates"], tldr: "A complete response means every measurable trace of the cancer has disappeared on scans or in the marrow; a partial response means it has shrunk by at least 30% (RECIST) but is still there. Neither is the same as cure: microscopic disease can remain.", summary: "Solid tumour responses are defined by RECIST 1.1 (complete: all target lesions gone and nodes <10 mm; partial: ≥30% decrease in summed diameters; progressive: ≥20% increase or new lesions; stable: neither); lymphoma uses Lugano and PET; leukaemia uses marrow blast count and count recovery (CR, CRi for incomplete recovery); myeloma uses IMWG (stringent CR, VGPR, PR). Complete responses are the strongest single-arm signal and, when durable, drive accelerated approvals; the proportion of complete responders and the depth of response (MRD, ctDNA clearance) increasingly predict long-term outcome. In neoadjuvant settings pathological complete response is judged on the resected specimen, and clinical complete response guides organ preservation.", wikipedia: W("Response_Evaluation_Criteria_in_Solid_Tumors"), related: ["orr", "recist", "pcr", "duration-of-response-term", "umrd", "progressive-disease"], sections: ["drug-discovery"] }),
  t({ id: "progressive-disease", name: "Progressive disease and radiographic progression", category: "Trials & regulation", aka: ["progressive disease", "progression", "disease progression", "radiographic progression", "radiological progression", "clinical progression", "progressed", "progressing", "on progression", "at progression", "after progression", "post-progression", "upon progression", "time of progression", "pseudoprogression", "pseudo-progression", "hyperprogression", "iRECIST", "iUPD", "iCPD", "PSA progression", "biochemical progression", "molecular progression", "ctDNA progression", "oligoprogressive"], tldr: "The point at which a cancer is judged to be growing again despite treatment, usually a 20% increase on scans or a new lesion (RECIST). It ends progression-free survival, usually triggers a change of treatment, and defines 'lines' of therapy.", summary: "Progression is assessed on scheduled scans (every 6-12 weeks in trials), so recorded progression dates depend on imaging frequency; blinded central review reduces investigator bias. Immunotherapy introduced pseudoprogression (apparent growth from immune infiltration before shrinkage), handled by iRECIST's 'unconfirmed progression' category, and hyperprogression (rapid acceleration in a minority). Molecular progression (rising ctDNA or PSA) precedes radiographic progression by months and is now used to trigger treatment switches in trials (SERENA-6). Oligoprogression, growth at one or a few sites while the rest is controlled, is treated with local therapy while continuing the systemic drug.", wikipedia: W("Response_Evaluation_Criteria_in_Solid_Tumors"), trials: ["serena-6"], related: ["pfs", "recist", "complete-response-term", "first-line", "oligometastatic", "ctdna"], sections: ["drug-discovery"] }),
  t({ id: "duration-of-response-term", name: "Duration of response (DoR) and disease control rate (DCR)", category: "Trials & regulation", aka: ["DoR", "DOR", "mDoR", "duration of response", "median duration of response", "durable response", "durable responses", "ongoing response", "ongoing responses", "responses ongoing", "DCR", "disease control rate", "disease control", "clinical benefit rate", "CBR", "clinical benefit", "tumour control", "time to response", "TTR", "median time to response", "rapid responses", "onset of response"], tldr: "Duration of response measures how long a tumour that shrank stays shrunk before growing again; disease control rate adds patients whose cancer stayed stable to those who responded. Together with response rate they describe a drug's activity in trials without a comparison group.", summary: "Median DoR is required alongside objective response rate for accelerated approvals because a high response rate that lasts two months is worth little; durable responses (ongoing at 12 months or more) are the hallmark of immunotherapy and of oncogene-targeted drugs in addicted tumours. Disease control rate (CR + PR + stable disease) is a weaker measure because stable disease may reflect slow natural history rather than drug effect, and clinical benefit rate (usually stable disease ≥6 months) is used in endocrine therapy trials of breast cancer where stability is meaningful. Time to response matters clinically for symptomatic patients and is fast for chemotherapy and kinase inhibitors, slower for immunotherapy.", wikipedia: W("Response_Evaluation_Criteria_in_Solid_Tumors"), related: ["orr", "complete-response-term", "single-arm", "accelerated-approval", "pfs"], sections: ["drug-discovery"] }),
  t({ id: "ttp", name: "Time to progression (TTP) and time to next treatment (TTNT)", category: "Trials & regulation", aka: ["TTP", "time to progression", "time-to-progression", "TTNT", "time to next treatment", "time to next therapy", "time to next intervention", "time to subsequent therapy", "time to treatment failure", "TTF", "time to first subsequent therapy", "TFST", "PFS2", "progression-free survival 2", "time to castration resistance", "time to CRPC", "time to deterioration", "time to symptomatic progression", "time to first skeletal event", "metastasis-free survival", "MFS", "distant metastasis-free survival", "DMFS", "rPFS", "radiographic progression-free survival", "biochemical recurrence-free survival"], tldr: "A family of 'time to X' endpoints: how long until the cancer grows (TTP, which unlike PFS ignores deaths), until the patient needs another treatment (TTNT), until it spreads (metastasis-free survival), or until symptoms worsen. Each captures something patients care about that survival alone misses.", summary: "Time to progression counts only progression events, censoring deaths, so it is used where competing mortality is high but is less favoured than PFS by regulators. Time to next treatment and PFS2 (progression on the next line) reflect whether a benefit persists beyond the trial drug and whether early use compromises later options. Metastasis-free survival is a validated surrogate for overall survival in localised prostate cancer and the endpoint of several approvals in non-metastatic castration-resistant disease; radiographic PFS is standard in prostate trials because PSA changes alone are unreliable. Time to deterioration of quality of life is a patient-reported time-to-event endpoint increasingly demanded by regulators and HTA bodies.", wikipedia: W("Progression-free_survival"), related: ["pfs", "os", "efs", "castration-resistance", "qol-pro"], sections: ["drug-discovery"] }),
  t({ id: "landmark-survival", name: "Landmark and milestone survival (5-year survival, median follow-up)", category: "Trials & regulation", aka: ["landmark analysis", "milestone survival", "milestone analysis", "5-year survival", "five-year survival", "5-year OS", "5-year PFS", "5-year survival rate", "10-year survival", "2-year survival", "3-year survival", "1-year survival", "survival rate", "survival rates", "median follow-up", "median follow up", "long-term survival", "long-term survivors", "tail of the curve", "Kaplan-Meier", "Kaplan–Meier", "survival curve", "survival curves", "curves separate", "curves cross", "restricted mean survival time", "RMST", "long-term survivor"], tldr: "The percentage of patients alive (or progression-free) at a fixed time point such as 2, 5 or 10 years, read off a Kaplan-Meier survival curve. With immunotherapy the 'tail of the curve', the fraction still alive years later, often matters more than the median.", summary: "Kaplan-Meier curves show the proportion of patients event-free over time; the median is the point where the curve crosses 50%, and landmark rates are read at fixed times. Medians can mislead when curves plateau (a durable tail after checkpoint inhibitors or CAR-T) or cross (delayed immunotherapy benefit), so milestone rates and restricted mean survival time supplement hazard ratios. Landmark analyses also compare outcomes from a fixed time conditional on status at that time (e.g. survival by MRD status at 12 months), avoiding immortal-time bias. Median follow-up indicates how mature the data are; 5-year rates need at least 5 years of follow-up in a reasonable number of patients to be reliable.", wikipedia: W("Kaplan%E2%80%93Meier_estimator"), related: ["os", "pfs", "hazard-ratio", "data-maturity", "interim-analysis", "kaplan-meier-curve", "absolute-benefit"], sections: ["drug-discovery"], trials: ["checkmate-067", "keynote-024-189"] }),
  t({ id: "data-maturity", name: "Data maturity (immature vs mature survival data)", category: "Trials & regulation", aka: ["OS immature", "immature OS", "immature data", "immature survival data", "overall survival data are immature", "OS data immature", "mature OS", "mature survival", "event-driven", "number of events", "information fraction", "censored", "censoring", "censored at", "OS trend", "OS not yet reached", "not reached", "not estimable", "median not reached", "median OS not reached"], tldr: "Survival results are 'immature' when too few patients have died (or progressed) for the comparison to be reliable, so medians are 'not reached' and confidence intervals are wide. Mature data come with time and events; early positive looks can fade or strengthen.", summary: "Trials pre-specify the number of events needed for each analysis (the information fraction at an interim); with fewer events the hazard ratio is unstable and the median cannot be estimated. Regulators accept immature OS if PFS is positive and there is no detriment, but require the final analysis as a post-marketing commitment; ADAURA and KEYNOTE-522 were approved on DFS/EFS with OS immature, and both later matured positively, whereas other trials' early OS trends vanished. 'Not reached' medians in the experimental arm are a favourable sign but not a result. Censoring marks patients still event-free at the cut-off, and heavy early censoring (dropouts, loss to follow-up) can bias curves.", wikipedia: W("Censoring_(statistics)"), trials: ["adaura", "keynote-522"], related: ["interim-analysis", "landmark-survival", "os", "hazard-ratio", "primary-endpoint", "kaplan-meier-curve", "sample-size-re-estimation"], sections: ["drug-discovery"] }),
  t({ id: "qol-pro", name: "Quality of life and patient-reported outcomes (QoL, PRO)", category: "Trials & regulation", aka: ["QoL", "QOL", "quality of life", "quality-of-life", "health-related quality of life", "HRQoL", "HRQL", "PRO", "PROs", "patient-reported outcome", "patient-reported outcomes", "patient-reported", "patient reported", "PRO-CTCAE", "EORTC QLQ-C30", "QLQ-C30", "FACT-G", "EQ-5D", "symptom burden", "symptom scores", "functional status", "time to deterioration", "TTD", "global health status", "tolerability endpoints", "patient experience", "financial toxicity questionnaire", "symptom score"], tldr: "Measures of how patients themselves feel and function during treatment (pain, fatigue, nausea, daily activities), collected by questionnaire rather than by the doctor. Regulators and payers now expect them alongside survival, and clinician grading is known to under-report symptoms.", summary: "Standard instruments include EORTC QLQ-C30 and disease modules, FACT scales, EQ-5D for health economics and PRO-CTCAE for symptomatic adverse events; endpoints are mean change, time to deterioration and proportion improved. PROs revealed that clinician-graded toxicity misses much of what patients experience, showed that some 'well-tolerated' drugs are not, and supported approvals and HTA decisions where survival gains were modest. Weekly electronic PRO symptom monitoring during chemotherapy improved survival in a randomised trial (Basch 2017) and is now guideline-recommended. Missing data (sicker patients stop filling forms) is the main analytic problem; FDA core PRO guidance (2021-24) standardises collection.", wikipedia: W("Patient-reported_outcome"), links: [{ label: "Wikipedia", url: W("Patient-reported_outcome") }, { label: "FDA guidance: patient-reported outcome measures in medical product development", url: "https://www.fda.gov/regulatory-information/search-fda-guidance-documents/patient-reported-outcome-measures-use-medical-product-development-support-labeling-claims" }], technologies: ["epro-symptom-monitoring", "remote-patient-monitoring"], related: ["ctcae-grading", "hta", "ttp", "financial-toxicity", "quality-adjusted-survival", "decentralised-trial", "n-of-1-trial", "absolute-benefit"], sections: ["supportive-care", "drug-discovery"], trials: ["checkmate-9er", "cctg-ce6", "quartz", "mars-2", "therap"] }),

  // ---- Side effects ----
  t({ id: "ctcae-grading", name: "CTCAE toxicity grading (grade 3-4 adverse events)", category: "Side effects", aka: ["CTCAE", "Common Terminology Criteria for Adverse Events", "grade 3-4", "grade 3–4", "grade ≥3", "grade 3 or higher", "grade 3", "grade 4", "grade 5", "grade 1-2", "grade 2", "high-grade toxicity", "severe adverse events", "adverse event", "adverse events", "serious adverse event", "serious adverse events", "SAE", "SAEs", "treatment-related adverse events", "TRAE", "TRAEs", "TEAE", "TEAEs", "treatment-emergent", "treatment-related death", "treatment-related deaths", "toxic death", "safety signal", "tolerability profile", "safety signals"], tldr: "The standard 1-to-5 scale doctors use to grade every side effect in a trial: 1 mild, 2 moderate, 3 severe or needing hospital care, 4 life-threatening, 5 death. 'Grade 3-4 events in 40% of patients' is the usual headline safety figure.", summary: "The NCI Common Terminology Criteria for Adverse Events (now v5.0) defines each toxicity by grade (neutropenia by neutrophil count, diarrhoea by stool frequency, neuropathy by function), allowing comparison across trials. Reports distinguish all-cause adverse events, treatment-related (attributed by the investigator), serious (hospitalisation or worse) and treatment-emergent, and often quote grade ≥3 rates and discontinuations. Limitations: grading is done by clinicians, who under-report symptoms compared with patient-reported PRO-CTCAE; chronic low-grade toxicity of long-term pills is poorly captured by grade alone; and different drugs' grade 3 events are not equally burdensome (asymptomatic lab abnormalities versus disabling neuropathy).", wikipedia: W("Common_Terminology_Criteria_for_Adverse_Events"), related: ["qol-pro", "dose-limiting-toxicity", "dose-modification", "irae"], sections: ["supportive-care"] }),
  t({ id: "febrile-neutropenia", name: "Febrile neutropenia", category: "Side effects", aka: ["neutropenic fever", "neutropenic sepsis", "febrile neutropaenia", "FN rate", "neutropenic infection", "infection during neutropenia"], tldr: "Fever in a patient whose infection-fighting white cells have been wiped out by chemotherapy. It is a medical emergency: without immune cells, an ordinary infection can become fatal in hours, so antibiotics are started immediately.", summary: "Defined as temperature ≥38.3°C (or ≥38.0°C sustained) with neutrophils <0.5 × 10⁹/L, it occurs in 10-20% of patients on standard chemotherapy regimens (higher with docetaxel-based, dose-dense and induction chemotherapy), carries 5-10% mortality and is a leading cause of unplanned admission. Management is empirical broad-spectrum antibiotics within an hour, risk-scored (MASCC) to allow oral outpatient treatment for low-risk cases. Prevention with G-CSF (filgrastim, pegfilgrastim) is recommended when a regimen's risk exceeds 20%, and febrile neutropenia is a standard dose-limiting toxicity and reason for dose reduction.", wikipedia: W("Febrile_neutropenia"), technologies: ["g-csf-growth-factors"], related: ["neutropenia", "dose-limiting-toxicity", "dose-modification", "cytopenias"], sections: ["supportive-care"] }),
  t({ id: "neutropenia", name: "Neutropenia", category: "Side effects", aka: ["neutropenic", "neutropaenia", "low neutrophils", "neutrophil count", "absolute neutrophil count", "ANC", "grade 4 neutropenia", "grade 3-4 neutropenia", "prolonged neutropenia", "nadir", "count nadir", "leukopenia", "leucopenia", "white cell count", "agranulocytosis"], tldr: "A shortage of neutrophils, the white blood cells that fight bacteria, caused by chemotherapy hitting the bone marrow. It usually bottoms out (the nadir) 7-14 days after each cycle and recovers before the next; while low, infection risk is high.", summary: "The commonest dose-limiting toxicity of cytotoxic chemotherapy and of several targeted drugs (CDK4/6 inhibitors, PARP inhibitors, sacituzumab govitecan) and cell therapies. Graded by absolute neutrophil count (grade 3 <1.0, grade 4 <0.5 × 10⁹/L); severity and duration determine infection risk and febrile neutropenia. Managed by dose delays and reductions, prophylactic G-CSF, and for some drugs (palbociclib) simply tolerated because it is uncomplicated. Trilaciclib protects marrow during chemotherapy in small-cell lung cancer. Prolonged cytopenias after CAR-T (ICAHT) and after lymphodepletion are distinct in mechanism and can last months.", wikipedia: W("Neutropenia"), technologies: ["g-csf-growth-factors"], related: ["febrile-neutropenia", "cytopenias", "thrombocytopenia", "dose-modification"], sections: ["supportive-care"] }),
  t({ id: "thrombocytopenia", name: "Thrombocytopenia", category: "Side effects", aka: ["thrombocytopaenia", "low platelets", "platelet count", "platelet transfusion", "bleeding risk", "grade 3-4 thrombocytopenia", "immune thrombocytopenia", "ITP", "thrombopoietin receptor agonist", "platelet transfusions"], tldr: "Too few platelets, the blood cells that form clots, caused by chemotherapy or by the cancer in the marrow. Mild cases cause bruising; severe cases (under 10-20 × 10⁹/L) risk serious bleeding and need platelet transfusions.", summary: "Common with carboplatin, gemcitabine, temozolomide, lurbinectedin, PARP inhibitors (niraparib especially), radioligand therapies and in leukaemia and myeloma; it limits dose more often than neutropenia for some regimens because no growth factor is routinely used (romiplostim and avatrombopag are being trialled). Grade 4 is <25 × 10⁹/L. It also complicates anticoagulation for cancer-associated thrombosis and procedures such as biopsies and central line placement. Cirrhosis with portal hypertension causes chronic thrombocytopenia that constrains liver cancer treatment, and immune thrombocytopenia is an immune-related adverse event of checkpoint inhibitors.", wikipedia: W("Thrombocytopenia"), technologies: ["transfusion-support"], related: ["cytopenias", "neutropenia", "anaemia", "antiangiogenic-toxicities"], sections: ["supportive-care"] }),
  t({ id: "anaemia", name: "Anaemia", category: "Side effects", aka: ["anemia", "anaemic", "anemic", "low haemoglobin", "low hemoglobin", "haemoglobin", "hemoglobin", "transfusion-dependent", "transfusion dependence", "transfusion independence", "red cell transfusion", "erythropoiesis-stimulating agent", "ESA", "ESAs", "iron deficiency", "erythropoiesis-stimulating agents"], tldr: "A shortage of red blood cells or haemoglobin, causing tiredness and breathlessness. In cancer it comes from the disease itself (marrow infiltration, bleeding, inflammation), from chemotherapy suppressing the marrow, and from some targeted drugs.", summary: "Present in 30-90% of patients depending on cancer and treatment; a defining feature of myeloma, MDS and leukaemia, and the dose-limiting toxicity of PARP inhibitors (olaparib, talazoparib) and of some ADCs and radioligands. Managed by treating the cause, iron replacement, red cell transfusion (with restrictive thresholds) and, cautiously, erythropoiesis-stimulating agents, which raise thrombosis risk and were linked to worse outcomes when used to high targets. Transfusion independence is an endpoint in MDS trials (luspatercept, imetelstat). Fatigue from anaemia is one of the most common and under-treated symptoms in oncology.", wikipedia: W("Anemia"), technologies: ["transfusion-support"], drugs: ["luspatercept", "imetelstat"], related: ["cytopenias", "thrombocytopenia", "mds"], sections: ["supportive-care"] }),
  t({ id: "cytopenias", name: "Cytopenias and myelosuppression", category: "Side effects", aka: ["cytopenia", "cytopenias", "myelosuppression", "myelosuppressive", "bone marrow suppression", "marrow suppression", "marrow toxicity", "haematological toxicity", "hematological toxicity", "haematologic toxicity", "hematologic toxicity", "pancytopenia", "bicytopenia", "lymphopenia", "lymphocytopenia", "prolonged cytopenias", "late cytopenias", "ICAHT", "immune effector cell-associated haematotoxicity", "count recovery", "blood counts", "full blood count", "complete blood count", "CBC"], tldr: "The umbrella term for low blood counts of any kind (white cells, red cells, platelets) when treatment suppresses the bone marrow. Most chemotherapy causes it temporarily; radioligands, CAR-T and some pills cause longer-lasting versions.", summary: "Myelosuppression is the shared toxicity of cytotoxic chemotherapy, conditioning regimens, lymphodepletion, radioligand therapy (177Lu-PSMA, PRRT) and a range of targeted agents, graded per lineage by CTCAE; pancytopenia means all three lineages are low. Blood counts before each cycle gate treatment, and delays and dose reductions are the standard responses. After CAR-T, prolonged and biphasic cytopenias (ICAHT) affect a third of patients and drive infection deaths months after infusion; lymphopenia is a marker of poorer immunotherapy outcomes. Therapy-related MDS is the late, permanent form of marrow injury.", wikipedia: W("Myelosuppression"), related: ["neutropenia", "thrombocytopenia", "anaemia", "mds"], sections: ["supportive-care"] }),
  t({ id: "mucositis", name: "Mucositis and stomatitis", category: "Side effects", aka: ["oral mucositis", "stomatitis", "mouth sores", "mouth ulcers", "oesophagitis", "esophagitis", "radiation oesophagitis", "mucosal toxicity", "mucosal damage", "gastrointestinal toxicity", "GI toxicity", "dexamethasone mouthwash"], tldr: "Painful inflammation and ulcers of the mouth and gut lining, because chemotherapy and radiotherapy hit the fast-dividing cells that renew it. It affects most patients on head and neck chemoradiation or transplant conditioning, can make eating impossible, and is the usual reason those patients need feeding tubes and opioid pain relief.", summary: "Severe oral mucositis affects most patients receiving head and neck chemoradiation and high-dose conditioning for transplant, and a minority on 5-FU, methotrexate and taxanes; everolimus and other mTOR inhibitors cause a distinct stomatitis prevented by dexamethasone mouthwash (SWISH). Oesophagitis follows thoracic radiotherapy. Management is analgesia (often opioids), oral care, palifermin in transplant, photobiomodulation, and nutritional support; mucositis prolongs hospital stays, causes dose reductions and increases infection through the damaged barrier. It is the classic example of on-target toxicity to normal proliferating tissue.", wikipedia: W("Mucositis"), related: ["chemoradiation", "conditioning-regimen", "feeding-tube", "dysphagia"], sections: ["supportive-care"], technologies: ["photobiomodulation-mucositis"] }),
  t({ id: "hand-foot-syndrome", name: "Hand-foot syndrome and hand-foot skin reaction", category: "Side effects", aka: ["hand-foot", "hand-foot syndrome", "hand foot syndrome", "hand-foot skin reaction", "HFSR", "HFS", "palmar-plantar erythrodysesthesia", "PPE", "palmar-plantar", "plantar-palmar"], tldr: "Redness, peeling, pain and cracking of the palms and soles caused by certain chemotherapy pills and by kinase inhibitors that block blood vessel growth. Rarely dangerous but can stop patients walking or using their hands.", summary: "Hand-foot syndrome from capecitabine, 5-FU infusion and liposomal doxorubicin is a diffuse painful erythema; hand-foot skin reaction from VEGFR multikinase inhibitors (sorafenib, regorafenib, cabozantinib, lenvatinib) is more localised hyperkeratotic callus over pressure points. Both are dose-dependent, managed by dose interruption and reduction, urea creams, and avoiding friction and heat; celecoxib and pyridoxine have weak evidence. It is one of the most common reasons for dose reduction of oral therapies and a leading contributor to quality-of-life loss on long-term TKIs.", wikipedia: W("Chemotherapy-induced_acral_erythema"), drugs: ["sorafenib", "regorafenib", "cabozantinib", "lenvatinib"], related: ["rash-skin-toxicity", "dose-modification", "tki-term"], sections: ["supportive-care"] }),
  t({ id: "peripheral-neuropathy", name: "Peripheral neuropathy (chemotherapy-induced)", category: "Side effects", aka: ["neuropathy", "peripheral neuropathy", "chemotherapy-induced peripheral neuropathy", "CIPN", "sensory neuropathy", "motor neuropathy", "neuropathic", "numbness", "tingling", "paraesthesia", "paresthesia", "cold-induced neuropathy", "cumulative neuropathy", "neurotoxicity", "neurotoxic", "ototoxicity", "hearing loss", "tinnitus", "neuropathies"], tldr: "Nerve damage from chemotherapy that causes numbness, tingling and pain in the hands and feet, and sometimes weakness or hearing loss. It builds up with each dose, can be permanent, and is the main reason oxaliplatin, taxanes and vincristine have to be stopped or reduced.", summary: "Oxaliplatin (acute cold-triggered and chronic cumulative), paclitaxel, docetaxel, vincristine, bortezomib, brentuximab vedotin and other MMAE ADCs, and cisplatin (which also damages hearing, especially in children, prevented by sodium thiosulfate) are the main culprits. There is no proven preventive drug; duloxetine helps painful neuropathy, and dose reduction or stopping is the only reliable measure, which is why 3 rather than 6 months of adjuvant oxaliplatin (IDEA) was so consequential. Neuropathy is graded by function (grade 2 limits instrumental activities, grade 3 self-care) and often reported by patients as more severe than by clinicians. Cisplatin eligibility in bladder cancer includes absence of neuropathy and hearing loss.", wikipedia: W("Chemotherapy-induced_peripheral_neuropathy"), drugs: ["oxaliplatin", "paclitaxel", "docetaxel", "vincristine", "bortezomib", "brentuximab-vedotin", "sodium-thiosulfate"], related: ["taxane", "folfox-family", "dose-modification", "late-effects"], sections: ["supportive-care"] }),
  t({ id: "cardiotoxicity", name: "Cardiotoxicity (LVEF decline, cardiomyopathy)", category: "Side effects", aka: ["cardiac toxicity", "cardiotoxic", "cardiomyopathy", "heart failure", "LVEF", "left ventricular ejection fraction", "ejection fraction", "LVEF decline", "asymptomatic LVEF decline", "echocardiography", "echocardiogram", "MUGA", "cardiac monitoring", "cardiac surveillance", "cardioprotection", "cardioprotective", "anthracycline cardiotoxicity", "cardiovascular toxicity", "cardiovascular events", "arterial hypertension", "arrhythmia", "atrial fibrillation"], tldr: "Heart damage from cancer treatment: anthracyclines weaken the heart muscle permanently in a dose-related way, trastuzumab does so reversibly, and some kinase inhibitors raise blood pressure or disturb rhythm. Heart function (LVEF) is monitored by ultrasound during treatment.", summary: "Anthracycline cardiomyopathy risk rises steeply above 400-450 mg/m² doxorubicin and with radiotherapy or age; trastuzumab causes asymptomatic LVEF declines in 5-10% and heart failure in 1-4%, more after anthracyclines, monitored every 3 months and usually reversible on stopping. VEGF inhibitors cause hypertension and rarely heart failure; ibrutinib causes atrial fibrillation; immune checkpoint inhibitors cause rare fulminant myocarditis; androgen deprivation and aromatase inhibitors raise cardiovascular risk over years. Cardio-oncology clinics manage risk with ACE inhibitors, beta-blockers, statins and dexrazoxane; anthracycline-free regimens and non-anthracycline ADC payloads reduce exposure. Childhood cancer survivors carry lifelong cardiac risk.", wikipedia: W("Cardiotoxicity"), technologies: ["cardio-oncology"], drugs: ["doxorubicin", "trastuzumab", "ibrutinib"], related: ["anthracycline", "myocarditis", "late-effects", "qt-prolongation"], sections: ["supportive-care"] }),
  t({ id: "hepatotoxicity", name: "Hepatotoxicity (liver enzyme elevation)", category: "Side effects", aka: ["liver toxicity", "hepatic toxicity", "hepatotoxic", "transaminitis", "transaminase elevation", "elevated transaminases", "raised liver enzymes", "liver enzymes", "ALT/AST", "liver function tests", "LFTs", "drug-induced liver injury", "DILI", "immune hepatitis", "immune-mediated hepatitis", "hepatitis B reactivation", "HBV reactivation", "veno-occlusive disease", "sinusoidal obstruction syndrome", "VOD/SOS", "hyperbilirubinaemia", "liver enzyme"], tldr: "Liver injury from a drug, usually detected as a rise in liver enzymes (ALT, AST) on routine blood tests before symptoms appear. Most cases settle with a pause or dose reduction; a few, especially with checkpoint inhibitors or in already damaged livers, are serious.", summary: "Kinase inhibitors (pazopanib, lapatinib, several ALK and ROS1 inhibitors), immune checkpoint inhibitors (immune hepatitis, treated with steroids), ADCs with calicheamicin payloads (inotuzumab, gemtuzumab: veno-occlusive disease especially around transplant), methotrexate, and CAR-T all cause hepatotoxicity, graded by ALT/AST and bilirubin multiples of normal. Pre-existing cirrhosis narrows the margin in liver cancer, hepatitis B can reactivate under rituximab and chemotherapy (screen and give antivirals), and Hy's law (ALT >3× with bilirubin >2×) predicts severe injury and can end drug development. Liver function tests are checked before every cycle of most regimens.", wikipedia: W("Hepatotoxicity"), related: ["cirrhosis", "irae", "dose-modification", "child-pugh"], sections: ["supportive-care"] }),
  t({ id: "immune-colitis", name: "Immune-mediated colitis and diarrhoea", category: "Side effects", aka: ["colitis", "immune colitis", "immune-mediated colitis", "checkpoint colitis", "ipilimumab colitis", "diarrhoea", "diarrhea", "grade 3 diarrhoea", "severe diarrhoea", "enterocolitis"], tldr: "Inflammation of the bowel caused by immunotherapy releasing the immune system against the gut lining, producing diarrhoea that can be severe. It is the commonest serious side effect of CTLA-4 antibodies and is treated with steroids and, if needed, infliximab.", summary: "Colitis occurs in 10-15% of patients on ipilimumab (higher with nivolumab combination) and 1-3% on PD-1 antibodies alone, typically 6-8 weeks in; grade 3 diarrhoea (≥7 stools/day over baseline) requires holding treatment and high-dose steroids, with infliximab or vedolizumab for refractory cases, and perforation is the feared complication. Faecal microbiota transplantation has reversed refractory colitis in case series, and the gut microbiome influences both colitis risk and response. Chemotherapy and kinase inhibitors (irinotecan, capecitabine, neratinib, abemaciclib, EGFR inhibitors) cause diarrhoea by different mechanisms managed with loperamide and dose adjustment, and diarrhoea is a leading reason for stopping oral targeted drugs.", wikipedia: W("Colitis"), technologies: ["checkpoint-inhibitor", "microbiome-modulation-io"], drugs: ["ipilimumab", "irinotecan"], related: ["irae", "immune-endocrinopathy", "dose-modification"], sections: ["supportive-care", "immunotherapy"] }),
  t({ id: "immune-endocrinopathy", wikipedia: W("Hypophysitis"), links: [{ label: "Haanen et al., Management of toxicities from immunotherapy: ESMO Clinical Practice Guideline (Annals of Oncology 2022)", url: "https://doi.org/10.1016/j.annonc.2022.10.001" }], name: "Immune-related endocrinopathies (thyroiditis, hypophysitis)", category: "Side effects", aka: ["endocrinopathy", "endocrinopathies", "hypothyroidism", "hyperthyroidism", "thyroiditis", "thyroid dysfunction", "hypophysitis", "adrenal insufficiency", "immune-related diabetes", "type 1 diabetes", "thyroid function tests", "TSH monitoring", "hormone replacement"], tldr: "Immunotherapy can attack hormone-producing glands: most often the thyroid (usually ending in an under-active thyroid needing lifelong tablets), and less often the pituitary (hypophysitis) or adrenal glands, which can be life-threatening if missed.", summary: "Thyroid dysfunction affects 10-20% of patients on PD-1/PD-L1 antibodies, usually a transient thyroiditis followed by permanent hypothyroidism managed with levothyroxine without stopping immunotherapy; hypophysitis is characteristic of ipilimumab (5-10%) and causes headache, fatigue and low cortisol requiring permanent hydrocortisone; fulminant type 1 diabetes and primary adrenal insufficiency are rare but acute. Unlike most immune-related adverse events, endocrinopathies are generally irreversible because the gland is destroyed, but they are also compatible with continued treatment, and some data link them to better response. Kinase inhibitors (lenvatinib, sunitinib) cause hypothyroidism by a different mechanism.", technologies: ["checkpoint-inhibitor"], drugs: ["ipilimumab", "pembrolizumab", "nivolumab"], related: ["irae", "immune-colitis", "myocarditis"], sections: ["supportive-care", "immunotherapy"] }),
  t({ id: "myocarditis", name: "Immune-related myocarditis", category: "Side effects", aka: ["immune myocarditis", "checkpoint myocarditis", "myocarditis", "immune-mediated myocarditis", "troponin", "troponin monitoring", "myositis", "myasthenia", "myasthenia gravis", "immune-related myositis"], tldr: "Rare but frequently fatal inflammation of the heart muscle triggered by checkpoint inhibitors, usually in the first two months. It often comes with muscle and nerve-muscle inflammation, and needs urgent high-dose steroids.", summary: "Occurs in about 1% of patients (more with combination CTLA-4 plus PD-1 and with some other combinations) with mortality of 25-50%; presents with chest pain, breathlessness, arrhythmia or heart block, often alongside myositis and myasthenia (the 'triad'). Diagnosis rests on troponin, ECG, echocardiography, cardiac MRI and biopsy; treatment is immediate methylprednisolone with abatacept, mycophenolate or ruxolitinib for steroid-refractory cases, and the drug is permanently stopped. Baseline and early troponin monitoring is debated. Distinct from anthracycline and trastuzumab cardiomyopathy, which damage the heart without inflammation.", wikipedia: W("Myocarditis"), technologies: ["checkpoint-inhibitor", "cardio-oncology"], related: ["irae", "cardiotoxicity", "immune-endocrinopathy"], sections: ["supportive-care", "immunotherapy"] }),
  t({ id: "ocular-toxicity", name: "Ocular toxicity (keratopathy, blurred vision)", category: "Side effects", aka: ["ocular toxicity", "ocular toxicities", "eye toxicity", "ocular adverse events", "ocular events", "keratopathy", "corneal toxicity", "corneal events", "microcyst-like epithelial changes", "MECs", "blurred vision", "dry eye", "dry eyes", "ophthalmology", "eye examinations", "ophthalmic examination", "uveitis", "serous retinopathy", "retinopathy", "conjunctivitis"], tldr: "Eye problems from cancer drugs: blurred vision and corneal damage from certain ADCs (belantamab, tisotumab), retinal fluid from MEK inhibitors, and inflammation from immunotherapy. Usually reversible with dose holds, but they need regular eye examinations.", summary: "ADCs with MMAF or other non-cleavable tubulin payloads (belantamab mafodotin) and tissue factor ADCs (tisotumab vedotin) cause keratopathy in most patients because payload reaches the corneal epithelium, requiring ophthalmology checks before each dose, lubricating drops and dose modification, and prompting the REMS programme and dose reductions that followed belantamab's re-approval. MEK inhibitors cause transient serous retinopathy, EGFR inhibitors cause conjunctivitis and trichomegaly, and checkpoint inhibitors cause uveitis. Ocular toxicity has ended some ADC programmes and is a key design consideration for payload and linker choice.", wikipedia: W("Keratopathy"), technologies: ["adc"], drugs: ["belantamab-mafodotin"], related: ["dose-modification", "therapeutic-index", "tubulin-inhibitor-payloads"], sections: ["supportive-care", "adcs"] }),
  t({ id: "qt-prolongation", name: "QT prolongation", category: "Side effects", aka: ["QTc prolongation", "QTc", "QT interval", "prolonged QT", "QT", "ECG monitoring", "electrocardiogram", "hERG", "hERG inhibition", "torsades", "torsades de pointes", "ventricular arrhythmia", "electrolyte monitoring"], tldr: "A change on the heart's electrical trace, caused by some drugs blocking a potassium channel (hERG), that in rare cases sets off a dangerous rhythm. Drugs that do this need ECG checks and care with other medicines and low potassium or magnesium.", summary: "Off-target hERG inhibition is common among kinase inhibitors (vandetanib, nilotinib, ribociclib, osimertinib, mobocertinib, selpercatinib, ivosidenib) and other drugs (arsenic trioxide, ondansetron, methadone); labels require baseline and periodic ECGs and electrolyte correction, and combining QT-prolonging drugs is avoided. Clinically important arrhythmia is rare, but QT prolongation has delayed or narrowed approvals and is screened for in early drug development (thorough QT studies). A QTc above 500 ms or an increase over 60 ms usually triggers dose interruption.", wikipedia: W("Long_QT_syndrome#Drug-induced"), drugs: ["nilotinib", "ribociclib", "osimertinib", "arsenic-trioxide"], related: ["cardiotoxicity", "therapeutic-index", "tki-term"], sections: ["supportive-care"] }),
  t({ id: "hyperglycaemia", name: "Hyperglycaemia (PI3K/AKT inhibitor class effect)", category: "Side effects", aka: ["hyperglycemia", "high blood sugar", "raised glucose", "glucose monitoring", "PI3K inhibitor toxicity", "PI3Kα inhibitor", "metformin prophylaxis", "SGLT2 inhibitor", "ketogenic diet with PI3K inhibitors"], tldr: "High blood sugar as a side effect of drugs that block the PI3K/AKT pathway, because the same pathway carries insulin's signal in muscle and liver. It is the main reason these otherwise effective breast cancer drugs are hard to give.", summary: "Alpelisib causes hyperglycaemia in about 65% of patients (grade 3-4 in a third), capivasertib and everolimus less often; steroids and some immunotherapy-induced diabetes also raise glucose. Management is screening for pre-diabetes, metformin (often prophylactic), SGLT2 inhibitors, dietary carbohydrate restriction and dose modification; mutant-selective PI3Kα inhibitors (inavolisib, RLY-2608) were designed to reduce it. Hyperglycaemia is a textbook on-target toxicity: the pathway that drives PIK3CA-mutant cancers is the same one insulin uses, and the ketogenic-diet-plus-PI3K-inhibitor hypothesis arose directly from this observation.", wikipedia: W("Hyperglycemia"), drugs: ["alpelisib", "capivasertib"], related: ["therapeutic-index", "dose-modification", "endocrine-resistance"], sections: ["supportive-care", "targeted-therapy"] }),
  t({ id: "rash-skin-toxicity", name: "Rash and skin toxicity (acneiform rash, paronychia)", category: "Side effects", aka: ["rash", "skin rash", "skin toxicity", "skin toxicities", "dermatological toxicity", "dermatologic toxicity", "cutaneous toxicity", "acneiform rash", "acneiform", "papulopustular rash", "EGFR rash", "paronychia", "nail changes", "xerosis", "dry skin", "photosensitivity", "maculopapular rash", "Stevens-Johnson", "SJS", "vitiligo", "hyperpigmentation"], tldr: "Skin reactions from cancer drugs, ranging from the acne-like rash that nearly everyone on an EGFR inhibitor gets (a sign the drug is working) to painful nail-fold infections, itching, and rare severe blistering reactions.", summary: "EGFR inhibitors (cetuximab, panitumumab, osimertinib, amivantamab) cause acneiform rash, paronychia and dry skin in most patients through on-target blockade in skin, managed with prophylactic doxycycline, topical steroids and moisturisers; the rash correlates with response. MEK and BRAF inhibitors, ADCs (enfortumab vedotin can cause severe, occasionally fatal skin reactions), immunotherapy (maculopapular rash, pruritus, vitiligo in melanoma, which predicts response), and chemotherapy (hand-foot syndrome, hyperpigmentation) all have characteristic patterns. Severe cutaneous adverse reactions (Stevens-Johnson syndrome, toxic epidermal necrolysis) are rare but require permanent discontinuation. Skin toxicity is a leading cause of dose reduction and of visible distress for patients.", wikipedia: W("Drug_eruption"), drugs: ["cetuximab", "osimertinib", "enfortumab-vedotin"], related: ["hand-foot-syndrome", "irae", "dose-modification", "tki-term"], sections: ["supportive-care"] }),
  t({ id: "extravasation-infusion-reaction", name: "Infusion reactions, hypersensitivity and extravasation", category: "Side effects", aka: ["infusion reaction", "infusion reactions", "infusion-related reaction", "infusion-related reactions", "IRR", "IRRs", "hypersensitivity", "hypersensitivity reaction", "allergic reaction", "anaphylaxis", "anaphylactic", "premedication", "premedicated", "pre-medication", "antihistamine premedication", "extravasation", "vesicant", "vesicants", "infusion site reaction", "injection site reaction", "subcutaneous formulation", "flu-like symptoms", "hypersensitivity reactions", "subcutaneous formulations"], tldr: "Reactions around the moment a drug is given: chills, fever or breathlessness from antibodies (infusion reactions), true allergy (hypersensitivity, rarely anaphylaxis), and leakage of a damaging drug into tissue around the vein (extravasation).", summary: "Infusion reactions are common with first doses of rituximab, cetuximab, daratumumab and other antibodies (cytokine release from target cells) and with taxanes and platinum (hypersensitivity, rising with cumulative carboplatin exposure); premedication with antihistamines, steroids and paracetamol, slow initial rates and subcutaneous formulations (rituximab, daratumumab, atezolizumab, pembrolizumab) reduce them. Anaphylaxis to asparaginase or platinum leads to switching agents or desensitisation. Extravasation of vesicants (anthracyclines, vinca alkaloids) causes tissue necrosis and is why central venous access is used; dexrazoxane treats anthracycline extravasation. These are distinct from cytokine release syndrome after T-cell engagers, though mechanistically related.", wikipedia: W("Infusion-related_reaction"), drugs: ["rituximab", "cetuximab", "daratumumab", "carboplatin"], related: ["central-venous-access", "crs", "anthracycline"], sections: ["supportive-care"] }),
  t({ id: "vte", name: "Venous thromboembolism (VTE)", category: "Side effects", aka: ["VTE", "thromboembolism", "venous thromboembolism", "thromboembolic events", "thromboembolic", "thrombosis", "thrombotic events", "deep vein thrombosis", "DVT", "pulmonary embolism", "blood clots", "blood clot", "anticoagulation", "anticoagulant", "thromboprophylaxis", "low-molecular-weight heparin", "LMWH", "DOAC", "DOACs", "Khorana score", "arterial thromboembolism", "anticoagulants"], tldr: "Blood clots in the leg veins or lungs. Cancer makes blood clot more easily and some treatments (IMiDs, anti-VEGF drugs, hormone therapy, central lines, surgery) add risk; clots are the second commonest cause of death in cancer patients after the cancer itself.", summary: "Cancer-associated thrombosis affects 5-20% of patients, highest in pancreatic, gastric, brain and lung cancer and myeloma; the Khorana score identifies outpatients who benefit from prophylactic apixaban or rivaroxaban (AVERT, CASSINI). Treatment is a DOAC or low-molecular-weight heparin for at least 6 months, balancing bleeding risk in gastrointestinal and urothelial tumours. Lenalidomide and thalidomide mandate aspirin or anticoagulant prophylaxis; bevacizumab and other VEGF inhibitors raise arterial events; tamoxifen and erythropoiesis-stimulating agents raise venous ones. Incidental pulmonary emboli on staging CTs are common and are treated as symptomatic ones.", wikipedia: W("Venous_thrombosis"), technologies: ["cancer-associated-thrombosis"], drugs: ["lenalidomide", "thalidomide", "bevacizumab", "tamoxifen"], related: ["imid", "antiangiogenic-toxicities", "central-venous-access"], sections: ["supportive-care"] }),
  t({ id: "antiangiogenic-toxicities", name: "Anti-VEGF class toxicities (hypertension, proteinuria, bleeding, perforation)", category: "Side effects", aka: ["proteinuria", "bleeding", "haemorrhage", "hemorrhage", "bleeding events", "bleeding risk", "haemoptysis", "epistaxis", "gastrointestinal perforation", "GI perforation", "perforation", "bowel perforation", "fistula", "fistula formation", "wound healing", "wound-healing complications", "impaired wound healing", "wound dehiscence", "reversible posterior leukoencephalopathy", "PRES", "VEGF inhibitor toxicity", "anti-VEGF toxicity", "hold 28 days around surgery"], tldr: "The shared side effects of drugs that block blood vessel growth (bevacizumab, ramucirumab and VEGFR kinase inhibitors): high blood pressure, protein leaking into the urine, nosebleeds and more serious bleeding, slow wound healing, and rarely holes in the bowel.", summary: "VEGF maintains normal vessel integrity and healing, so blocking it raises blood pressure in 20-40% (treated with standard antihypertensives, a possible marker of efficacy), causes proteinuria, and impairs wound healing (bevacizumab is held for 4-6 weeks around surgery). Bleeding ranges from epistaxis to fatal haemoptysis in squamous lung cancer with central cavitating tumours (excluded from bevacizumab trials) and variceal bleeding in liver cancer (endoscopy required before atezolizumab-bevacizumab). Gastrointestinal perforation and fistula (1-2%, more after radiotherapy or with bowel involvement) and arterial thromboembolic events are the most serious. Multikinase inhibitors add hand-foot skin reaction, fatigue, diarrhoea and hypothyroidism.", wikipedia: W("Bevacizumab#Adverse_effects"), technologies: ["antiangiogenic"], drugs: ["bevacizumab", "lenvatinib", "cabozantinib", "regorafenib"], related: ["vte", "hand-foot-syndrome", "tki-term", "surgical-morbidity"], sections: ["supportive-care"] }),
  t({ id: "secondary-malignancy", links: [{ label: "NCI Dictionary of Cancer Terms: secondary cancer", url: "https://www.cancer.gov/publications/dictionaries/cancer-terms/def/secondary-cancer" }], name: "Secondary malignancy (therapy-related cancer)", category: "Side effects", aka: ["secondary malignancies", "second malignancy", "second malignancies", "second cancer", "second cancers", "second primary", "second primary cancer", "second primary cancers", "second primary malignancy", "therapy-related", "treatment-related cancer", "treatment-induced cancer", "therapy-related AML", "therapy-related MDS", "therapy-related myeloid neoplasm", "t-MN", "t-AML", "radiation-induced", "radiation-induced cancer", "radiation-induced sarcoma", "secondary leukaemia", "secondary leukemia", "secondary AML", "T-cell lymphoma after CAR-T", "T-cell malignancies", "second primaries", "second primary malignancies", "T-cell malignancy", "therapy-related myeloid neoplasms"], tldr: "A new, different cancer caused by the treatment of the first one: leukaemia after alkylating chemotherapy or PARP inhibitors, solid tumours in irradiated tissue decades later, and rarely T-cell lymphoma after CAR-T. Rare per patient, but it matters most for those cured young.", summary: "Therapy-related myeloid neoplasms (MDS/AML) follow alkylators (5-7 years, often with TP53 mutations and complex karyotype), topoisomerase II inhibitors (2-3 years, MLL rearrangements), PARP inhibitors (about 1-2% in maintenance trials), lenalidomide maintenance and radiotherapy, and carry a poor prognosis; they often arise from pre-existing clonal haematopoiesis. Radiation-induced solid cancers (breast cancer after Hodgkin mantle radiotherapy, sarcomas, thyroid cancer after childhood radiation) appear 10-30 years later and drive the search for less radiation in curable young patients. Secondary T-cell malignancies after CAR-T (FDA boxed warning, 2024) are rare and mostly unrelated to insertional mutagenesis. Second primary cancers also reflect shared risk factors (tobacco in head and neck and lung cancer) and genetic syndromes.", related: ["mds", "clonal-haematopoiesis", "late-effects", "alkylating-agent", "anthracycline"], sections: ["supportive-care"] }),
  t({ id: "late-effects", name: "Late effects and survivorship toxicity", category: "Side effects", aka: ["late effects", "late toxicity", "late toxicities", "long-term toxicity", "long-term toxicities", "long-term side effects", "long-term effects", "chronic toxicity", "cumulative toxicity", "cumulative dose", "lifetime dose", "infertility", "gonadotoxicity", "premature ovarian insufficiency", "premature menopause", "growth impairment", "neurocognitive effects", "neurocognitive decline", "cognitive impairment", "chemo brain", "lymphoedema", "lymphedema", "xerostomia", "dry mouth", "osteoporosis", "bone loss", "osteonecrosis", "osteonecrosis of the jaw", "sexual dysfunction", "childhood cancer survivors", "childhood cancer survivor", "cumulative doses"], tldr: "Health problems appearing months or decades after treatment ends: heart damage, infertility, second cancers, lymphoedema, dry mouth, memory problems, weak bones. They matter most for children and young adults, who live longest with them.", summary: "Two-thirds of childhood cancer survivors have at least one chronic condition by age 50 (Childhood Cancer Survivor Study), which is why paediatric oncology has spent decades reducing radiation and anthracycline doses without losing cure rates. Adult examples include lymphoedema (reduced by sentinel node biopsy), xerostomia and dysphagia after head and neck radiotherapy (reduced by IMRT), infertility (addressed by oncofertility and GnRH protection), premature menopause and osteoporosis from endocrine therapy, neuropathy, cardiomyopathy, and neurocognitive effects. Survivorship care plans, risk-based screening (breast MRI after chest radiotherapy, echocardiography after anthracyclines) and exercise programmes address them, and trials increasingly report late toxicity as a co-primary concern in de-escalation.", wikipedia: W("Late_effect"), technologies: ["survivorship-care-plan", "fertility-preservation", "exercise-oncology"], related: ["secondary-malignancy", "cardiotoxicity", "peripheral-neuropathy", "de-escalation", "aya-oncology"], sections: ["supportive-care"] }),
  t({ id: "hypogammaglobulinaemia", name: "Hypogammaglobulinaemia and infection risk after B-cell therapies", category: "Side effects", aka: ["hypogammaglobulinemia", "low immunoglobulins", "low IgG", "immunoglobulin replacement", "IVIG", "intravenous immunoglobulin", "B-cell depletion", "B-cell aplasia", "infection risk", "opportunistic infections", "infection prophylaxis", "antimicrobial prophylaxis", "antiviral prophylaxis", "PJP prophylaxis", "Pneumocystis prophylaxis", "CMV reactivation", "cytomegalovirus", "vaccine responses", "revaccination"], tldr: "A shortage of antibodies because treatment has wiped out the B cells or plasma cells that make them, as CD19 CAR-T, CD20 antibodies and BCMA therapies deliberately do. It leaves patients prone to infections, sometimes for years, and is managed with immunoglobulin infusions.", summary: "Infections are the leading cause of non-relapse death after BCMA and CD19 CAR-T and bispecific antibodies; hypogammaglobulinaemia, prolonged cytopenias, T-cell dysfunction and steroids for CRS all contribute. Management includes IVIG for recurrent infections or IgG <4 g/L, prophylaxis against Pneumocystis, herpes viruses and sometimes fungi, CMV monitoring, and vaccination (non-live; responses are blunted, so household contacts should be vaccinated). Rituximab causes hypogammaglobulinaemia after repeated courses and hepatitis B reactivation. Persistent B-cell aplasia after CD19 CAR-T is also a useful sign that the CAR-T cells remain active.", wikipedia: W("Hypogammaglobulinemia"), technologies: ["car-t", "t-cell-engager"], drugs: ["rituximab", "teclistamab"], related: ["t-cell-exhaustion-term", "cytopenias", "crs", "febrile-neutropenia"], sections: ["supportive-care", "cell-therapy"] }),
  t({ id: "dose-modification", name: "Dose reduction, interruption and discontinuation", category: "Side effects", aka: ["dose reduction", "dose reductions", "dose-reduction", "dose reduced", "dose interruption", "dose interruptions", "dose delay", "dose delays", "treatment delay", "dose hold", "hold treatment", "dose modification", "dose modifications", "dose adjustment", "dose adjustments", "discontinuation", "discontinuations", "discontinued", "treatment discontinuation", "discontinuation rate", "discontinuation due to adverse events", "permanent discontinuation", "stopped treatment", "treatment cessation", "relative dose intensity", "RDI", "adherence", "non-adherence", "compliance", "real-world dosing", "starting dose", "dose holds", "treatment delays"], tldr: "The everyday tools for living with side effects: pausing a drug until a problem settles (interruption), restarting at a lower dose (reduction), or stopping it for good (discontinuation). Between 30 and 60% of patients on oral targeted drugs need a reduction, so these rates are the clearest test of whether a dose was set right.", summary: "Labels specify dose modification rules by toxicity grade; in practice 30-60% of patients on oral targeted drugs need a reduction, and discontinuation for adverse events (typically 5-20% in trials, higher in real-world older populations) directly reduces benefit. Relative dose intensity below 85% is associated with worse outcomes for curative chemotherapy, whereas for targeted drugs lower doses often work as well (Project Optimus's rationale). Adherence to daily pills over years (endocrine therapy, imatinib) is a hidden determinant of efficacy. Trials report dose reductions and discontinuations alongside grade 3-4 events as the clearest summary of tolerability.", wikipedia: W("Dose_(biochemistry)"), technologies: ["project-optimus"], related: ["ctcae-grading", "mtd", "therapeutic-index", "pharmacokinetics", "qol-pro"], sections: ["supportive-care"] }),
  t({ id: "obstructive-jaundice", name: "Obstructive jaundice and biliary obstruction", category: "Side effects", aka: ["jaundice", "obstructive jaundice", "biliary obstruction", "bile duct obstruction", "cholestasis", "cholangitis", "bilirubin", "elevated bilirubin", "hyperbilirubinaemia", "hyperbilirubinemia", "biliary drainage", "pruritus from cholestasis", "malignant bowel obstruction", "bowel obstruction", "intestinal obstruction", "gastric outlet obstruction", "airway obstruction", "SVC syndrome", "superior vena cava syndrome", "ureteric obstruction", "hydronephrosis"], tldr: "Yellowing of the skin and eyes because a tumour blocks the bile duct, most often pancreatic or bile duct cancer. It causes itching, infection risk and dark urine, and it must be relieved (usually with a stent) before chemotherapy can be given safely.", summary: "Most pancreatic head, distal bile duct and ampullary cancers present with painless jaundice; perihilar cholangiocarcinoma obstructs higher up. Bilirubin above about 1.5× normal precludes most chemotherapy (irinotecan, taxanes and many TKIs are cleared by the liver), so ERCP-placed metal stents or percutaneous drainage come first, with antibiotics for cholangitis. Other malignant obstructions treated by stenting, surgery or radiotherapy include gastric outlet, bowel (managed medically with octreotide and steroids in advanced disease, or surgically), airway, superior vena cava (SVC syndrome) and ureteric obstruction causing hydronephrosis, which impairs cisplatin eligibility in bladder and cervical cancer.", wikipedia: W("Jaundice"), cancers: ["pancreatic", "cholangiocarcinoma"], related: ["biliary-stent", "endoscopy", "whipple", "hepatotoxicity"], sections: ["supportive-care"] }),
  t({ id: "dysphagia", name: "Dysphagia (difficulty swallowing)", category: "Side effects", aka: ["swallowing difficulty", "difficulty swallowing", "swallowing function", "odynophagia", "aspiration pneumonia", "speech and swallowing", "swallowing therapy", "dysphagia-optimised", "DARS", "feeding tube dependence", "tube dependence", "oesophageal obstruction", "esophageal obstruction"], tldr: "Trouble swallowing, either because a tumour narrows the food pipe or throat, or because radiotherapy and surgery to the head, neck or chest have damaged the muscles and nerves that coordinate swallowing. It affects nutrition, dignity and the risk of food going into the lungs.", summary: "The presenting symptom of most oesophageal cancers (palliated by stents, brachytherapy or radiotherapy, and by effective chemotherapy) and the dominant late toxicity of head and neck chemoradiation, where a fifth of survivors remain partly tube-dependent. Dysphagia-optimised IMRT (DARS trial), proton therapy, swallowing exercises during treatment, speech and language therapy and avoiding prophylactic feeding tubes when possible reduce it; the swallowing outcome is a co-primary consideration in HPV-positive oropharynx de-escalation trials. After oesophagectomy, anastomotic strictures and reflux cause further swallowing problems, and dysphagia is a core item in head and neck quality-of-life instruments.", wikipedia: W("Dysphagia"), cancers: ["esophageal", "head-and-neck"], related: ["feeding-tube", "biliary-stent", "oesophagectomy", "mucositis", "late-effects"], sections: ["supportive-care"] }),
];
